window.REFS_BIBLE = {"1 Corinthians 11:23":{"tr":[[23,"Size ilettiğim şeyi ben Rab’den aldım: Rab İsa ele verildiği gece eline ekmek aldı,"]],"en":[[23,"For I have received of the Lord that which also I delivered unto you, that the Lord Jesus, the same night in which he was betrayed, took bread."]]},"1 Corinthians 11:24":{"tr":[[24,"şükredip ekmeği kırdı ve şöyle dedi: “Bu sizin uğrunuza feda edilen bedenimdir. Beni anmak için bunu yapın.”"]],"en":[[24,"And giving thanks, broke, and said: Take ye, and eat: this is my body, which shall be delivered for you: this do for the commemoration of me."]]},"1 Corinthians 11:25":{"tr":[[25,"Aynı şekilde yemekten sonra kâseyi aldı ve şöyle dedi: “Bu kâse benim kanımla gerçekleşen yeni antlaşmadır. Ondan her içtiğinizde beni anmak için bunu yapın.”"]],"en":[[25,"In like manner also the chalice, after he had supped, saying: This chalice is the new testament in my blood: this do ye, as often as you shall drink, for the commemoration of me."]]},"1 Corinthians 11:26":{"tr":[[26,"Çünkü bu ekmeği her yediğinizde ve bu kâseden her içtiğinizde, Rab gelinceye dek O’nun ölümünü duyurmuş olursunuz."]],"en":[[26,"For as often as you shall eat this bread, and drink the chalice, you shall shew the death of the Lord, until he come."]]},"1 Corinthians 11:5":{"tr":[[5,"Başı örtüsüz dua ya da peygamberlik eden her kadın başını küçük düşürür. Bu, saçını kazıtmakla birdir."]],"en":[[5,"But every woman praying or prophesying with her head not covered, disgraceth her head: for it is all one as if she were shaven."]]},"1 Corinthians 12:13":{"tr":[[13,"Yahudi ya da Grek, köle ya da özgür, hepimiz tek bir beden olmak üzere tek Ruh’ta vaftiz edildik ve hepimize aynı Ruh’tan içirildi."]],"en":[[13,"For in one Spirit were we all baptized into one body, whether Jews or Gentiles, whether bond or free; and in one Spirit we have all been made to drink."]]},"1 Corinthians 13:1-3":{"tr":[[1,"İnsanların ve meleklerin diliyle konuşsam, ama sevgim olmasa, ses çıkaran bir bakır ya da ıngırdayan bir zilden farkım kalmaz."],[2,"Peygamberlik yeteneğim olsa, bütün sırları bilsem, her bilgiye sahip olsam, dağları yerinden oynatacak kadar büyük imanım olsa, ama sevgim olmasa, bir hiçim."],[3,"Varımı yoğumu yoksullara dağıtsam, bedenimi yakılmak üzere teslim etsem, ama sevgim olmasa, bunun bana hiçbir yararı olmaz."]],"en":[[1,"If I speak with the tongues of men, and of angels, and have not charity, I am become as sounding brass, or a tinkling cymbal."],[2,"And if I should have prophecy and should know all mysteries, and all knowledge, and if I should have all faith, so that I could remove mountains, and have not charity, I am nothing."],[3,"And if I should distribute all my goods to feed the poor, and if I should deliver my body to be burned, and have not charity, it profiteth me nothing."]]},"1 Corinthians 13:12":{"tr":[[12,"Şimdi bir aynadan bulanık bir görüntü görüyoruz, ama o zaman yüz yüze göreceğiz. Şimdi bilgim sınırlıdır, ama o zaman, Tanrı’nın beni tamamen bildiği gibi ben de her şeyi tamamen bileceğim."]],"en":[[12,"We see now through a glass in a dark manner; but then face to face. Now I know I part; but then I shall know even as I am known."]]},"1 Corinthians 13:5":{"tr":[[5,"Sevgi kaba davranmaz, kendi çıkarını aramaz, kolay kolay öfkelenmez, kötülüğün hesabını tutmaz."]],"en":[[5,"Is not ambitious, seeketh not her own, is not provoked to anger, thinketh no evil;"]]},"1 Corinthians 15:17":{"tr":[[17,"Mesih dirilmediyse imanınız boştur, hâlâ günahlarınızın içindesiniz."]],"en":[[17,"And if Christ be not risen again, your faith is vain, for you are yet in your sins."]]},"1 Corinthians 15:28":{"tr":[[28,"Her şey O’na bağımlı kılındıktan sonra, Oğul da her şeyi kendisine bağımlı kılana bağımlı olacak. Öyle ki, Tanrı her şeyde her şey olsun."]],"en":[[28,"And when all things shall be subdued unto him, then the Son also himself shall be subject unto him that put all things under him, that God may be all in all."]]},"1 Corinthians 15:3-4":{"tr":[[3,"Aldığım bu en önemli bilgiyi size ilettim: Kutsal Yazılar uyarınca Mesih günahlarımız için öldü,"],[4,"gömüldü ve Kutsal Yazılar uyarınca üçüncü gün dirildi."]],"en":[[3,"For I delivered unto you first of all, which I also received: how that Christ died for our sins, according to the scriptures:"],[4,"And that he was buried, and that he rose again the third day, according to the scriptures:"]]},"1 Corinthians 15:3-8":{"tr":[[3,"Aldığım bu en önemli bilgiyi size ilettim: Kutsal Yazılar uyarınca Mesih günahlarımız için öldü,"],[4,"gömüldü ve Kutsal Yazılar uyarınca üçüncü gün dirildi."],[5,"Kefas’a, sonra Onikiler’e göründü."],[6,"Daha sonra beş yüzü aşkın kardeşe aynı anda göründü. Bunların çoğu hâlâ yaşıyor, bazıları ise öldü."],[7,"Sonra Yakup’a, daha sonra bütün elçilere göründü."],[8,"Hepsinden sonra, zamansız doğmuş birine benzeyen bana da göründü."]],"en":[[3,"For I delivered unto you first of all, which I also received: how that Christ died for our sins, according to the scriptures:"],[4,"And that he was buried, and that he rose again the third day, according to the scriptures:"],[5,"And that he was seen by Cephas; and after that by the eleven."],[6,"Then he was seen by more than five hundred brethren at once: of whom many remain until this present, and some are fallen asleep."],[7,"After that, he was seen by James, then by all the apostles."],[8,"And last of all, he was seen also by me, as by one born out of due time."]]},"1 Corinthians 15:32":{"tr":[[32,"Eğer Efes’te sadece insanca bir amaçla vahşi hayvanlarla dövüştüysem, bunun bana ne yararı var? Ölüler dirilmiyorsa, “Yiyip içelim, nasılsa yarın öleceğiz.”"]],"en":[[32,"If (according to man) I fought with beasts at Ephesus, what doth it profit me, if the dead rise not again? Let us eat and drink, for tomorrow we shall die."]]},"1 Corinthians 15:5-6":{"tr":[[5,"Kefas’a, sonra Onikiler’e göründü."],[6,"Daha sonra beş yüzü aşkın kardeşe aynı anda göründü. Bunların çoğu hâlâ yaşıyor, bazıları ise öldü."]],"en":[[5,"And that he was seen by Cephas; and after that by the eleven."],[6,"Then he was seen by more than five hundred brethren at once: of whom many remain until this present, and some are fallen asleep."]]},"1 John 1:5":{"tr":[[5,"İsa Mesih’ten duyup size ilettiğimiz bildiri şudur: Tanrı ışıktır, O’nda hiç karanlık yoktur."]],"en":[[5,"And this is the declaration which we have heard from him, and declare unto you: That God is light, and in him there is no darkness."]]},"1 John 3:8":{"tr":[[8,"Günah işlemeyi sürdüren İblis’tendir. Çünkü İblis başlangıçtan beri günah işlemektedir. Tanrı Oğlu İblis’in işlerini ortadan kaldırmak için göründü."]],"en":[[8,"He that committeth sin is of the devil: for the devil sinneth from the beginning. For this purpose, the Son of God appeared, that he might destroy the works of the devil."]]},"1 John 4:8,16":{"tr":[[8,"Sevmeyen kişi Tanrı’yı tanımaz. Çünkü Tanrı sevgidir."],[16,"Tanrı’nın bize olan sevgisini bildik ve buna iman ettik. Tanrı sevgidir. Sevgide yaşayan Tanrı’da yaşar, Tanrı da onda yaşar."]],"en":[[8,"He that loveth not, knoweth not God: for God is charity."],[16,"And we have known, and have believed the charity, which God hath to us. God is charity: and he that abideth in charity, abideth in God, and God in him."]]},"1 John 4:9":{"tr":[[9,"Tanrı’nın bize olan sevgisi şununla açıkça görüldü: Tanrı, O’nun aracılığıyla yaşayalım diye biricik Oğlu’nu dünyaya gönderdi."]],"en":[[9,"By this hath the charity of God appeared towards us, because God hath sent his only begotten Son into the world, that we may live by him."]]},"1 Kings 18:37":{"tr":[[37,"“Yanıt ver bana, ya RAB, yanıt ver! Öyle ki, bu halk senin, ya RAB, Tanrı olduğunu ve onların yüreklerini yeniden kendine döndürdüğünü bilsin.”"]],"en":[[37,"Hear me, O Lord, hear me: that this people may learn, that thou art the Lord God, and that thou hast turned their heart again."]]},"1 Kings 2:19":{"tr":[[19,"Bat-Şeva Adoniya adına konuşmak için Kral Süleyman’ın yanına gitti. Kral onu karşılamak için ayağa kalktı, önünde eğildi ve tahtına oturdu. Kralın annesi için de bir taht konuldu; o da kralın sağına oturdu."]],"en":[[19,"Then Bethsabee came to king Solomon, to speak to him for Adonias: and the king arose to meet her, and bowed to her, and sat down upon his throne: and a throne was set for the king’s mother, and she sat on his right hand."]]},"1 Peter 1:1":{"tr":[[1,"İsa Mesih’in elçisi Petrus’tan Pontus, Galatya, Kapadokya, Asya İli ve Bitinya’ya dağılmış olan seçilmiş yabancılara selam!"]],"en":[[1,"Peter, an apostle of Jesus Christ, to the strangers dispersed through Pontus, Galatia, Cappadocia, Asia, and Bithynia, elect,"]]},"1 Peter 2:5":{"tr":[[5,"Siz de yaşayan taşlar olarak ruhsal bir ev olmak üzere inşa ediliyorsunuz. Öyle ki, İsa Mesih aracılığıyla Tanrı’nın kabul edeceği ruhsal kurbanlar sunan kutsal bir kâhinler topluluğu olasınız."]],"en":[[5,"Be you also as living stones built up, a spiritual house, a holy priesthood, to offer up spiritual sacrifices, acceptable to God by Jesus Christ."]]},"1 Peter 2:5-9":{"tr":[[5,"Siz de yaşayan taşlar olarak ruhsal bir ev olmak üzere inşa ediliyorsunuz. Öyle ki, İsa Mesih aracılığıyla Tanrı’nın kabul edeceği ruhsal kurbanlar sunan kutsal bir kâhinler topluluğu olasınız."],[6,"Nitekim Kutsal Yazı’da şöyle deniyor: “İşte, Siyon’a seçilmiş, değerli bir köşe taşı koyuyorum. O’na iman eden asla utandırılmayacak.”"],[7,"Siz iman edenler için bu taş değerlidir. İman etmeyenler içinse, “Yapıcıların reddettiği taş, köşenin baş taşı oldu”"],[8,"ve “Bir sürçme taşı, bir tökezleme kayası.” Onlar Tanrı sözüne uymadıkları için sürçerler. Zaten bunun için belirlenmişlerdi."],[9,"Ama siz, sizi karanlıktan şaşılası ışığına çağıran Tanrı’nın erdemlerini duyurmak için seçilmiş soy, krallık kâhinleri, kutsal ulus ve Tanrı’nın öz halkısınız."]],"en":[[5,"Be you also as living stones built up, a spiritual house, a holy priesthood, to offer up spiritual sacrifices, acceptable to God by Jesus Christ."],[6,"Wherefore it is said in the scripture: Behold, I lay in Sion a chief corner stone, elect, precious. And he that shall believe in him, shall not be confounded."],[7,"To you therefore that believe, he is honour: but to them that believe not, the stone which the builders rejected, the same is made the head of the corner:"],[8,"And a stone of stumbling, and a rock of scandal, to them who stumble at the word, neither do believe, whereunto also they are set."],[9,"But you are a chosen generation, a kingly priesthood, a holy nation, a purchased people: that you may declare his virtues, who hath called you out of darkness into his marvellous light:"]]},"1 Thessalonians 4:7":{"tr":[[7,"Çünkü Tanrı bizi pisliğe değil, kutsal yaşama çağırdı."]],"en":[[7,"For God hath not called us unto uncleanness, but unto sanctification."]]},"1 Timothy 2:1-4":{"tr":[[1,"Her şeyden önce şunu öğütlerim: Bütün insanlar için dilekte bulunulsun, dua edilsin, aracılık edilsin ve şükredilsin;"],[2,"krallar ve yetki sahibi olan herkes için de. Öyle ki, tam bir dindarlık ve ağırbaşlılık içinde sakin ve huzurlu bir yaşam sürelim."],[3,"Bu, Kurtarıcımız Tanrı’nın gözünde iyi ve beğenilen bir şeydir."],[4,"O, bütün insanların kurtulmasını ve gerçeğin bilgisine erişmesini ister."]],"en":[[1,"I desire therefore, first of all, that supplications, prayers, intercessions, and thanksgivings be made for all men:"],[2,"For kings, and for all that are in high station: that we may lead a quiet and a peaceable life in all piety and chastity."],[3,"For this is good and acceptable in the sight of God our Saviour,"],[4,"Who will have all men to be saved, and to come to the knowledge of the truth."]]},"1 Timothy 2:12":{"tr":[[12,"Kadının öğretmesine ya da erkeğe egemen olmasına izin vermiyorum. Sessiz kalsın."]],"en":[[12,"But I suffer not a woman to teach, nor to use authority over the man: but to be in silence."]]},"1 Timothy 2:4":{"tr":[[4,"O bütün insanların kurtulup gerçeği tanımaya erişmesini ister."]],"en":[[4,"Who will have all men to be saved, and to come to the knowledge of the truth."]]},"1 Timothy 2:5":{"tr":[[5,"Çünkü tek Tanrı ve Tanrı ile insanlar arasında tek bir aracı vardır: İnsan olan Mesih İsa."]],"en":[[5,"For there is one God, and one mediator of God and men, the man Christ Jesus:"]]},"1 Timothy 3:1-13":{"tr":[[1,"Şu söz güvenilirdir: Bir kimse gözetmen olmayı istiyorsa, iyi bir görev istiyor demektir."],[2,"Gözetmen suçlanacak bir durumda olmamalı; tek karılı, ölçülü, sağduyulu, saygın, konuksever, öğretme yeteneği olan biri olmalı;"],[3,"şarap düşkünü, kavgacı olmamalı; tersine, yumuşak huylu olmalı; kavga etmemeli, para sevgisinden uzak olmalı."],[4,"Kendi ev halkını iyi yönetmeli, çocuklarının saygıyla söz dinlemesini sağlamalı."],[5,"Kendi ev halkını yönetmesini bilmeyen, Tanrı’nın kilisesiyle nasıl ilgilenebilir?"],[6,"Gözetmen imanda yeni olmamalı. Yoksa gurura kapılarak İblis’e verilen cezaya çarptırılabilir."],[7,"Kilise dışındakilerin de iyi tanıklığını kazanmış olmalı. Yoksa rezil olur, İblis’in tuzağına düşer."],[8,"Aynı şekilde diyakonlar da ağırbaşlı olmalı; iki yüzlü, şarap düşkünü, haksız kazanç peşinde olmamalı."],[9,"İmanın sırrını temiz bir vicdanla korumalılar."],[10,"Bunlar da önce denenmeli, sonra kusursuz bulunurlarsa diyakonluk görevine geçmelidir."],[11,"Aynı şekilde kadınlar da ağırbaşlı olmalı; iftiracı değil, ölçülü ve her konuda güvenilir olmalı."],[12,"Diyakonlar tek karılı olmalı, çocuklarını ve ev halkını iyi yönetmeli."],[13,"Çünkü diyakonluk görevini iyi yapanlar kendilerine saygın bir yer ve Mesih İsa’ya olan imanda büyük bir cesaret kazanırlar."]],"en":[[1,"A faithful saying: if a man desire the office of a bishop, he desireth a good work."],[2,"It behoveth therefore a bishop to be blameless, the husband of one wife, sober, prudent, of good behaviour, chaste, given to hospitality, a teacher,"],[3,"Not given to wine, no striker, but modest, not quarrelsome, not covetous, but"],[4,"One that ruleth well his own house, having his children in subjection with all chastity."],[5,"But if a man know not how to rule his own house, how shall he take care of the church of God?"],[6,"Not a neophyte: lest being puffed up with pride, he fall into the judgment of the devil."],[7,"Moreover he must have a good testimony of them who are without: lest he fall into reproach and the snare of the devil."],[8,"Deacons in like manner chaste, not double tongued, not given to much wine, not greedy of filthy lucre:"],[9,"Holding the mystery of faith in a pure conscience."],[10,"And let these also first be proved: and so let them minister, having no crime."],[11,"The women in like manner chaste, not slanderers, but sober, faithful in all things."],[12,"Let deacons be the husbands of one wife: who rule well their children, and their own houses."],[13,"For they that have ministered well, shall purchase to themselves a good degree, and much confidence in the faith which is in Christ Jesus."]]},"2 Chronicles 22:2":{"tr":[[2,"Ahazya kral olduğunda kırk iki yaşındaydı ve Yeruşalim’de bir yıl krallık yaptı. Annesi, Omri’nin torunu Atalya’ydı."]],"en":[[2,"Ochozias was forty-two years old when he began to reign, and he reigned one year in Jerusalem, and the name of his mother was Athalia the daughter of Amri."]]},"2 Corinthians 10:5":{"tr":[[5,"Tasarıları ve Tanrı bilgisine karşı dikilen her engeli yıkıyor, her düşünceyi tutsak edip Mesih’e bağımlı kılıyoruz."]],"en":[[5,"And every height that exhalteth itself against the knowledge of God, and bringing into captivity every understanding unto the obedience of Christ;"]]},"2 Corinthians 5:17":{"tr":[[17,"Bu nedenle, bir kimse Mesih’teyse yeni yaratıktır. Eski şeyler geçmiş, her şey yeni olmuştur."]],"en":[[17,"If then any be in Christ a new creature, the old things are passed away, behold all things are made new."]]},"2 Corinthians 5:8":{"tr":[[8,"Evet, cesaretimiz var. Bedenden uzakta, Rab’bin yanında yaşamayı yeğleriz."]],"en":[[8,"But we are confident, and have a good will to be absent rather from the body, and to be present with the Lord."]]},"2 Kings 8:26":{"tr":[[26,"Ahazya kral olduğunda yirmi iki yaşındaydı ve Yeruşalim’de bir yıl krallık yaptı. Annesi, İsrail Kralı Omri’nin torunu Atalya’ydı."]],"en":[[26,"Ochozias was two and twenty years old when he began to reign, and he reigned one year in Jerusalem: the name of his mother was Athalia the daughter of Amri king of Israel."]]},"2 Maccabees 12:45":{"tr":[[45,"Tanrı yolunda ölenleri bekleyen görkemli ödülü göz önüne alıyorsa, bu kutsal ve dindarca bir düşünceydi. Bu yüzden ölüler günahlarından kurtulsunlar diye onlar için bağışlanma kurbanı sundurdu."]],"en":[[45,"And because he considered that they who had fallen asleep with godliness, had great grace laid up for them."],[46,"It is therefore a holy and wholesome thought to pray for the dead, that they may be loosed from sins."]]},"2 Maccabees 7:28":{"tr":[[28,"“Yalvarırım, oğlum, göğe ve yere bak; onlarda olan her şeyi gör ve Tanrı’nın bunları var olan şeylerden yaratmadığını anla. İnsan soyu da böyle var oldu.”"]],"en":[[28,"I beseech thee, my son, look upon heaven and earth, and all that is in them: and consider that God made them out of nothing, and mankind also:"]]},"2 Peter 1:4":{"tr":[[4,"Tanrı bunlar aracılığıyla bize değerli ve çok büyük vaatler verdi. Öyle ki, bunlar sayesinde dünyadaki kötü arzuların yol açtığı yozlaşmadan kaçıp Tanrısal özyapıya ortak olasınız."]],"en":[[4,"By whom he hath given us most great and precious promises: that by these you may be made partakers of the divine nature: flying the corruption of that concupiscence which is in the world."]]},"2 Peter 3:13":{"tr":[[13,"Ama biz O’nun vaadine uygun olarak, doğruluğun barındığı yeni gökleri ve yeni yeri bekliyoruz."]],"en":[[13,"But we look for new heavens and a new earth according to his promises, in which justice dwelleth."]]},"2 Peter 3:9":{"tr":[[9,"Rab bazılarının gecikme saydığı gibi vaadini yerine getirmekte gecikmez. Kimsenin mahvolmasını istemediği, herkesin tövbe etmesini istediği için size karşı sabırlı davranıyor."]],"en":[[9,"The Lord delayeth not his promise, as some imagine, but dealeth patiently for your sake, not willing that any should perish, but that all should return to penance."]]},"2 Thessalonians 2:15":{"tr":[[15,"Öyleyse, kardeşler, sağlam durun. İster sözle ister mektupla size ilettiğimiz geleneklere sımsıkı bağlı kalın."]],"en":[[14,"Therefore, brethren, stand fast; and hold the traditions which you have learned, whether by word, or by our epistle."]]},"2 Timothy 2:11":{"tr":[[11,"Şu söz güvenilirdir: “O’nunla birlikte öldüysek, O’nunla birlikte yaşayacağız da.”"]],"en":[[11,"A faithful saying: for if we be dead with him, we shall live also with him."]]},"2 Timothy 2:2":{"tr":[[2,"Birçok tanığın önünde benden işittiklerini, başkalarına da öğretmeye yeterli olacak güvenilir insanlara emanet et."]],"en":[[2,"And the things which thou hast heard of me by many witnesses, the same commend to faithful men, who shall be fit to teach others also."]]},"2 Timothy 3:11":{"tr":[[11,"Antakya’da, Konya’da ve Listra’da başıma gelen zulümleri, acıları biliyorsun. Nasıl zulümlere katlandım! Ama Rab beni hepsinden kurtardı."]],"en":[[11,"Persecutions, afflictions: such as came upon me at Antioch, at Iconium, and at Lystra: what persecutions I endured, and out of them all the Lord delivered me."]]},"2 Timothy 4:13":{"tr":[[13,"Gelirken Troas’ta Karpus’un yanında bıraktığım üstlüğü, kitapları ve özellikle parşömenleri getir."]],"en":[[13,"The cloak that I left at Troas, with Carpus, when thou comest, bring with thee, and the books, especially the parchments."]]},"Acts 11:19-26":{"tr":[[19,"İstefanos yüzünden başlayan zulüm nedeniyle dağılanlar Fenike, Kıbrıs ve Antakya’ya kadar gittiler. Tanrı sözünü Yahudilerden başka kimseye duyurmuyorlardı."],[20,"Ama aralarından bazı Kıbrıslılar ve Kireneliler Antakya’ya gelince Grekçe konuşanlara da Rab İsa’yı müjdeleyerek seslendiler."],[21,"Rab’bin eli onlarla birlikteydi. Pek çok kişi iman edip Rab’be döndü."],[22,"Bu haber Yeruşalim’deki kilisenin kulağına ulaştı. Bunun üzerine Barnaba’yı Antakya’ya gönderdiler."],[23,"Barnaba oraya varınca Tanrı’nın lütfunu gördü ve sevindi. Hepsini, yürekten bir bağlılıkla Rab’be sadık kalmaya özendirdi."],[24,"Çünkü Barnaba iyi bir adamdı; Kutsal Ruh’la ve imanla doluydu. Böylece pek çok kişi Rab’be kazanıldı."],[25,"Barnaba Saul’u aramak için Tarsus’a gitti."],[26,"Onu bulunca Antakya’ya getirdi. Bir yıl boyunca kilisede toplanıp büyük bir kalabalığı eğittiler. Öğrencilere ilk kez Antakya’da “Mesihçi” adı verildi."]],"en":[[19,"Now they who had been dispersed by the persecution that arose on occasion of Stephen, went about as far as Phenice and Cyprus and Antioch, speaking the word to none, but to the Jews only."],[20,"But some of them were men of Cyprus and Cyrene, who, when they were entered into Antioch, spoke also to the Greeks, preaching the Lord Jesus."],[21,"And the hand of the Lord was with them: and a great number believing, were converted to the Lord."],[22,"And the tidings came to the ears of the church that was at Jerusalem, touching these things: and they sent Barnabas as far as Antioch."],[23,"Who, when he was come, and had seen the grace of God, rejoiced: and he exhorted them all with purpose of heart to continue in the Lord."],[24,"For he was a good man, and full of the Holy Ghost and of faith. And a great multitude was added to the Lord."],[25,"And Barnabas went to Tarsus to seek Saul: whom, when he had found, he brought to Antioch."],[26,"And they conversed there in the church a whole year; and they taught a great multitude, so that at Antioch the disciples were first named Christians."]]},"Acts 11:25-26":{"tr":[[25,"Barnaba Saul’u aramak için Tarsus’a gitti."],[26,"Onu bulunca Antakya’ya getirdi. Bir yıl boyunca kilisede toplanıp büyük bir kalabalığı eğittiler. Öğrencilere ilk kez Antakya’da “Mesihçi” adı verildi."]],"en":[[25,"And Barnabas went to Tarsus to seek Saul: whom, when he had found, he brought to Antioch."],[26,"And they conversed there in the church a whole year; and they taught a great multitude, so that at Antioch the disciples were first named Christians."]]},"Acts 11:26":{"tr":[[26,"Onu bulunca Antakya’ya getirdi. Bir yıl boyunca kilisede toplanıp büyük bir kalabalığı eğittiler. Öğrencilere ilk kez Antakya’da “Mesihçi” adı verildi."]],"en":[[26,"And they conversed there in the church a whole year; and they taught a great multitude, so that at Antioch the disciples were first named Christians."]]},"Acts 13:1-3":{"tr":[[1,"Antakya’daki kilisede şu peygamberler ve öğretmenler vardı: Barnaba, Nijer denen Şimon, Kireneli Lukius, bölge kralı Hirodes’le birlikte büyümüş olan Menahem ve Saul."],[2,"Bunlar Rab’be tapınıp oruç tutarken Kutsal Ruh, “Barnaba’yla Saul’u, kendilerini çağırdığım iş için bana ayırın” dedi."],[3,"Bunun üzerine oruç tutup dua ettikten sonra ellerini onların üzerine koyup onları yolcu ettiler."]],"en":[[1,"Now there were in the church which was at Antioch, prophets and doctors, among whom was Barnabas, and Simon who was called Niger, and Lucius of Cyrene, and Manahen, who was the foster brother of Herod the tetrarch, and Saul."],[2,"And as they were ministering to the Lord, and fasting, the Holy Ghost said to them: Separate me Saul and Barnabas, for the work whereunto I have taken them."],[3,"Then they, fasting and praying, and imposing their hands upon them, sent them away."]]},"Acts 13:13-14":{"tr":[[13,"Pavlus ve arkadaşları Baf’tan denize açılıp Pamfilya’daki Perge’ye geldiler. Yuhanna ise onlardan ayrılıp Yeruşalim’e döndü."],[14,"Onlar Perge’den geçip Pisidya’daki Antakya’ya vardılar. Şabat Günü havraya girip oturdular."]],"en":[[13,"Now when Paul and they that were with him had sailed from Paphos, they came to Perge in Pamphylia. And John departing from them, returned to Jerusalem."],[14,"But they passing through Perge, came to Antioch in Pisidia: and entering into the synagogue on the sabbath day, they sat down."]]},"Acts 13:14-52":{"tr":[[14,"Onlar Perge’den geçip Pisidya’daki Antakya’ya vardılar. Şabat Günü havraya girip oturdular."],[15,"Kutsal Yasa’dan ve peygamberlerin yazılarından bölümler okunduktan sonra havranın yöneticileri onlara, “Kardeşler, halka söyleyecek bir öğüt sözünüz varsa söyleyin” diye haber gönderdiler."],[16,"Pavlus ayağa kalktı, eliyle bir işaret yaparak şöyle dedi: “Ey İsrail halkı ve Tanrı’dan korkan sizler, dinleyin!"],[17,"Bu İsrail halkının Tanrısı atalarımızı seçti. Mısır’da yabancı olarak yaşarken halkı büyük bir ulus yaptı ve onları güçlü bileğiyle oradan çıkardı."],[18,"Yaklaşık kırk yıl çölde onlara katlandı."],[19,"Kenan ülkesinde yedi ulusu yok ederek onların topraklarını halkına mülk olarak verdi. Bu yaklaşık dört yüz elli yıl sürdü."],[20,"Bundan sonra Tanrı, Peygamber Samuel’in zamanına kadar onlara hâkimler verdi."],[21,"Sonra halk bir kral istedi. Tanrı da onlara kırk yıl krallık yapan Benyamin oymağından Kiş oğlu Saul’u verdi."],[22,"Tanrı Saul’u kaldırdıktan sonra Davut’u onlara kral yaptı. Onun için şu tanıklıkta bulundu: ‘İşay oğlu Davut’u yüreğime göre bir adam olarak buldum. O bütün isteğimi yerine getirecek.’"],[23,"Tanrı, verdiği söze uygun olarak bu adamın soyundan İsrail’e bir Kurtarıcı, İsa’yı gönderdi."],[24,"İsa’nın gelişinden önce Yahya bütün İsrail halkına tövbe vaftizini duyurmuştu."],[25,"Yahya görevini tamamlamak üzereyken, ‘Beni kim sanıyorsunuz? Ben O değilim’ diyordu. ‘Ama bakın, benden sonra biri geliyor. Ben onun ayağındaki çarıkları çözmeye bile layık değilim.’"],[26,"Kardeşler, İbrahim soyunun çocukları ve aranızda bulunan Tanrı’dan korkan sizler! Bu kurtuluş sözü bize gönderildi."],[27,"Çünkü Yeruşalim’de oturanlar ve yöneticileri İsa’yı tanımadılar. O’nu mahkûm ederek her Şabat Günü okunan peygamberlerin sözlerini yerine getirdiler."],[28,"O’nda ölüm cezasını gerektiren hiçbir suç bulamadıkları halde, O’nun öldürülmesini Pilatus’tan istediler."],[29,"O’nunla ilgili yazılmış olanların hepsini yerine getirdikten sonra O’nu çarmıhtan indirip bir mezara koydular."],[30,"Ama Tanrı O’nu ölümden diriltti."],[31,"İsa, kendisiyle birlikte Celile’den Yeruşalim’e gelmiş olanlara günlerce göründü. Şimdi bunlar halkın önünde O’nun tanıklarıdır."],[32,"Biz de size, atalarımıza verilen sözün müjdesini getiriyoruz:"],[33,"Tanrı, İsa’yı dirilterek bu sözü onların çocukları olan bizler için yerine getirdi. Nitekim ikinci mezmurda şöyle yazılmıştır: ‘Sen benim Oğlum’sun, bugün ben seni doğurdum.’"],[34,"Tanrı’nın O’nu bir daha çürümemek üzere ölümden diriltmesiyle ilgili olarak şöyle denmiştir: ‘Davut’a söz verdiğim kutsal ve güvenilir nimetleri size vereceğim.’"],[35,"Bu nedenle başka bir mezmurda da şöyle diyor: ‘Kutsalının çürümesine izin vermeyeceksin.’"],[36,"Davut kendi kuşağında Tanrı’nın amacına hizmet ettikten sonra öldü, atalarının yanına gömüldü ve çürüdü."],[37,"Tanrı’nın dirilttiği İsa ise çürümedi."],[38,"Bu nedenle, kardeşler, bilin ki günahların bağışlanması size O’nun aracılığıyla duyuruluyor."],[39,"Musa’nın Yasası’yla aklanamadığınız her şeyden, iman eden herkes O’nun aracılığıyla aklanır."],[40,"Öyleyse dikkat edin, peygamberlerin söylediği şu söz başınıza gelmesin:"],[41,"‘Bakın, ey alay edenler, şaşın ve yok olun! Çünkü ben sizin günlerinizde bir iş yapacağım. Biri size anlatsa bile inanmayacağınız bir iş!’”"],[42,"Pavlus’la Barnaba havradan çıkarken halk, bir sonraki Şabat Günü de bu konular üzerinde konuşmaları için yalvardı."],[43,"Toplantı dağılınca Yahudilerin ve Yahudiliğe dönmüş Tanrı’ya tapan yabancıların birçoğu Pavlus’la Barnaba’nın ardından gitti. Pavlus’la Barnaba da onlarla konuşarak Tanrı’nın lütfunda kalmaları için onları özendirdiler."],[44,"Sonraki Şabat Günü neredeyse bütün kent Rab’bin sözünü dinlemek için toplandı."],[45,"Ama Yahudiler kalabalığı görünce kıskançlıkla doldular. Pavlus’un söylediklerine karşı çıkıp ona sövdüler."],[46,"Pavlus’la Barnaba ise yüreklilikle şöyle dediler: “Tanrı’nın sözünün önce size bildirilmesi gerekiyordu. Ama siz onu reddettiğinize ve kendinizi sonsuz yaşama layık görmediğinize göre, işte biz de uluslara dönüyoruz."],[47,"Çünkü Rab bize şöyle buyurdu: ‘Seni uluslara ışık yaptım. Öyle ki, dünyanın dört bucağına kurtuluş getiresin.’”"],[48,"Bunu duyan öteki uluslardan olanlar sevindiler ve Rab’bin sözünü yücelttiler. Sonsuz yaşam için belirlenmiş olanların hepsi iman etti."],[49,"Rab’bin sözü bütün bölgeye yayıldı."],[50,"Ama Yahudiler, Tanrı’ya tapan saygın kadınları ve kentin ileri gelenlerini kışkırtıp Pavlus’la Barnaba’ya karşı bir zulüm başlattılar ve onları kendi bölgelerinden kovdular."],[51,"Pavlus’la Barnaba onları protesto etmek için ayaklarının tozunu silkip Konya’ya gittiler."],[52,"Öğrenciler ise sevinçle ve Kutsal Ruh’la dolmuştu."]],"en":[[14,"But they passing through Perge, came to Antioch in Pisidia: and entering into the synagogue on the sabbath day, they sat down."],[15,"And after the reading of the law and the prophets, the rulers of the synagogue sent to them, saying: Ye men, brethren, if you have any word of exhortation to make to the people, speak."],[16,"Then Paul rising up, and with his hand bespeaking silence, said: Ye men of Israel, and you that fear God, give ear."],[17,"The God of the people of Israel chose our fathers, and exalted the people when they were sojourners in the land of Egypt, and with an high arm brought them out from thence,"],[18,"And for the space of forty years endured their manners in the desert."],[19,"And destroying seven nations in the land of Chanaan, divided their land among them, by lot,"],[20,"As it were, after four hundred and fifty years: and after these things, he gave unto them judges, until Samuel the prophet."],[21,"And after that they desired a king: and God gave them Saul the son of Cis, a man of the tribe of Benjamin, forty years."],[22,"And when he had removed him, he raised them up David to be king: to whom giving testimony, he said: I have found David, the son of Jesse, a man according to my own heart, who shall do all my wills."],[23,"Of this man’s seed God according to his promise, hath raised up to Israel a Saviour, Jesus:"],[24,"John first preaching, before his coming, the baptism of penance to all the people of Israel."],[25,"And when John was fulfilling his course, he said: I am not he, whom you think me to be: but behold, there cometh one after me, whose shoes of his feet I am not worthy to loose."],[26,"Men, brethren, children of the stock of Abraham, and whosoever among you fear God, to you the word of this salvation is sent."],[27,"For they that inhabited Jerusalem, and the rulers thereof, not knowing him, nor the voices of the prophets, which are read every sabbath, judging him have fulfilled them."],[28,"And finding no cause of death in him, they desired of Pilate, that they might kill him."],[29,"And when they had fulfilled all things that were written of him, taking him down from the tree, they laid him in a sepulchre."],[30,"But God raised him up from the dead the third day:"],[31,"Who was seen for many days, by them who came up with him from Galilee to Jerusalem, who to this present are his witnesses to the people."],[32,"And we declare unto you, that the promise which was made to our fathers,"],[33,"This same God hath fulfilled to our children, raising up Jesus, as in the second psalm also is written: Thou art my Son, this day have I begotten thee."],[34,"And to shew that he raised him up from the dead, not to return now any more to corruption, he said thus: I will give you the holy things of David faithful."],[35,"And therefore, in another place also, he saith: Thou shalt not suffer thy holy one to see corruption."],[36,"For David, when he had served in his generation, according to the will of God, slept: and was laid unto his fathers, and saw corruption."],[37,"But he whom God hath raised from the dead, saw no corruption."],[38,"Be it known therefore to you, men, brethren, that through him forgiveness of sins is preached to you: and from all the things, from which you could not be justified by the law of Moses."],[39,"In him every one that believeth, is justified."],[40,"Beware, therefore, lest that come upon you which is spoken in the prophets:"],[41,"Behold, ye despisers, and wonder, and perish: for I work a work in your days, a work which you will not believe, if any man shall tell it you."],[42,"And as they went out, they desired them, that on the next sabbath, they would speak unto them these words."],[43,"And when the synagogue was broken up, many of the Jews, and of the strangers who served God, followed Paul and Barnabas: who speaking to them, persuaded them to continue in the grace of God."],[44,"But the next sabbath day, the whole city almost came together, to hear the word of God."],[45,"And the Jews seeing the multitudes, were filled with envy, and contradicted those things which were said by Paul, blaspheming."],[46,"Then Paul and Barnabas said boldly: To you it behoved us first to speak the word of God: but because you reject it, and judge yourselves unworthy of eternal life, behold we turn to the Gentiles."],[47,"For so the Lord hath commanded us: I have set thee to be the light of the Gentiles; that thou mayest be for salvation unto the utmost part of the earth."],[48,"And the Gentiles hearing it, were glad, and glorified the word of the Lord: and as many as were ordained to life everlasting, believed."],[49,"And the word of the Lord was published throughout the whole country."],[50,"But the Jews stirred up religious and honourable women, and the chief men of the city, and raised persecution against Paul and Barnabas: and cast them out of their coasts."],[51,"But they, shaking off the dust of their feet against them, came to Iconium."],[52,"And the disciples were filled with joy and with the Holy Ghost."]]},"Acts 14:1-20":{"tr":[[1,"Konya’da Pavlus’la Barnaba birlikte Yahudi havrasına girip öyle konuştular ki, çok sayıda Yahudi ve Grek iman etti."],[2,"Ama iman etmeyen Yahudiler öbür ulusların halkını kışkırtıp kardeşlere karşı düşmanlık duymalarına yol açtılar."],[3,"Pavlus’la Barnaba uzun süre orada kalıp Rab’le ilgili cesaretle konuştular. Rab onların eliyle belirtiler ve harikalar yaptırarak kendi lütuf sözüne tanıklık etti."],[4,"Kentin halkı ikiye bölündü. Kimi Yahudilerden, kimi elçilerden yana çıktı."],[5,"Öteki uluslardan olanlarla Yahudiler, yöneticileriyle birlikte elçileri aşağılayıp taşlamaya kalkıştılar."],[6,"Elçiler bunu anlayınca Likaonya’nın Listra ve Derbe kentlerine ve çevre bölgelere kaçtılar."],[7,"Oralarda da Müjde’yi yaymaya devam ettiler."],[8,"Listra’da ayakları tutmayan, doğuştan kötürüm, hiç yürümemiş bir adam oturuyordu."],[9,"Adam Pavlus’un söylediklerini dinliyordu. Pavlus ona dikkatle bakınca, iyileşmek için imanı olduğunu gördü."],[10,"Yüksek sesle, “Kalk, ayaklarının üzerinde dik dur!” dedi. Adam sıçrayıp yürümeye başladı."],[11,"Halk Pavlus’un yaptığını görünce Likaonya dilinde, “İlahlar insan kılığına girip aramıza indiler!” diye bağırdı."],[12,"Barnaba’ya Zeus, sözcülüğü o yaptığı için Pavlus’a da Hermes dediler."],[13,"Kentin girişindeki Zeus tapınağının kâhini boğalar ve çelenkler getirip halkla birlikte kentin kapılarında onlara kurban sunmak istedi."],[14,"Bunu duyan elçiler Barnaba ile Pavlus giysilerini yırtıp kalabalığın içine atıldılar ve şöyle bağırdılar:"],[15,"“Ey insanlar, bunu neden yapıyorsunuz? Biz de sizin gibi insanız. Size bu boş şeyleri bırakıp göğü, yeri, denizi ve bunların içindekilerin hepsini yaratan yaşayan Tanrı’ya dönmeniz için Müjde’yi getiriyoruz."],[16,"Tanrı geçmiş kuşaklar boyunca bütün ulusların kendi yollarında yürümelerine izin verdi."],[17,"Yine de kendini tanıksız bırakmadı. İyilik yaparak size gökten yağmur, mevsimlere göre ürün verdi, yüreklerinizi yiyecekle ve sevinçle doldurdu.”"],[18,"Bu sözlerle bile halkı kendilerine kurban sunmaktan zar zor alıkoyabildiler."],[19,"Ama Antakya’dan ve Konya’dan bazı Yahudiler gelip halkı kendi taraflarına çektiler. Pavlus’u taşladılar, öldüğünü sanarak kentin dışına sürüklediler."],[20,"Ama öğrenciler çevresine toplanınca Pavlus kalkıp kente döndü. Ertesi gün Barnaba’yla birlikte Derbe’ye gitti."]],"en":[[1,"And it came to pass in Iconium, that they entered together into the synagogue of the Jews, and so spoke that a very great multitude both of the Jews and of the Greeks did believe."],[2,"But the unbelieving Jews stirred up and incensed the minds of the Gentiles against the brethren."],[3,"A long time therefore they abode there, dealing confidently in the Lord, who gave testimony to the word of his grace, granting signs and wonders to be done by their hands."],[4,"And the multitude of the city was divided; and some of them indeed held with the Jews, but some with the apostles."],[5,"And when there was an assault made by the Gentiles and the Jews with their rulers, to use them contumeliously, and to stone them:"],[6,"They understanding it, fled to Lystra, and Derbe, cities of Lycaonia, and to the whole country round about, and were there preaching the gospel."],[7,"And there sat a certain man at Lystra, impotent in his feet, a cripple from his mother’s womb, who never had walked."],[8,"This same heard Paul speaking. Who looking upon him, and seeing that he had faith to be healed,"],[9,"Said with a loud voice: Stand upright on thy feet. And he leaped up, and walked."],[10,"And when the multitudes had seen what Paul had done, they lifted up their voice in the Lycaonian tongue, saying: The gods are come down to us in the likeness of men;"],[11,"And they called Barnabas, Jupiter: but Paul, Mercury; because he was chief speaker."],[12,"The priest also of Jupiter that was before the city, bringing oxen and garlands before the gate, would have offered sacrifice with the people."],[13,"Which, when the apostles Barnabas and Paul had heard, rending their clothes, they leaped out among the people, crying,"],[14,"And saying: Ye men, why do ye these things? We also are mortals, men like unto you, preaching to you to be converted from these vain things, to the living God, who made the heaven, and the earth, and the sea, and all things that are in them:"],[15,"Who in times past suffered all nations to walk in their own ways."],[16,"Nevertheless he left not himself without testimony, doing good from heaven, giving rains and fruitful seasons, filling our hearts with food and gladness."],[17,"And speaking these things, they scarce restrained the people from sacrificing to them."],[18,"Now there came thither certain Jews from Antioch, and Iconium: and persuading the multitude, and stoning Paul, drew him out of the city, thinking him to be dead."],[19,"But as the disciples stood round about him, he rose up and entered into the city, and the next day he departed with Barnabas to Derbe."]]},"Acts 14:1-6":{"tr":[[1,"Konya’da Pavlus’la Barnaba birlikte Yahudi havrasına girip öyle konuştular ki, çok sayıda Yahudi ve Grek iman etti."],[2,"Ama iman etmeyen Yahudiler öbür ulusların halkını kışkırtıp kardeşlere karşı düşmanlık duymalarına yol açtılar."],[3,"Pavlus’la Barnaba uzun süre orada kalıp Rab’le ilgili cesaretle konuştular. Rab onların eliyle belirtiler ve harikalar yaptırarak kendi lütuf sözüne tanıklık etti."],[4,"Kentin halkı ikiye bölündü. Kimi Yahudilerden, kimi elçilerden yana çıktı."],[5,"Öteki uluslardan olanlarla Yahudiler, yöneticileriyle birlikte elçileri aşağılayıp taşlamaya kalkıştılar."],[6,"Elçiler bunu anlayınca Likaonya’nın Listra ve Derbe kentlerine ve çevre bölgelere kaçtılar."]],"en":[[1,"And it came to pass in Iconium, that they entered together into the synagogue of the Jews, and so spoke that a very great multitude both of the Jews and of the Greeks did believe."],[2,"But the unbelieving Jews stirred up and incensed the minds of the Gentiles against the brethren."],[3,"A long time therefore they abode there, dealing confidently in the Lord, who gave testimony to the word of his grace, granting signs and wonders to be done by their hands."],[4,"And the multitude of the city was divided; and some of them indeed held with the Jews, but some with the apostles."],[5,"And when there was an assault made by the Gentiles and the Jews with their rulers, to use them contumeliously, and to stone them:"],[6,"They understanding it, fled to Lystra, and Derbe, cities of Lycaonia, and to the whole country round about, and were there preaching the gospel."]]},"Acts 14:24-26":{"tr":[[24,"Pisidya’dan geçip Pamfilya’ya vardılar."],[25,"Perge’de Tanrı sözünü yaydıktan sonra Antalya’ya indiler."],[26,"Oradan denize açılıp Antakya’ya döndüler. Şimdi tamamladıkları iş için Tanrı’nın lütfuna emanet edildikleri yer burasıydı."]],"en":[[23,"And passing through Pisidia, they came into Pamphylia."],[24,"And having spoken the word of the Lord in Perge, they went down into Attalia:"],[25,"And thence they sailed to Antioch, from whence they had been delivered to the grace of God, unto the work which they accomplished."]]},"Acts 16:1-2":{"tr":[[1,"Pavlus Derbe’ye, sonra Listra’ya gitti. Orada Timoteos adında bir öğrenci vardı. Annesi iman etmiş bir Yahudi, babası ise Grek’ti."],[2,"Listra ve Konya’daki kardeşler onun hakkında iyi şeyler söylüyorlardı."]],"en":[[1,"And he came to Derbe and Lystra. And behold, there was a certain disciple there named Timothy, the son of a Jewish woman that believed; but his father was a Gentile."],[2,"To this man the brethren that were in Lystra and Iconium, gave a good testimony."]]},"Acts 16:14-15":{"tr":[[14,"Bizi dinleyenlerin arasında Tiyatira kentinden, mor kumaş satıcısı, Tanrı’ya tapan Lidya adında bir kadın vardı. Rab, Pavlus’un söylediklerine kulak vermesi için onun yüreğini açtı."],[15,"Lidya ve ev halkı vaftiz edildikten sonra bize şöyle yalvardı: “Rab’be iman ettiğime inanıyorsanız, gelin, evimde kalın.” Bizi razı etti."]],"en":[[14,"And a certain woman named Lydia, a seller of purple, of the city of Thyatira, one that worshipped God, did hear: whose heart the Lord opened to attend to those things which were said by Paul."],[15,"And when she was baptized, and her household, she besought us, saying: If you have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us."]]},"Acts 16:6":{"tr":[[6,"Kutsal Ruh onların Asya İli’nde Tanrı sözünü yaymalarına izin vermediği için Frikya ve Galatya bölgesinden geçtiler."]],"en":[[6,"And when they had passed through Phrygia, and the country of Galatia, they were forbidden by the Holy Ghost to preach the word in Asia."]]},"Acts 16:8-11":{"tr":[[8,"Misya’dan geçip Troas’a indiler."],[9,"Pavlus gece bir görüm gördü: Makedonyalı bir adam ayakta durmuş, “Makedonya’ya geçip bize yardım et!” diye ona yalvarıyordu."],[10,"Pavlus bu görümü görünce, Tanrı’nın bizi Makedonyalılara Müjde’yi yaymaya çağırdığı sonucuna vararak hemen Makedonya’ya gitmeye hazırlandık."],[11,"Troas’tan denize açılarak doğruca Semadirek Adası’na, ertesi gün de Neapolis’e gittik."]],"en":[[8,"And when they had passed through Mysia, they went down to Troas."],[9,"And a vision was shewed to Paul in the night, which was a man of Macedonia standing and beseeching him, and saying: Pass over into Macedonia, and help us."],[10,"And as soon as he had seen the vision, immediately we sought to go into Macedonia, being assured that God had called us to preach the gospel to them."],[11,"And sailing from Troas, we came with a straight course to Samothracia, and the day following to Neapolis;"]]},"Acts 17:26":{"tr":[[26,"“Tanrı bütün ulusları tek bir insandan türetti; yeryüzünün her yanına yerleştirdi. Belirli zamanları ve oturacakları yerlerin sınırlarını saptadı.”"]],"en":[[26,"And hath made of one, all mankind, to dwell upon the whole face of the earth, determining appointed times, and the limits of their habitation."]]},"Acts 18:23":{"tr":[[23,"Pavlus orada bir süre kaldıktan sonra yola çıktı. Galatya ve Frikya bölgesini baştan başa dolaşarak bütün öğrencileri güçlendirdi."]],"en":[[23,"And after he had spent some time there, he departed, and went through the country of Galatia and Phrygia, in order, confirming all the disciples."]]},"Acts 1:9-11":{"tr":[[9,"Bunları söyledikten sonra İsa, onlar bakarken yukarı alındı ve bir bulut O’nu gözlerinden gizledi."],[10,"O giderken onlar göğe bakakalmışken, beyaz giysili iki adam yanlarında belirdi."],[11,"Adamlar, “Ey Celileliler, neden durmuş göğe bakıyorsunuz?” dediler. “Aranızdan göğe alınan bu İsa, O’nun göğe gidişini nasıl gördünüzse, öyle geri gelecek.”"]],"en":[[9,"And when he had said these things, while they looked on, he was raised up: and a cloud received him out of their sight."],[10,"And while they were beholding him going up to heaven, behold two men stood by them in white garments."],[11,"Who also said: Ye men of Galilee, why stand you looking up to heaven? This Jesus who is taken up from you into heaven, shall so come, as you have seen him going into heaven."]]},"Acts 20:17-38":{"tr":[[17,"Pavlus Milet’ten Efes’e haber gönderip kilisenin ihtiyarlarını çağırttı."],[18,"Onlar yanına gelince şöyle dedi: “Asya İli’ne ayak bastığım ilk günden beri, aranızda bulunduğum süre boyunca nasıl yaşadığımı biliyorsunuz."],[19,"Rab’be tam bir alçakgönüllülükle, gözyaşları içinde ve Yahudilerin düzenlerinden dolayı başıma gelen sıkıntılar içinde hizmet ettim."],[20,"Size yararlı olan hiçbir şeyi bildirmekten çekinmedim. Size hem herkesin önünde hem de evden eve dolaşarak öğrettim."],[21,"Hem Yahudileri hem Grekleri tövbe ederek Tanrı’ya dönmeye ve Rabbimiz İsa’ya iman etmeye çağırdım."],[22,"Şimdi, Ruh’un zorlamasıyla Yeruşalim’e gidiyorum. Orada başıma neler geleceğini bilmiyorum."],[23,"Yalnız şunu biliyorum: Kutsal Ruh her kentte bana tanıklık ederek beni zincirlerin ve sıkıntıların beklediğini söylüyor."],[24,"Ama ben yaşamımı hiç önemsemiyorum. Yeter ki, koşuyu bitireyim ve Rab İsa’dan aldığım görevi, Tanrı’nın lütfunu bildiren Müjde’ye tanıklık etme görevini tamamlayayım."],[25,"Şimdi biliyorum ki, aralarında dolaşıp Tanrı’nın Egemenliği’ni duyurduğum sizlerin hiçbiri artık yüzümü görmeyecek."],[26,"Bu nedenle bugün size şunu açıkça söylüyorum: Hiç kimsenin kanından sorumlu değilim."],[27,"Çünkü Tanrı’nın bütün amacını size bildirmekten çekinmedim."],[28,"Kendinize ve Kutsal Ruh’un sizi gözetmen atadığı bütün sürüye dikkat edin. Tanrı’nın kendi kanıyla satın aldığı kilisesini güdün."],[29,"Biliyorum, ben ayrıldıktan sonra aranıza sürüyü esirgemeyen yırtıcı kurtlar girecek."],[30,"Öğrencileri ardınca sürüklemek için gerçeği çarpıtan kişiler sizin aranızdan bile çıkacak."],[31,"Bu nedenle uyanık durun. Üç yıl boyunca her birinizi gece gündüz gözyaşları içinde uyarmaktan geri durmadığımı unutmayın."],[32,"Şimdi sizi Tanrı’ya ve O’nun lütuf sözüne emanet ediyorum. O söz sizi geliştirmeye ve kutsal kılınmışlar arasında size miras vermeye yeterlidir."],[33,"Kimsenin altınına, gümüşüne ya da giysisine göz dikmedim."],[34,"Kendi gereksinimlerimi ve yanımdakilerin gereksinimlerini bu ellerimle karşıladığımı siz de biliyorsunuz."],[35,"Böyle çalışarak zayıflara yardım etmemiz ve Rab İsa’nın, ‘Vermek, almaktan daha büyük mutluluktur’ diyen sözlerini hatırlamamız gerektiğini her bakımdan size gösterdim.”"],[36,"Pavlus bunları söyledikten sonra diz çöktü ve hepsiyle birlikte dua etti."],[37,"Hepsi hıçkıra hıçkıra ağladı. Pavlus’un boynuna sarılıp onu öptüler."],[38,"En çok üzüldükleri şey, onun, “Artık yüzümü görmeyeceksiniz” demesiydi. Sonra onu gemiye kadar geçirdiler."]],"en":[[17,"And sending from Miletus to Ephesus, he called the ancients of the church."],[18,"And when they were come to him, and were together, he said to them: You know from the first day that I came into Asia, in what manner I have been with you, for all the time,"],[19,"Serving the Lord with all humility, and with tears, and temptations which befell me by the conspiracies of the Jews;"],[20,"How I have kept back nothing that was profitable to you, but have preached it to you, and taught you publicly, and from house to house,"],[21,"Testifying both to Jews and Gentiles penance towards God, and faith in our Lord Jesus Christ."],[22,"And now, behold, being bound in the spirit, I go to Jerusalem: not knowing the things which shall befall me there:"],[23,"Save that the Holy Ghost in every city witnesseth to me, saying: That bands and afflictions wait for me at Jerusalem."],[24,"But I fear none of these things, neither do I count my life more precious than myself, so that I may consummate my course and the ministry of the word which I received from the Lord Jesus, to testify the gospel of the grace of God."],[25,"And now behold, I know that all you, among whom I have gone preaching the kingdom of God, shall see my face no more."],[26,"Wherefore I take you to witness this day, that I am clear from the blood of all men;"],[27,"For I have not spared to declare unto you all the counsel of God."],[28,"Take heed to yourselves, and to the whole flock, wherein the Holy Ghost hath placed you bishops, to rule the church of God, which he hath purchased with his own blood."],[29,"I know that, after my departure, ravening wolves will enter in among you, not sparing the flock."],[30,"And of your own selves shall arise men speaking perverse things, to draw away disciples after them."],[31,"Therefore watch, keeping in memory, that for three years I ceased not, with tears to admonish every one of you night and day."],[32,"And now I commend you to God, and to the word of his grace, who is able to build up, and to give an inheritance among all the sanctified."],[33,"I have not coveted any man’s silver, gold, or apparel, as"],[34,"You yourselves know: for such things as were needful for me and them that are with me, these hands have furnished."],[35,"I have shewed you all things, how that so labouring you ought to support the weak, and to remember the word of the Lord Jesus, how he said: It is a more blessed thing to give, rather than to receive."],[36,"And when he had said these things, kneeling down, he prayed with them all."],[37,"And there was much weeping among them all; and falling on the neck of Paul, they kissed him,"],[38,"Being grieved most of all for the word which he had said, that they should see his face no more. And they brought him on his way to the ship."]]},"Acts 20:6-12":{"tr":[[6,"Biz de Mayasız Ekmek Bayramı’ndan sonra Filipi’den denize açıldık ve beş gün sonra Troas’ta onlara katıldık. Orada yedi gün kaldık."],[7,"Haftanın ilk günü ekmek bölmek için bir araya geldiğimizde Pavlus, ertesi gün yola çıkacağı için topluluğa konuşma yaptı. Konuşmasını gece yarısına kadar sürdürdü."],[8,"Toplandığımız yukarı kattaki odada çok sayıda kandil yanıyordu."],[9,"Pencerede oturan Eftihos adında bir genç, Pavlus’un konuşması uzadıkça derin bir uykuya daldı. Uykuya yenik düşünce üçüncü kattan aşağı düştü. Yerden ölüsünü kaldırdılar."],[10,"Pavlus aşağı inip gencin üzerine kapandı, onu kucaklayarak, “Telaşlanmayın, canı içinde!” dedi."],[11,"Sonra yukarı çıkıp ekmeği böldü ve yedi. Gün ağarıncaya dek uzun süre konuştuktan sonra oradan ayrıldı."],[12,"Genci yaşar durumda eve götürdüler ve büyük teselli buldular."]],"en":[[6,"But we sailed from Philippi after the days of the Azymes, and came to them to Troas in five days, where we abode seven days."],[7,"And on the first day of the week, when we were assembled to break bread, Paul discoursed with them, being to depart on the morrow: and he continued his speech until midnight."],[8,"And there were a great number of lamps in the upper chamber where we were assembled."],[9,"And a certain young man named Eutychus, sitting on the window, being oppressed with a deep sleep, (as Paul was long preaching,) by occasion of his sleep fell from the third loft down, and was taken up dead."],[10,"To whom, when Paul had gone down, he laid himself upon him, and embracing him, said: Be not troubled, for his soul is in him."],[11,"Then going up, and breaking bread and tasting, and having talked a long time to them, until daylight, so he departed."],[12,"And they brought the youth alive, and were not a little comforted."]]},"Acts 21:39":{"tr":[[39,"Pavlus, “Ben Kilikya’nın Tarsus kentinden bir Yahudi’yim, ünlü bir kentin yurttaşıyım” dedi. “Lütfen halka konuşmama izin ver.”"]],"en":[[39,"But Paul said to him: I am a Jew of Tarsus in Cilicia, a citizen of no mean city. And I beseech thee, suffer me to speak to the people."]]},"Acts 22:3":{"tr":[[3,"“Ben Kilikya’nın Tarsus kentinde doğmuş bir Yahudi’yim. Ama bu kentte yetiştim. Gamaliel’in ayaklarının dibinde atalarımızın Yasası’nı titizlikle öğrendim. Bugün sizin hepinizin olduğu gibi, ben de Tanrı için gayretliydim.”"]],"en":[[3,"And he saith: I am a Jew, born at Tarsus in Cilicia, but brought up in this city, at the feet of Gamaliel, taught according to the truth of the law of the fathers, zealous for the law, as also all you are this day:"]]},"Acts 24:15":{"tr":[[15,"“Ben de onların beklediği gibi, doğru olsun olmasın bütün ölülerin dirileceğine ilişkin Tanrı’ya umut bağlamışım.”"]],"en":[[15,"Having hope in God, which these also themselves look for, that there shall be a resurrection of the just and unjust."]]},"Acts 27:5-6":{"tr":[[5,"Kilikya ve Pamfilya açıklarındaki denizi geçerek Likya’daki Mira kentine vardık."],[6,"Yüzbaşı orada İtalya’ya gitmekte olan İskenderiyeli bir gemi bularak bizi ona bindirdi."]],"en":[[5,"And sailing over the sea of Cilicia, and Pamphylia, we came to Lystra, which is in Lycia:"],[6,"And there the centurion finding a ship of Alexandria sailing into Italy, removed us into it."]]},"Acts 2:1-4":{"tr":[[1,"Pentekost günü geldiğinde hepsi bir arada bulunuyordu."],[2,"Birdenbire gökten güçlü bir rüzgârın estiğini andıran bir ses geldi ve oturdukları evi baştan başa doldurdu."],[3,"Ateşten dillere benzeyen, her birinin üzerine dağılıp konan diller gördüler."],[4,"Hepsi Kutsal Ruh’la doldu ve Ruh’un kendilerine verdiği yetiyle başka dillerde konuşmaya başladılar."]],"en":[[1,"And when the days of the Pentecost were accomplished, they were all together in one place:"],[2,"And suddenly there came a sound from heaven, as of a mighty wind coming, and it filled the whole house where they were sitting."],[3,"And there appeared to them parted tongues as it were of fire, and it sat upon every one of them:"],[4,"And they were all filled with the Holy Ghost, and they began to speak with divers tongues, according as the Holy Ghost gave them to speak."]]},"Acts 2:11":{"tr":[[11,"Kritliler ve Araplar; hepimiz Tanrı’nın büyük işlerini onların kendi dillerimizde anlattığını duyuyoruz!”"]],"en":[[11,"Jews also, and proselytes, Cretes, and Arabians: we have heard them speak in our own tongues the wonderful works of God."]]},"Acts 2:42":{"tr":[[42,"Kendilerini elçilerin öğretisine, paydaşlığa, ekmeğin bölünmesine ve dualara adadılar."]],"en":[[42,"And they were persevering in the doctrine of the apostles, and in the communication of the breaking of bread, and in prayers."]]},"Acts 2:9":{"tr":[[9,"“Partlar, Medler, Elamlılar; Mezopotamya, Yahudiye, Kapadokya, Pontus ve Asya İli’nde yaşayanlar,"]],"en":[[9,"Parthians, and Medes, and Elamites, and inhabitants of Mesopotamia, Judea, and Cappadocia, Pontus and Asia,"]]},"Acts 3:15":{"tr":[[15,"“Yaşamın Önderi’ni öldürdünüz. Ama Tanrı O’nu ölümden diriltti. Biz buna tanığız.”"]],"en":[[15,"But the author of life you killed, whom God hath raised from the dead, of which we are witnesses."]]},"Acts 3:18":{"tr":[[18,"“Tanrı bütün peygamberlerinin ağzıyla Mesih’inin acı çekeceğini önceden bildirmişti. Böylece bunu yerine getirdi.”"]],"en":[[18,"But those things which God before had shewed by the mouth of all the prophets, that his Christ should suffer, he hath so fulfilled."]]},"Acts 3:22":{"tr":[[22,"Musa şöyle demişti: “Tanrınız Rab size kendi kardeşleriniz arasından benim gibi bir peygamber çıkaracak. Size ne söylerse, her konuda onu dinleyin.”"]],"en":[[22,"For Moses said: A prophet shall the Lord your God raise up unto you of your brethren, like unto me: him you shall hear according to all things whatsoever he shall speak to you."]]},"Acts 4:12":{"tr":[[12,"“Kurtuluş başka hiç kimsede yoktur. Çünkü gök altında, insanlar arasında bizi kurtarabilecek başka bir ad verilmemiştir.”"]],"en":[[12,"Neither is there salvation in any other. For there is no other name under heaven given to men, whereby we must be saved."]]},"Acts 4:32":{"tr":[[32,"İman edenler topluluğu tek yürek, tek can olmuştu. Hiçbiri malının kendisine ait olduğunu söylemezdi; her şeyleri ortaktı."]],"en":[[32,"And the multitude of believers had but one heart and one soul: neither did any one say that aught of the things which he possessed, was his own; but all things were common unto them."]]},"Acts 5:29":{"tr":[[29,"Petrus ve öbür elçiler şöyle karşılık verdiler: “İnsanlardan çok Tanrı’nın sözünü dinlemek gerekir.”"]],"en":[[29,"But Peter and the apostles answering, said: We ought to obey God, rather than men."]]},"Acts 7:2-4":{"tr":[[2,"İstefanos şöyle dedi: “Kardeşler, babalar, beni dinleyin! Atamız İbrahim, Harran’a yerleşmeden önce, daha Mezopotamya’dayken yüce Tanrı ona göründü"],[3,"ve ona, ‘Ülkeni ve akrabalarını bırakıp sana göstereceğim ülkeye git’ dedi."],[4,"Bunun üzerine İbrahim Kildanilerin ülkesinden çıkıp Harran’a yerleşti. Babası ölünce Tanrı onu oradan şu an yaşadığınız bu ülkeye getirdi.”"]],"en":[[2,"Who said: Ye men, brethren, and fathers, hear. The God of glory appeared to our father Abraham, when he was in Mesopotamia, before he dwelt in Charan."],[3,"And said to him: Go forth out of thy country, and from thy kindred, and come into the land which I shall shew thee."],[4,"Then he went out of the land of the Chaldeans, and dwelt in Charan. And from thence, after his father was dead, he removed him into this land, wherein you now dwell."]]},"Acts 9:11":{"tr":[[11,"Rab ona, “Kalk, Doğru Sokak denen sokağa git” dedi. “Yahuda’nın evinde Tarsuslu Saul adında birini sor. O şu anda dua ediyor.”"]],"en":[[11,"And the Lord said to him: Arise, and go into the street that is called Stait, and seek in the house of Judas, one named Saul of Tarsus. For behold he prayeth."]]},"Colossians 1:14":{"tr":[[14,"O’nda kurtuluşa, yani günahlarımızın bağışlanmasına sahibiz."]],"en":[[14,"In whom we have redemption through his blood, the remission of sins;"]]},"Colossians 1:15":{"tr":[[15,"Görünmez Tanrı’nın görünümü, bütün yaratılışın ilk doğanı O’dur."]],"en":[[15,"Who is the image of the invisible God, the firstborn of every creature:"]]},"Colossians 1:18":{"tr":[[18,"Bedenin, yani kilisenin başı O’dur. Her şeyde üstün olsun diye başlangıç ve ölüler arasından ilk doğan O’dur."]],"en":[[18,"And he is the head of the body, the church, who is the beginning, the firstborn from the dead; that in all things he may hold the primacy:"]]},"Colossians 3:14":{"tr":[[14,"Bütün bunların üstünde, her şeyi yetkin bir birlik içinde birbirine bağlayan sevgiyi giyinin."]],"en":[[14,"But above all these things have charity, which is the bond of perfection:"]]},"Colossians 3:3":{"tr":[[3,"Çünkü siz öldünüz, yaşamınız Mesih’le birlikte Tanrı’da saklıdır."]],"en":[[3,"For you are dead; and your life is hid with Christ in God."]]},"Colossians 4:13-16":{"tr":[[13,"Onun sizin için, Laodikya ve Hierapolis’teki kardeşler için çok emek harcadığına tanıklık ederim."],[14,"Sevgili hekim Luka ile Dimas size selam ediyor."],[15,"Laodikya’daki kardeşlere, Nimfa’ya ve onun evinde toplanan kiliseye selam söyleyin."],[16,"Bu mektup sizde okunduktan sonra Laodikya kilisesinde de okunmasını sağlayın. Laodikya’dan gelecek mektubu da siz okuyun."]],"en":[[13,"For I bear him testimony that he hath much labour for you, and for them that are at Laodicea, and them at Hierapolis."],[14,"Luke, the most dear physician, saluteth you: and Demas."],[15,"Salute the brethren who are at Laodicea, and Nymphas, and the church that is in his house."],[16,"And when this epistle shall have been read with you, cause that it be read also in the church of the Laodiceans: and that you read that which is of the Laodiceans."]]},"Daniel 10:10-19":{"tr":[[10,"Birden bir el bana dokundu ve titreyen dizlerimin, ellerimin üzerine kaldırdı beni."],[11,"Bana, “Ey çok sevilen Daniel, sana söyleyeceğim sözleri anla ve ayağa kalk, çünkü şimdi sana gönderildim” dedi. Bunu söyleyince titreyerek ayağa kalktım."],[12,"Sonra şöyle dedi: “Korkma, Daniel. Anlamaya ve Tanrı’nın önünde alçakgönüllü olmaya yüreğini verdiğin ilk günden beri sözlerin işitildi. Ben de sözlerin yüzünden geldim."],[13,"Ama Pers krallığının önderi yirmi bir gün bana karşı direndi. Sonra baş önderlerden biri olan Mikael yardımıma geldi, çünkü orada Pers krallarıyla yalnız kalmıştım."],[14,"Şimdi son günlerde halkının başına gelecekleri sana anlatmaya geldim. Çünkü bu görüm gelecek günlerle ilgilidir.”"],[15,"Bu sözleri bana söylerken yüzümü yere eğdim ve dilim tutuldu."],[16,"İnsanoğluna benzeyen biri dudaklarıma dokundu. Ağzımı açıp önümde duran kişiye şöyle dedim: “Efendim, bu görüm yüzünden acılar içindeyim, hiç gücüm kalmadı."],[17,"Ben, efendimin kulu, efendimle nasıl konuşabilirim? Gücüm tükendi, nefesim kesildi.”"],[18,"İnsana benzeyen kişi bana yeniden dokunup güç verdi."],[19,"“Ey çok sevilen adam, korkma!” dedi. “Esenlik seninle olsun! Güçlü ol, evet, güçlü ol!” Benimle konuşunca güçlendim ve, “Konuş efendim, çünkü bana güç verdin” dedim."]],"en":[[10,"And behold a hand touched me, and lifted me up upon my knees, and upon the joints of my hands."],[11,"And he said to me: Daniel, thou man of desires, understand the words that I speak to thee, and stand upright: for I am sent now to thee. And when he had said this word to me, I stood trembling."],[12,"And he said to me: Fear not, Daniel: for from the first day that thou didst set thy heart to understand, to afflict thyself in the sight of thy God, thy words have been heard: and I am come for thy words."],[13,"But the prince of the kingdom of the Persians resisted me one and twenty days: and behold Michael, one of the chief princes, came to help me, and I remained there by the king of the Persians."],[14,"But I am come to teach thee what things shall befall thy people in the latter days, for as yet the vision is for days."],[15,"And when he was speaking such words to me, I cast down my countenance to the ground, and held my peace."],[16,"And behold, as it were the likeness of a son of man touched my lips: then I opened my mouth, and spoke, and said to him that stood before me: O my Lord, at the sight of thee my joints are loosed, and no strength hath remained in me."],[17,"And how can the servant of my lord speak with my lord? for no strength remaineth in me, moreover my breath is stopped."],[18,"Therefore he that looked like a man touched me again, and strengthened me."],[19,"And he said: Fear not, O man of desires, peace be to thee: take courage and be strong. And when he spoke to me, I grew strong: and I said: Speak, O my lord, for thou hast strengthened me."]]},"Daniel 7:13-14":{"tr":[[13,"Gece gördüğüm görümlerde şunu gördüm: İnsanoğluna benzeyen biri göklerin bulutlarıyla geliyordu. Yaşlanmayan Varlık’a doğru ilerledi ve onun önüne getirildi."],[14,"Ona egemenlik, yücelik ve krallık verildi. Bütün halklar, uluslar ve her dilden insanlar ona kulluk etti. Onun egemenliği sonsuz bir egemenliktir, hiç geçmeyecek; krallığı hiç yıkılmayacak."]],"en":[[13,"I beheld therefore in the vision of the night, and lo, one like the son of man came with the clouds of heaven, and he came even to the Ancient of days: and they presented him before him."],[14,"And he gave him power, and glory, and a kingdom: and all peoples, tribes and tongues shall serve him: his power is an everlasting power that shall not be taken away: and his kingdom that shall not be destroyed."]]},"Daniel 8:17-18":{"tr":[[17,"Durduğum yere yaklaştı. O gelince korkup yüzüstü yere kapandım. Bana, “Ey insanoğlu, anla ki bu görüm son zamanla ilgilidir” dedi."],[18,"O benimle konuşurken yüzüstü yere yığılıp derin bir uykuya daldım. Ama bana dokunup ayağa kaldırdı."]],"en":[[17,"And he came and stood near where I stood: and when he was come, I fell on my face trembling, and he said to me: Understand, O son of man, for in the time of the end the vision shall be fulfilled."],[18,"And when he spoke to me I fell flat on the ground: and he touched me, and set me upright,"]]},"Deuteronomy 18:15":{"tr":[[15,"Tanrınız RAB size kendi aranızdan, kardeşlerinizin arasından benim gibi bir peygamber çıkaracak. Onu dinleyin."]],"en":[[15,"The Lord thy God will raise up to thee a PROPHET of thy nation and of thy brethren like unto me: him thou shalt hear:"]]},"Deuteronomy 18:18":{"tr":[[18,"Onlara kardeşlerinin arasından senin gibi bir peygamber çıkaracağım. Sözlerimi onun ağzına koyacağım, ona buyurduğum her şeyi onlara söyleyecek."]],"en":[[18,"I will raise them up a prophet out of the midst of their brethren like to thee: and I will put my words in his mouth, and he shall speak to them all that I shall command him."]]},"Deuteronomy 18:20":{"tr":[[20,"Ama benim buyurmadığım bir sözü küstahça benim adımla söyleyen ya da başka ilahların adıyla konuşan peygamber ölecektir."]],"en":[[20,"But the prophet, who being corrupted with pride, shall speak in my name things that I did not command him to say, or in the name of strange gods, shall be slain."]]},"Deuteronomy 24:4":{"tr":[[4,"Onu boşayan ilk kocası, kadın kirlendikten sonra onu yeniden karı olarak alamaz; çünkü bu, RAB’bin gözünde iğrençtir. Tanrınız RAB’bin size mülk olarak vereceği ülkeyi günaha sokmayacaksınız."]],"en":[[4,"The former husband cannot take her again to wife: because she is defiled, and is become abominable before the Lord: lest thou cause thy land to sin, which the Lord thy God shall give thee to possess."]]},"Deuteronomy 2:4-5,9,19":{"tr":[[4,"“Halka şunu buyur: ‘Seir’de yaşayan kardeşleriniz Esav’ın soyundan gelenlerin topraklarından geçeceksiniz. Sizden korkacaklar; ama çok dikkatli olun."],[5,"Onlarla savaşmayın. Çünkü onların topraklarından size bir ayak basacak yer bile vermeyeceğim; Seir Dağı’nı mülk olarak Esav’a verdim.’”"],[9,"RAB bana, “Moavlıları rahatsız etmeyin, onlarla savaşa girmeyin” dedi. “Çünkü topraklarından hiçbir yeri size mülk olarak vermeyeceğim. Ar’ı mülk olarak Lut’un soyuna verdim.”"],[19,"“Ammonluların topraklarına yaklaştığınızda onları rahatsız etmeyin, onlarla savaşmayın. Çünkü Ammonluların topraklarından hiçbir yeri size mülk olarak vermeyeceğim; orayı mülk olarak Lut’un soyuna verdim.”"]],"en":[[4,"And command thou the people, saying: You shall pass by the borders of your brethren the children of Esau, who dwell in Seir, and they will be afraid of you."],[5,"Take ye then good heed that you stir not against them. For I will not give you of their land so much as the step of one foot can tread upon, because I have given mount Seir to Esau, for a possession."],[9,"And the Lord said to me: Fight not against the Moabites, neither go to battle against them: for I will not give thee any of their land, because I have given Ar to the children of Lot in possession."],[19,"And when thou comest nigh the frontiers of the children of Ammon, take heed thou fight not against them, nor once move to battle: for I will not give thee of the land of the children of Ammon, because I have given it to the children of Lot for a possession."]]},"Deuteronomy 5:21":{"tr":[[21,"Komşunun karısına göz dikmeyeceksin. Komşunun evine, tarlasına, erkek ve kadın kölesine, öküzüne, eşeğine, hiçbir şeyine göz dikmeyeceksin.”"]],"en":[[21,"Thou shalt not covet thy neighbour’s wife: nor his house, nor his field, nor his manservant, nor his maidservant, nor his ox, nor his ass, nor any thing that is his."]]},"Deuteronomy 5:6-21":{"tr":[[6,"“Seni Mısır’dan, köle olduğun ülkeden çıkaran Tanrın RAB benim."],[7,"Benden başka tanrın olmayacak."],[8,"Kendine yukarıda gökte, aşağıda yeryüzünde ya da yerin altındaki sularda yaşayan herhangi bir varlığın biçiminde put yapmayacaksın."],[9,"Putların önünde eğilmeyecek, onlara tapmayacaksın. Çünkü ben, Tanrın RAB, kıskanç bir Tanrı’yım. Benden nefret edenlerin babalarının suçunu çocuklarından, üçüncü ve dördüncü kuşaktan sorarım."],[10,"Ama beni seven ve buyruklarımı yerine getirenlerin binlerce kuşağına sevgi gösteririm."],[11,"Tanrın RAB’bin adını boş yere ağzına almayacaksın. Çünkü RAB adını boş yere ağzına alanı cezasız bırakmayacak."],[12,"Tanrın RAB’bin sana buyurduğu gibi Şabat Günü’nü kutsal sayarak koru."],[13,"Altı gün çalışacak, bütün işlerini yapacaksın."],[14,"Ama yedinci gün, Tanrın RAB’bin Şabat Günü’dür. O gün ne sen, ne oğlun, ne kızın, ne erkek ve kadın köle, ne öküzün, ne eşeğin, ne başka hayvanların, ne de kentlerinde yaşayan yabancılar hiçbir iş yapmayacak. Öyle ki, erkek ve kadın kölelerin de senin gibi dinlensin."],[15,"Mısır’da köle olduğunu ve Tanrın RAB’bin seni güçlü eli ve uzanmış koluyla oradan çıkardığını anımsa. Bu yüzden Tanrın RAB Şabat Günü’nü tutmanı buyurdu."],[16,"Tanrın RAB’bin buyurduğu gibi annene babana saygı göster. Öyle ki, Tanrın RAB’bin sana vereceği ülkede ömrün uzun olsun ve iyilik bulasın."],[17,"Adam öldürmeyeceksin."],[18,"Zina etmeyeceksin."],[19,"Çalmayacaksın."],[20,"Komşuna karşı yalan yere tanıklık etmeyeceksin."],[21,"Komşunun karısına göz dikmeyeceksin. Komşunun evine, tarlasına, erkek ve kadın kölesine, öküzüne, eşeğine, hiçbir şeyine göz dikmeyeceksin.”"]],"en":[[6,"I am the Lord thy God, who brought thee out of the land of Egypt, out of the house of bondage."],[7,"Thou shalt not have strange gods in my sight."],[8,"Thou shalt not make to thyself a graven thing, nor the likeness of any things, that are in heaven above, or that are in the earth beneath, or that abide in the waters under the earth."],[9,"Thou shalt not adore them, and thou shalt not serve them. For I am the Lord thy God, a jealous God, visiting the iniquity of the fathers upon their children unto the third and fourth generation, to them that hate me,"],[10,"And shewing mercy unto many thousands, to them that love me, and keep my commandments."],[11,"Thou shalt not take the name of the Lord thy God in vain: for he shall not be unpunished that taketh his name upon a vain thing."],[12,"Observe the day of the sabbath, to sanctify it, as the Lord thy God hath commanded thee."],[13,"Six days shalt thou labour, and shalt do all thy works."],[14,"The seventh is the day of the sabbath, that is, the rest of the Lord thy God. Thou shalt not do any work therein, thou nor thy son nor thy daughter, nor thy manservant nor thy maidservant, nor thy ox, nor thy ass, nor any of thy beasts, nor the stranger that is within thy gates: that thy manservant and thy maidservant may rest, even as thyself."],[15,"Remember that thou also didst serve in Egypt, and the Lord thy God brought thee out from thence with a strong hand, and a stretched out arm. Therefore hath he commanded thee that thou shouldst observe the sabbath day."],[16,"Honour thy father and mother, as the Lord thy God hath commanded thee, that thou mayst live a long time, and it may be well with thee in the land, which the Lord thy God will give thee."],[17,"Thou shalt not kill."],[18,"Neither shalt thou commit adultery."],[19,"And thou shalt not steal."],[20,"Neither shalt thou bear false witness against thy neighbour."],[21,"Thou shalt not covet thy neighbour’s wife: nor his house, nor his field, nor his manservant, nor his maidservant, nor his ox, nor his ass, nor any thing that is his."]]},"Deuteronomy 6:4":{"tr":[[4,"Dinle, ey İsrail! Tanrımız RAB tek RAB’dir."]],"en":[[4,"Hear, O Israel, the Lord our God is one Lord."]]},"Deuteronomy 9:4-5":{"tr":[[4,"Tanrınız RAB o ulusları önünüzden kovduktan sonra içinizden, “RAB bu ülkeyi mülk edinmemiz için doğruluğumuz yüzünden bizi buraya getirdi” demeyin. Hayır, RAB bu ulusları kötülükleri yüzünden önünüzden kovuyor."],[5,"O ülkeyi mülk edinmeye gidiyorsanız, bu sizin doğruluğunuzdan ya da yüreğinizin temizliğinden değil. Tanrınız RAB o ulusları kötülükleri yüzünden ve atalarınız İbrahim’e, İshak’a ve Yakup’a ant içerek verdiği sözü yerine getirmek için önünüzden kovuyor."]],"en":[[4,"Say not in thy heart, when the Lord thy God shall have destroyed them in thy sight: For my justice hath the Lord brought me in to possess this land, whereas these nations are destroyed for their wickedness."],[5,"For it is not for thy justices, and the uprightness of thy heart that thou shalt go in to possess their lands: but because they have done wickedly, they are destroyed at thy coming in: and that the Lord might accomplish his word, which he promised by oath to thy fathers Abraham, Isaac, and Jacob."]]},"Ephesians 1:1":{"tr":[[1,"Tanrı’nın isteğiyle Mesih İsa’nın elçisi olan ben Pavlus’tan Efes’teki kutsallara, Mesih İsa’ya bağlı imanlılara selam!"]],"en":[[1,"Paul, an apostle of Jesus Christ, by the will of God, to all the saints who are at Ephesus, and to the faithful in Christ Jesus."]]},"Ephesians 1:10":{"tr":[[10,"Zaman dolunca yerine getireceği tasarıya göre, yerde ve gökte ne varsa hepsini Mesih’te birleştirecek."]],"en":[[10,"In the dispensation of the fulness of times, to re-establish all things in Christ, that are in heaven and on earth, in him."]]},"Ephesians 2:20":{"tr":[[20,"Temeli elçiler ve peygamberler olan, köşe taşı da Mesih İsa’nın kendisi olan yapının üzerine inşa edildiniz."]],"en":[[20,"Built upon the foundation of the apostles and prophets, Jesus Christ himself being the chief corner stone:"]]},"Ephesians 2:4":{"tr":[[4,"Ama merhameti bol olan Tanrı bizi çok sevdiği için,"]],"en":[[4,"But God, (who is rich in mercy,) for his exceeding charity wherewith he loved us,"]]},"Ephesians 4:13":{"tr":[[13,"Ta ki hepimiz imanda ve Tanrı Oğlu’nu tanımakta birliğe erişelim, olgun insanlığa, Mesih’in doluluğunun ölçüsüne varalım."]],"en":[[13,"Until we all meet into the unity of faith, and of the knowledge of the Son of God, unto a perfect man, unto the measure of the age of the fulness of Christ;"]]},"Ephesians 4:4-6":{"tr":[[4,"Çağrınızın tek umuduna çağrıldığınız gibi tek beden, tek Ruh,"],[5,"tek Rab, tek iman, tek vaftiz,"],[6,"hepsinin üstünde, hepsinin aracılığıyla ve hepsinin içinde olan, hepimizin Babası olan tek Tanrı vardır."]],"en":[[4,"One body and one Spirit; as you are called in one hope of your calling."],[5,"One Lord, one faith, one baptism."],[6,"One God and Father of all, who is above all, and through all, and in us all."]]},"Ephesians 5:21-33":{"tr":[[21,"Mesih’e duyduğunuz saygıdan ötürü birbirinize bağımlı olun."],[22,"Ey kadınlar, Rab’be bağımlı olduğunuz gibi kocalarınıza bağımlı olun."],[23,"Çünkü Mesih kilisenin başı olduğu gibi, koca da karısının başıdır. Mesih bedenin kurtarıcısıdır."],[24,"Kilise Mesih’e bağımlı olduğu gibi, kadınlar da her konuda kocalarına bağımlı olsun."],[25,"Ey kocalar, Mesih kiliseyi nasıl sevip onun uğruna kendini feda ettiyse, siz de karılarınızı öyle sevin."],[26,"Mesih bunu, kiliseyi sözle, suyla yıkayıp temizleyerek kutsal kılmak için yaptı."],[27,"Öyle ki, kiliseyi lekesiz, buruşuksuz ya da buna benzer kusurlardan arınmış olarak, kutsal ve lekesiz olarak yüceliğiyle kendine sunsun."],[28,"Aynı şekilde kocalar da karılarını kendi bedenleri gibi sevmelidir. Karısını seven kendini sever."],[29,"Hiç kimse hiçbir zaman kendi bedeninden nefret etmemiştir. Tersine, Mesih’in kiliseyi beslediği gibi, onu besleyip kollar."],[30,"Çünkü biz O’nun bedeninin üyeleriyiz."],[31,"“Bu nedenle adam annesini babasını bırakıp karısına bağlanacak ve ikisi tek beden olacak.”"],[32,"Bu sır büyüktür, ama ben Mesih’le kiliseden söz ediyorum."],[33,"Ne var ki, her biriniz karısını kendisi gibi sevmeli, kadın da kocasına saygı göstermelidir."]],"en":[[21,"Being subject one to another, in the fear of Christ."],[22,"Let women be subject to their husbands, as to the Lord:"],[23,"Because the husband is the head of the wife, as Christ is the head of the church. He is the saviour of his body."],[24,"Therefore as the church is subject to Christ, so also let the wives be to their husbands in all things."],[25,"Husbands, love your wives, as Christ also loved the church, and delivered himself up for it:"],[26,"That he might sanctify it, cleansing it by the laver of water in the word of life:"],[27,"That he might present it to himself a glorious church, not having spot or wrinkle, or any; such thing; but that it should be holy, and without blemish."],[28,"So also ought men to love their wives as their own bodies. He that loveth his wife, loveth himself."],[29,"For no man ever hated his own flesh; but nourisheth and cherisheth it, as also Christ doth the church:"],[30,"Because we are members of his body, of his flesh, and of his bones."],[31,"For this cause shall a man leave his father and mother, and shall cleave to his wife, and they shall be two in one flesh."],[32,"This is a great sacrament; but I speak in Christ and in the church."],[33,"Nevertheless let every one of you in particular love his wife as himself: and let the wife fear her husband."]]},"Ephesians 5:25":{"tr":[[25,"Ey kocalar, Mesih kiliseyi nasıl sevip onun uğruna kendini feda ettiyse, siz de karılarınızı öyle sevin."]],"en":[[25,"Husbands, love your wives, as Christ also loved the church, and delivered himself up for it:"]]},"Ephesians 5:26":{"tr":[[26,"Mesih bunu, kiliseyi sözle, suyla yıkayıp temizleyerek kutsal kılmak için yaptı."]],"en":[[26,"That he might sanctify it, cleansing it by the laver of water in the word of life:"]]},"Ephesians 5:8":{"tr":[[8,"Bir zamanlar karanlıktınız, ama şimdi Rab’de ışıksınız. Işık çocukları gibi yaşayın."]],"en":[[8,"For you were heretofore darkness, but now light in the Lord. Walk then as children of the light."]]},"Ephesians 6:12":{"tr":[[12,"Çünkü güreşimiz insanlara karşı değil, yönetimlere, hükümranlıklara, bu karanlık dünyanın güçlerine, göksel yerlerdeki kötü ruhsal kuvvetlere karşıdır."]],"en":[[12,"For our wrestling is not against flesh and blood; but against principalities and power, against the rulers of the world of this darkness, against the spirits of wickedness in the high places."]]},"Exodus 20:11":{"tr":[[11,"Çünkü RAB göğü, yeri, denizi ve bunların içindekilerin hepsini altı günde yarattı, yedinci gün dinlendi. Bu nedenle RAB Şabat Günü’nü kutsadı ve onu kutsal kıldı."]],"en":[[11,"For in six days the Lord made heaven and earth, and the sea, and all things that are in them, and rested on the seventh day: therefore the Lord blessed the seventh day, and sanctified it."]]},"Exodus 20:12":{"tr":[[12,"Annene babana saygı göster. Öyle ki, Tanrın RAB’bin sana vereceği ülkede ömrün uzun olsun."]],"en":[[12,"Honour thy father and thy mother, that thou mayest be longlived upon the land which the Lord thy God will give thee."]]},"Exodus 20:14":{"tr":[[14,"Zina etmeyeceksin."]],"en":[[14,"Thou shalt not commit adultery."]]},"Exodus 20:2":{"tr":[[2,"“Seni Mısır’dan, köle olduğun ülkeden çıkaran Tanrın RAB benim."]],"en":[[2,"I am the Lord thy God, who brought thee out of the land of Egypt, out of the house of bondage."]]},"Exodus 20:2-17":{"tr":[[2,"“Seni Mısır’dan, köle olduğun ülkeden çıkaran Tanrın RAB benim."],[3,"Benden başka tanrın olmayacak."],[4,"Kendine yukarıda gökte, aşağıda yeryüzünde ya da yerin altındaki sularda yaşayan herhangi bir varlığın biçiminde put yapmayacaksın."],[5,"Putların önünde eğilmeyecek, onlara tapmayacaksın. Çünkü ben, Tanrın RAB, kıskanç bir Tanrı’yım. Benden nefret edenlerin babalarının suçunu çocuklarından, üçüncü ve dördüncü kuşaktan sorarım."],[6,"Ama beni seven ve buyruklarımı yerine getirenlerin binlerce kuşağına sevgi gösteririm."],[7,"Tanrın RAB’bin adını boş yere ağzına almayacaksın. Çünkü RAB adını boş yere ağzına alanı cezasız bırakmayacak."],[8,"Şabat Günü’nü kutsal sayarak anımsa."],[9,"Altı gün çalışacak, bütün işlerini yapacaksın."],[10,"Ama yedinci gün, Tanrın RAB’bin Şabat Günü’dür. O gün ne sen, ne oğlun, ne kızın, ne erkek ve kadın köle, ne hayvanların, ne de kentlerinde yaşayan yabancılar hiçbir iş yapmayacak."],[11,"Çünkü RAB göğü, yeri, denizi ve bunların içindekilerin hepsini altı günde yarattı, yedinci gün dinlendi. Bu nedenle RAB Şabat Günü’nü kutsadı ve onu kutsal kıldı."],[12,"Annene babana saygı göster. Öyle ki, Tanrın RAB’bin sana vereceği ülkede ömrün uzun olsun."],[13,"Adam öldürmeyeceksin."],[14,"Zina etmeyeceksin."],[15,"Çalmayacaksın."],[16,"Komşuna karşı yalan yere tanıklık etmeyeceksin."],[17,"Komşunun evine göz dikmeyeceksin. Komşunun karısına, erkek ve kadın kölesine, öküzüne, eşeğine, hiçbir şeyine göz dikmeyeceksin.”"]],"en":[[2,"I am the Lord thy God, who brought thee out of the land of Egypt, out of the house of bondage."],[3,"Thou shalt not have strange gods before me."],[4,"Thou shalt not make to thyself a graven thing, nor the likeness of any thing that is in heaven above, or in the earth beneath, nor of those things that are in the waters under the earth."],[5,"Thou shalt not adore them, nor serve them: I am the Lord thy God, mighty, jealous, visiting the iniquity of the fathers upon the children, unto the third and fourth generation of them that hate me:"],[6,"And shewing mercy unto thousands to them that love me, and keep my commandments."],[7,"Thou shalt not take the name of the Lord thy God in vain: for the Lord will not hold him guiltless that shall take the name of the Lord his God in vain."],[8,"Remember that thou keep holy the sabbath day."],[9,"Six days shalt thou labour, and shalt do all thy works."],[10,"But on the seventh day is the sabbath of the Lord thy God: thou shalt do no work on it, thou nor thy son, nor thy daughter, nor thy manservant, nor thy maidservant, nor thy beast, nor the stranger that is within thy gates."],[11,"For in six days the Lord made heaven and earth, and the sea, and all things that are in them, and rested on the seventh day: therefore the Lord blessed the seventh day, and sanctified it."],[12,"Honour thy father and thy mother, that thou mayest be longlived upon the land which the Lord thy God will give thee."],[13,"Thou shalt not kill."],[14,"Thou shalt not commit adultery."],[15,"Thou shalt not steal."],[16,"Thou shalt not bear false witness against thy neighbour."],[17,"Thou shalt not covet thy neighbour’s house: neither shalt thou desire his wife, nor his servant, nor his handmaid, nor his ox, nor his ass, nor any thing that is his."]]},"Exodus 20:3":{"tr":[[3,"Benden başka tanrın olmayacak."]],"en":[[3,"Thou shalt not have strange gods before me."]]},"Exodus 23:7":{"tr":[[7,"“Yalan davadan uzak dur. Suçsuzu ve doğruyu öldürme; çünkü ben kötüyü aklamam.”"]],"en":[[7,"Thou shalt fly lying. The innocent and just person thou shalt not put to death: because I abhor the wicked."]]},"Exodus 25:18-20":{"tr":[[18,"Dövme altından iki kerubi de yap; bunları kefaret kapağının iki ucuna koy."],[19,"Kerubilerin biri bir uçta, öteki öbür uçta olsun."],[20,"Kerubiler kanatlarını açıp kefaret kapağını iki yandan örtsün; yüzleri birbirine dönük olsun, Sandığı örten kefaret kapağına baksınlar."]],"en":[[18,"Thou shalt make also two cherubims of beaten gold, on the two sides of the oracle."],[19,"Let one cherub be on the one side, and the other on the other."],[20,"Let them cover both sides of the propitiatory, spreading their wings, and covering the oracle, and let them look one towards the other, their faces being turned towards the propitiatory wherewith the ark is to be covered."]]},"Exodus 33:11":{"tr":[[11,"RAB, insanın dostuyla konuştuğu gibi Musa’yla yüz yüze konuşurdu. Musa ordugaha dönerdi; ama yardımcısı, Nun oğlu genç Yeşu, çadırdan ayrılmazdı."]],"en":[[11,"And the Lord spoke to Moses face to face, as a man is wont to speak to his friend. And when he returned into the camp, his servant Josue the son of Nun, a young man, departed not from the tabernacle."]]},"Exodus 34:28":{"tr":[[28,"Musa orada RAB’bin yanında kırk gün kırk gece kaldı; ne ekmek yedi ne su içti. Antlaşmanın sözlerini, On Buyruk’u levhalara yazdı."]],"en":[[28,"And he was there with the Lord forty days and forty nights: he neither ate bread nor drank water, and he wrote upon the tables the ten words of the covenant."]]},"Exodus 3:6":{"tr":[[6,"Tanrı, “Ben babanın Tanrısı, İbrahim’in Tanrısı, İshak’ın Tanrısı ve Yakup’un Tanrısı’yım” dedi. Musa yüzünü örttü, çünkü Tanrı’ya bakmaktan korkuyordu."]],"en":[[6,"And he said: I am the God of thy father, the God of Abraham, the God of Isaac, and the God of Jacob. Moses hid his face: for he durst not look at God."]]},"Exodus 4:22":{"tr":[[22,"“Firavuna de ki, ‘RAB şöyle diyor: İsrail benim oğlum, ilk oğlumdur.’”"]],"en":[[22,"And thou shalt say to him: Thus saith the Lord: Israel is my son, my firstborn."]]},"Galatians 1:1-2":{"tr":[[1,"İnsanlar tarafından ya da bir insan aracılığıyla değil, İsa Mesih ve O’nu ölümden dirilten Baba Tanrı aracılığıyla elçi atanan ben Pavlus’tan"],[2,"ve benimle birlikte olan bütün kardeşlerden Galatya’daki kiliselere selam!"]],"en":[[1,"Paul, an apostle, not of men, neither by man, but by Jesus Christ, and God the Father, who raised him from the dead,"],[2,"And all the brethren who are with me, to the churches of Galatia."]]},"Galatians 1:18":{"tr":[[18,"Üç yıl sonra Kefas’la tanışmak için Yeruşalim’e gittim ve on beş gün onunla kaldım."]],"en":[[18,"Then, after three years, I went to Jerusalem, to see Peter, and I tarried with him fifteen days."]]},"Galatians 2:11":{"tr":[[11,"Ama Kefas Antakya’ya geldiğinde, açıkça suçlu olduğu için ona yüz yüze karşı çıktım."]],"en":[[11,"But when Cephas was come to Antioch, I withstood him to the face, because he was to be blamed."]]},"Galatians 2:9":{"tr":[[9,"Kilisenin direkleri sayılan Yakup, Kefas ve Yuhanna bana verilen lütfu tanıyınca, bana ve Barnaba’ya paydaşlık sağ elini uzattılar. Biz öteki uluslara, onlar da sünnetlilere gideceklerdi."]],"en":[[9,"And when they had known the grace that was given to me, James and Cephas and John, who seemed to be pillars, gave to me and Barnabas the right hands of fellowship: that we should go unto the Gentiles, and they unto the circumcision:"]]},"Galatians 4:4-5":{"tr":[[4,"Ama zaman dolunca Tanrı, Yasa’nın buyruğu altında yaşayanları kurtarmak için kadından doğan ve Yasa altında doğan Oğlu’nu gönderdi."],[5,"Öyle ki, Yasa altında olanları kurtarsın ve bizler Tanrı’nın oğulları olalım."]],"en":[[4,"But when the fulness of the time was come, God sent his Son, made of a woman, made under the law:"],[5,"That he might redeem them who were under the law: that we might receive the adoption of sons."]]},"Galatians 4:6":{"tr":[[6,"Oğullar olduğunuz için Tanrı, “Abba, Baba!” diye seslenen Oğlu’nun Ruhu’nu yüreklerimize gönderdi."]],"en":[[6,"And because you are sons, God hath sent the Spirit of his Son into your hearts, crying: Abba, Father."]]},"Galatians 4:7":{"tr":[[7,"Bu nedenle artık köle değil, oğulsun. Oğul olduğun için de Tanrı seni aynı zamanda mirasçı yapmıştır."]],"en":[[7,"Therefore now he is not a servant, but a son. And if a son, an heir also through God."]]},"Galatians 5:1":{"tr":[[1,"Mesih bizi özgür olalım diye özgür kıldı. Bu yüzden sağlam durun, bir daha kölelik boyunduruğuna girmeyin."]],"en":[[1,"Stand fast, and be not held again under the yoke of bondage."]]},"Galatians 5:22":{"tr":[[22,"Oysa Ruh’un meyvesi sevgi, sevinç, esenlik, sabır, şefkat, iyilik, bağlılık,"]],"en":[[22,"But the fruit of the Spirit is, charity, joy, peace, patience, benignity, goodness, longanimity,"]]},"Galatians 5:22-23":{"tr":[[22,"Oysa Ruh’un meyvesi sevgi, sevinç, esenlik, sabır, şefkat, iyilik, bağlılık,"],[23,"yumuşak huyluluk ve özdenetimdir. Bu tür şeylere karşı bir yasa yoktur."]],"en":[[22,"But the fruit of the Spirit is, charity, joy, peace, patience, benignity, goodness, longanimity,"],[23,"Mildness, faith, modesty, continency, chastity. Against such there is no law."]]},"Galatians 5:6":{"tr":[[6,"Çünkü Mesih İsa’da sünnetli olup olmamanın bir önemi yoktur. Önemli olan, sevgi yoluyla etkin olan imandır."]],"en":[[6,"For in Christ Jesus neither circumcision availeth any thing, nor uncircumcision: but faith that worketh by charity."]]},"Galatians 6:2":{"tr":[[2,"Birbirinizin yükünü taşıyın. Böylece Mesih’in Yasası’nı yerine getirmiş olursunuz."]],"en":[[2,"Bear ye one another’s burdens; and so you shall fulfill the law of Christ."]]},"Genesis 11:31-12":{"tr":[],"en":[]},"Genesis 12:3":{"tr":[[3,"“Seni kutsayanları kutsayacak, seni lanetleyeni lanetleyeceğim. Yeryüzündeki bütün halklar senin aracılığınla kutsanacak.”"]],"en":[[3,"I will bless them that bless thee, and curse them that curse thee, and IN THEE shall all the kindred of the earth be blessed:"]]},"Genesis 15:16":{"tr":[[16,"“Senin soyun dördüncü kuşakta buraya geri dönecek, çünkü Amorluların suçu henüz dolmadı.”"]],"en":[[16,"But in the fourth generation they shall return hither: for as yet the iniquities of the Amorrhites are not at the full until this present time."]]},"Genesis 17:5":{"tr":[[5,"“Artık sana Avram denmeyecek, adın İbrahim olacak; çünkü seni birçok ulusun babası yaptım.”"]],"en":[[5,"Neither shall thy name be called any more Abram: but thou shalt be called Abraham: because I have made thee a father of many nations."]]},"Genesis 1:1":{"tr":[[1,"Başlangıçta Tanrı gökleri ve yeri yarattı."]],"en":[[1,"In the beginning God created heaven, and earth."]]},"Genesis 1:26-27":{"tr":[[26,"Tanrı, “İnsanı kendi suretimizde, kendimize benzer biçimde yapalım” dedi. “Denizdeki balıklara, gökteki kuşlara, evcil hayvanlara, bütün yeryüzüne ve yerde sürünen bütün canlılara egemen olsun.”"],[27,"Tanrı insanı kendi suretinde yarattı; onu Tanrı’nın suretinde yarattı; onları erkek ve dişi olarak yarattı."]],"en":[[26,"And he said: Let us make man to our image and likeness: and let him have dominion over the fishes of the sea, and the fowls of the air, and the beasts, and the whole earth, and every creeping creature that moveth upon the earth."],[27,"And God created man to his own image: to the image of God he created him: male and female he created them."]]},"Genesis 1:28":{"tr":[[28,"Tanrı onları kutsadı ve onlara, “Verimli olun, çoğalın, yeryüzünü doldurun ve onu yönetin” dedi. “Denizdeki balıklara, gökteki kuşlara ve yeryüzünde hareket eden bütün canlılara egemen olun.”"]],"en":[[28,"And God blessed them, saying: Increase and multiply, and fill the earth, and subdue it, and rule over the fishes of the sea, and the fowls of the air, and all living creatures that move upon the earth."]]},"Genesis 21:21":{"tr":[[21,"İsmail Paran çölünde yaşadı. Annesi ona Mısır’dan bir kadın aldı."]],"en":[[21,"And he dwelt in the wilderness of Pharan, and his mother took a wife for him out of the land of Egypt."]]},"Genesis 22:12":{"tr":[[12,"Melek, “Çocuğa dokunma, ona hiçbir şey yapma” dedi. “Tanrı’dan korktuğunu şimdi anladım, çünkü oğlunu, biricik oğlunu benden esirgemedin.”"]],"en":[[12,"And he said to him: Lay not thy hand upon the boy, neither do thou any thing to him: now I know that thou fearest God, and hast not spared thy only begotten son for my sake."]]},"Genesis 28:10":{"tr":[[10,"Yakup Beer-Şeva’dan ayrılıp Harran’a doğru yola çıktı."]],"en":[[10,"But Jacob being departed from Bersabee, went on to Haran."]]},"Genesis 29:1-20":{"tr":[[1,"Yakup yoluna devam edip doğu halklarının ülkesine vardı."],[2,"Kırda bir kuyu gördü; yanında üç koyun sürüsü yatıyordu. Sürüler bu kuyudan sulanırdı. Kuyunun ağzındaki taş büyüktü."],[3,"Bütün sürüler orada toplanınca çobanlar taşı kuyunun ağzından yuvarlar, koyunları sular, sonra taşı yeniden kuyunun ağzına yerleştirirlerdi."],[4,"Yakup çobanlara, “Kardeşlerim, nerelisiniz?” diye sordu. “Harranlıyız” dediler."],[5,"Yakup, “Nahor’un torunu Lavan’ı tanır mısınız?” diye sordu. “Tanırız” dediler."],[6,"Yakup, “Sağlığı yerinde mi?” diye sordu. “Yerinde” dediler. “İşte kızı Rahel de koyunlarla geliyor.”"],[7,"Yakup, “Bakın, daha gün ortası, sürüleri toplamanın vakti değil” dedi. “Koyunları sulayın, sonra gidip otlatın.”"],[8,"Çobanlar, “Bütün sürüler toplanmadan, taş kuyunun ağzından yuvarlanmadan olmaz” dediler. “Ancak ondan sonra koyunları sulayabiliriz.”"],[9,"Yakup daha onlarla konuşurken Rahel babasının koyunlarıyla geldi; çünkü koyunları o güdüyordu."],[10,"Yakup dayısı Lavan’ın kızı Rahel’i ve dayısının koyunlarını görünce gidip taşı kuyunun ağzından yuvarladı ve dayısı Lavan’ın koyunlarını suladı."],[11,"Sonra Rahel’i öptü ve hıçkıra hıçkıra ağladı."],[12,"Yakup Rahel’e, babasının akrabası, Rebeka’nın oğlu olduğunu söyledi. Rahel koşup babasına haber verdi."],[13,"Lavan kız kardeşinin oğlu Yakup’un haberini alınca onu karşılamaya koştu; ona sarılıp öptü ve evine getirdi. Yakup da başından geçenlerin hepsini Lavan’a anlattı."],[14,"Lavan ona, “Sen gerçekten benim kanımdan, canımdansın” dedi. Yakup bir ay onun yanında kaldı."],[15,"Lavan Yakup’a, “Akrabam olduğun için bana boşuna mı çalışacaksın?” dedi. “Söyle, ücretin ne olsun?”"],[16,"Lavan’ın iki kızı vardı. Büyüğünün adı Lea, küçüğünün adı Rahel’di."],[17,"Lea’nın gözleri donuktu, Rahel ise hem endamlı hem güzeldi."],[18,"Yakup Rahel’i seviyordu. “Küçük kızın Rahel için sana yedi yıl hizmet ederim” dedi."],[19,"Lavan, “Onu sana vermem başka birine vermemden iyidir” dedi. “Benim yanımda kal.”"],[20,"Yakup Rahel için yedi yıl çalıştı. Ona duyduğu sevgiden ötürü bu yıllar kendisine birkaç gün gibi geldi."]],"en":[[1,"Then Jacob went on in his journey, and came into the east country."],[2,"And he saw a well in the field, and three flocks of sheep lying by it: for the beasts were watered out of it, and the mouth thereof was closed with a great stone."],[3,"And the custom was, when all the sheep were gathered together to roll away the stone, and after the sheep were watered, to put it on the mouth of the well again."],[4,"And he said to the shepherds: Brethren, whence are you? They answered: Of Haran."],[5,"And he asked them, saying: Know you Laban the son of Nachor? They said: We know him."],[6,"He said: Is he in health? He is in health, say they: and behold Rachel his daughter cometh with his flock."],[7,"And Jacob said: There is yet much day remaining, neither is it time to bring the flocks into the folds again: first give the sheep drink, and so lead them back to feed."],[8,"They answered: We cannot, till all the cattle be gathered together, and we remove the stone from the well’s mouth, that we may water the flocks."],[9,"They were yet speaking, and behold Rachel came with her father’s sheep: for she fed the flock."],[10,"And when Jacob saw her, and knew her to be his cousin-german, and that they were the sheep of Laban, his uncle: he removed the stone wherewith the well was closed."],[11,"And having watered the flock, he kissed her: and lifting up his voice, wept."],[12,"And he told her that he was her father’s brother, and the son of Rebecca: but she went in haste and told her father."],[13,"Who, when he heard that Jacob his sister’s son was come, ran forth to meet him; and embracing him, and heartily kissing him, brought him into his house. And when he had heard the causes of his journey,"],[14,"He answered: Thou art my bone and my flesh. And after the days of one month were expired,"],[15,"He said to him: Because thou art my brother, shalt thou serve me without wages? Tell me what wages thou wilt have."],[16,"Now he had two daughters, the name of the elder was Lia: and the younger was called Rachel."],[17,"But Lia was blear eyed: Rachel was well favoured, and of a beautiful countenance."],[18,"And Jacob being in love with her, said: I will serve thee seven years for Rachel thy younger daughter."],[19,"Laban answered: It is better that I give her to thee than to another man; stay with me."],[20,"So Jacob served seven years for Rachel: and they seemed but a few days, because of the greatness of his love."]]},"Genesis 2:23-24":{"tr":[[23,"Adam şöyle dedi: “İşte, bu benim kemiklerimden bir kemik, etimden bir ettir. Ona ‘kadın’ denecek, çünkü o erkekten alındı.”"],[24,"Bu yüzden erkek annesini babasını bırakıp karısına bağlanacak ve ikisi tek beden olacak."]],"en":[[23,"And Adam said: This now is bone of my bones, and flesh of my flesh; she shall be called woman, because she was taken out of man."],[24,"Wherefore a man shall leave father and mother, and shall cleave to his wife: and they shall be two in one flesh."]]},"Genesis 2:24":{"tr":[[24,"Bu yüzden erkek annesini babasını bırakıp karısına bağlanacak ve ikisi tek beden olacak."]],"en":[[24,"Wherefore a man shall leave father and mother, and shall cleave to his wife: and they shall be two in one flesh."]]},"Genesis 3:15":{"tr":[[15,"“Seninle kadın arasına, senin soyunla onun soyu arasına düşmanlık koyacağım. O senin başını ezecek, sen onun topuğunu yaralayacaksın.”"]],"en":[[15,"I will put enmities between thee and the woman, and thy seed and her seed: she shall crush thy head, and thou shalt lie in wait for her heel."]]},"Genesis 3:5":{"tr":[[5,"“Çünkü Tanrı biliyor ki, ondan yediğiniz gün gözleriniz açılacak, iyiyi ve kötüyü bilerek Tanrı gibi olacaksınız.”"]],"en":[[5,"For God doth know that in what day soever you shall eat thereof, your eyes shall be opened: and you shall be as Gods, knowing good and evil."]]},"Genesis 8:4":{"tr":[[4,"Yedinci ayın on yedinci günü gemi Ararat dağlarına oturdu."]],"en":[[4,"And the ark rested in the seventh month, the seven and twentieth day of the month, upon the mountains of Armenia."]]},"Hebrews 10:36":{"tr":[[36,"Tanrı’nın isteğini yerine getirip vaat edileni almanız için dayanmanız gerekiyor."]],"en":[[36,"For patience is necessary for you; that, doing the will of God, you may receive the promise."]]},"Hebrews 12:6-8":{"tr":[[6,"“Çünkü Rab sevdiğini terbiye eder, oğul olarak kabul ettiği herkesi cezalandırır.”"],[7,"Çektiklerinize terbiye olarak katlanın. Tanrı size oğullarına davrandığı gibi davranıyor. Babası tarafından terbiye edilmeyen oğul var mı?"],[8,"Herkesin payına düşen terbiyeden yoksun kalırsanız, gerçek oğullar değil, piçler olursunuz."]],"en":[[6,"For whom the Lord loveth, he chastiseth; and he scourgeth every son whom he receiveth."],[7,"Persevere under discipline. God dealeth with you as with his sons; for what son is there, whom the father doth not correct?"],[8,"But if you be without chastisement, whereof all are made partakers, then are you bastards, and not sons."]]},"Hebrews 1:1-2":{"tr":[[1,"Tanrı geçmişte peygamberler aracılığıyla atalarımıza birçok kez ve çeşitli yollarla seslendi."],[2,"Bu son günlerde ise, her şeyin mirasçısı olarak belirlediği ve aracılığıyla evreni yarattığı Oğlu’nun aracılığıyla bize seslendi."]],"en":[[1,"God, who, at sundry times and in divers manners, spoke in times past to the fathers by the prophets, last of all,"],[2,"In these days hath spoken to us by his Son, whom he hath appointed heir of all things, by whom also he made the world."]]},"Hebrews 1:3":{"tr":[[3,"Oğul, Tanrı yüceliğinin parıltısı ve özünün tıpatıp görünümüdür. Evreni güçlü sözüyle ayakta tutar. Günahları arındırdıktan sonra yücelerde, Yüce Olan’ın sağında oturdu."]],"en":[[3,"Who being the brightness of his glory, and the figure of his substance, and upholding all things by the word of his power, making purgation of sins, sitteth on the right hand of the majesty on high."]]},"Hebrews 2:14":{"tr":[[14,"Çocuklar etten ve kandan olduğu için İsa da onların doğasını paylaştı. Öyle ki, ölüm gücüne sahip olanı, yani İblis’i kendi ölümüyle etkisiz kılsın."]],"en":[[14,"Therefore because the children are partakers of flesh and blood, he also himself in like manner hath been partaker of the same: that, through death, he might destroy him who had the empire of death, that is to say, the devil:"]]},"Hebrews 4:15":{"tr":[[15,"Çünkü başkâhinimiz zayıflıklarımızda bize yakınlık duyamayan biri değildir. Tersine, bizim gibi her konuda denenmiş, ama günah işlememiştir."]],"en":[[15,"For we have not a high priest, who can not have compassion on our infirmities: but one tempted in all things like as we are, without sin."]]},"Hebrews 5:10":{"tr":[[10,"Çünkü Tanrı O’nu Melkisedek düzeninde başkâhin ilan etti."]],"en":[[10,"Called by God a high priest according to the order of Melchisedech."]]},"Hebrews 9:15":{"tr":[[15,"Bu nedenle Mesih yeni bir antlaşmanın aracısıdır. Öyle ki, çağrılmış olanlar vaat edilen sonsuz mirası alsınlar. Çünkü ilk antlaşma döneminde işlenen suçların bedelini ödemek üzere biri öldü."]],"en":[[15,"And therefore he is the mediator of the new testament: that by means of his death, for the redemption of those transgressions, which were under the former testament, they that are called may receive the promise of eternal inheritance."]]},"Isaiah 32:17":{"tr":[[17,"Doğruluğun ürünü esenlik, doğruluğun sonucu da sonsuza dek huzur ve güven olacak."]],"en":[[17,"And the work of justice shall be peace, and the service of justice quietness, and security for ever."]]},"Isaiah 45:22":{"tr":[[22,"“Ey dünyanın dört bucağındakiler, bana dönün ve kurtulun! Çünkü Tanrı benim, başkası yok.”"]],"en":[[22,"Be converted to me, and you shall be saved, all ye ends of the earth: for I am God, and there is no other."]]},"James 1:25":{"tr":[[25,"Ama özgürlük sağlayan yetkin yasayı inceleyen ve ona bağlı kalan, işitip unutan değil de uygulayan kişi, yaptığı işte mutlu olacaktır."]],"en":[[25,"But he that hath looked into the perfect law of liberty, and hath continued therein, not becoming a forgetful hearer, but a doer of the work; this man shall be blessed in his deed."]]},"James 2:26":{"tr":[[26,"Ruhsuz beden nasıl ölüyse, eylemsiz iman da öylece ölüdür."]],"en":[[26,"For even as the body without the spirit is dead; so also faith without works is dead."]]},"James 5:14-15":{"tr":[[14,"Aranızda hasta olan var mı? Kilisenin ihtiyarlarını çağırsın. Onlar da Rab’bin adıyla onu yağla meshedip onun için dua etsinler."],[15,"İmanla edilen dua hastayı iyileştirecek, Rab onu ayağa kaldıracaktır. Eğer günah işlemişse, bağışlanacaktır."]],"en":[[14,"Is any man sick among you? Let him bring in the priests of the church, and let them pray over him, anointing him with oil in the name of the Lord."],[15,"And the prayer of faith shall save the sick man: and the Lord shall raise him up: and if he be in sins, they shall be forgiven him."]]},"James 5:16":{"tr":[[16,"Bu nedenle, iyileşmek için günahlarınızı birbirinize itiraf edin ve birbiriniz için dua edin. Doğru kişinin yalvarışı çok güçlü ve etkilidir."]],"en":[[16,"Confess therefore your sins one to another: and pray one for another, that you may be saved. For the continual prayer of a just man availeth much."]]},"Jeremiah 29:13":{"tr":[[13,"“Beni arayacaksınız ve bütün yüreğinizle aradığınızda beni bulacaksınız.”"]],"en":[[13,"You shall seek me, and shall And me: when you shall seek me with all your heart."]]},"John 10:17":{"tr":[[17,"“Babam beni bu nedenle seviyor: Canımı, yeniden almak üzere veriyorum.”"]],"en":[[17,"Therefore doth the Father love me: because I lay down my life, that I may take it again."]]},"John 10:30":{"tr":[[30,"“Ben ve Baba biriz.”"]],"en":[[30,"I and the Father are one."]]},"John 12:31":{"tr":[[31,"“Şimdi bu dünya yargılanıyor. Şimdi bu dünyanın egemeni dışarı atılacak.”"]],"en":[[31,"Now is the judgment of the world: now shall the prince of this world be cast out."]]},"John 13:1":{"tr":[[1,"Fısıh Bayramı’ndan önceydi. İsa bu dünyadan ayrılıp Baba’nın yanına gideceği saatin geldiğini biliyordu. Dünyada kendisine ait olanları sevmişti, onları sonuna kadar sevdi."]],"en":[[1,"Before the festival day of the pasch, Jesus knowing that his hour was come, that he should pass out of this world to the Father: having loved his own who were in the world, he loved them unto the end."]]},"John 13:34":{"tr":[[34,"Size yeni bir buyruk veriyorum: Birbirinizi sevin. Sizi nasıl sevdiysem, siz de birbirinizi öyle sevin."]],"en":[[34,"A new commandment I give unto you: That you love one another, as I have loved you, that you also love one another."]]},"John 14:6":{"tr":[[6,"İsa ona, “Yol, gerçek ve yaşam benim” dedi. “Benim aracılığım olmadan Baba’ya kimse gelemez.”"]],"en":[[6,"Jesus saith to him: I am the way, and the truth, and the life. No man cometh to the Father, but by me."]]},"John 14:9":{"tr":[[9,"İsa ona şöyle karşılık verdi: “Filipus, bunca zamandır sizinle birlikteyim, beni hâlâ tanımadın mı? Beni görmüş olan Baba’yı görmüştür. Sen nasıl, ‘Baba’yı bize göster’ diyorsun?”"]],"en":[[9,"Jesus saith to him: Have I been so long a time with you; and have you not known me? Philip, he that seeth me seeth the Father also. How sayest thou, Shew us the Father?"]]},"John 15:26":{"tr":[[26,"“Baba’dan size göndereceğim Yardımcı, yani Baba’dan çıkan gerçeğin Ruhu geldiği zaman, bana tanıklık edecek.”"]],"en":[[26,"But when the Paraclete cometh, whom I will send you from the Father, the Spirit of truth, who proceedeth from the Father, he shall give testimony of me."]]},"John 16:13":{"tr":[[13,"“Ama O, yani gerçeğin Ruhu gelince, sizi bütün gerçeğe yöneltecek. Kendiliğinden konuşmayacak, yalnız duyduklarını söyleyecek ve gelecekte olacakları size bildirecek.”"]],"en":[[13,"But when he, the Spirit of truth, is come, he will teach you all truth. For he shall not speak of himself; but what things soever he shall hear, he shall speak; and the things that are to come, he shall shew you."]]},"John 16:24":{"tr":[[24,"“Şimdiye dek benim adımla hiçbir şey dilemediniz. Dileyin, alacaksınız. Öyle ki, sevinciniz tam olsun.”"]],"en":[[24,"Hitherto you have not asked any thing in my name. Ask, and you shall receive; that your joy may be full."]]},"John 17:20-23":{"tr":[[20,"“Yalnız bunlar için değil, bunların sözü aracılığıyla bana iman edecek olanlar için de dua ediyorum."],[21,"Hepsi bir olsun. Baba, sen nasıl bendeysen, ben nasıl sendeysem, onlar da bizde bir olsunlar. Öyle ki, dünya beni senin gönderdiğine iman etsin."],[22,"Bana verdiğin yüceliği onlara verdim. Öyle ki, biz nasıl birsek onlar da bir olsunlar."],[23,"Ben onlarda, sen de bende olmak üzere, tam bir birlik içinde olsunlar. Öyle ki, dünya beni senin gönderdiğini, beni sevdiğin gibi onları da sevdiğini bilsin.”"]],"en":[[20,"And not for them only do I pray, but for them also who through their word shall believe in me;"],[21,"That they all may be one, as thou, Father, in me, and I in thee; that they also may be one in us; that the world may believe that thou hast sent me."],[22,"And the glory which thou hast given me, I have given to them; that they may be one, as we also are one:"],[23,"I in them, and thou in me; that they may be made perfect in one: and the world may know that thou hast sent me, and hast loved them, as thou hast also loved me."]]},"John 17:21":{"tr":[[21,"Hepsi bir olsun. Baba, sen nasıl bendeysen, ben nasıl sendeysem, onlar da bizde bir olsunlar. Öyle ki, dünya beni senin gönderdiğine iman etsin."]],"en":[[21,"That they all may be one, as thou, Father, in me, and I in thee; that they also may be one in us; that the world may believe that thou hast sent me."]]},"John 18:37":{"tr":[[37,"Bunun üzerine Pilatus, “Yani sen bir kralsın, öyle mi?” diye sordu. İsa, “Kral olduğumu sen söylüyorsun” dedi. “Ben gerçeğe tanıklık etmek için doğdum ve bunun için dünyaya geldim. Gerçekten yana olan herkes sesimi dinler.”"]],"en":[[37,"Pilate therefore said to him: Art thou a king then? Jesus answered: Thou sayest that I am a king. For this was I born, and for this came I into the world; that I should give testimony to the truth. Every one that is of the truth, heareth my voice."]]},"John 19:1":{"tr":[[1,"O zaman Pilatus İsa’yı alıp kırbaçlattı."]],"en":[[1,"Then therefore, Pilate took Jesus, and scourged him."]]},"John 19:17":{"tr":[[17,"Kendi haçını taşıyarak, Kafatası denen yere gitti. Bu yere İbranice’de Golgota denir."]],"en":[[17,"And bearing his own cross, he went forth to that place which is called Calvary, but in Hebrew Golgotha."]]},"John 19:25":{"tr":[[25,"İsa’nın çarmıhının yanında annesi, teyzesi, Klopa’nın karısı Meryem ve Mecdelli Meryem duruyordu."]],"en":[[25,"Now there stood by the cross of Jesus, his mother, and his mother’s sister, Mary of Cleophas, and Mary Magdalen."]]},"John 19:27":{"tr":[[27,"Sonra öğrenciye, “İşte, annen!” dedi. Öğrenci o andan itibaren onu kendi evine aldı."]],"en":[[27,"After that, he saith to the disciple: Behold thy mother. And from that hour, the disciple took her to his own."]]},"John 1:1":{"tr":[[1,"Başlangıçta Söz vardı. Söz Tanrı’yla birlikteydi ve Söz Tanrı’ydı."]],"en":[[1,"In the beginning was the Word, and the Word was with God, and the Word was God."]]},"John 1:1-14":{"tr":[[1,"Başlangıçta Söz vardı. Söz Tanrı’yla birlikteydi ve Söz Tanrı’ydı."],[2,"O başlangıçta Tanrı’yla birlikteydi."],[3,"Her şey O’nun aracılığıyla var oldu, var olan hiçbir şey O’nsuz olmadı."],[4,"Yaşam O’ndaydı ve yaşam insanların ışığıydı."],[5,"Işık karanlıkta parlar; karanlık onu alt edemedi."],[6,"Tanrı’nın gönderdiği bir adam vardı; adı Yahya’ydı."],[7,"Yahya tanıklık için, ışığa tanıklık etmek için geldi. Öyle ki, herkes onun aracılığıyla iman etsin."],[8,"Kendisi ışık değildi, ışığa tanıklık etmeye gelmişti."],[9,"Her insanı aydınlatan gerçek ışık dünyaya geliyordu."],[10,"O dünyadaydı; dünya O’nun aracılığıyla var oldu, ama dünya O’nu tanımadı."],[11,"Kendi yurduna geldi, ama kendi halkı O’nu kabul etmedi."],[12,"Kendisini kabul edenlerin hepsine, yani O’nun adına iman edenlere Tanrı’nın çocukları olma hakkını verdi."],[13,"Onlar ne kandan, ne beden isteğinden, ne de insan isteğinden doğdular; tersine, Tanrı’dan doğdular."],[14,"Söz insan oldu ve aramızda yaşadı. O’nun yüceliğini, Baba’dan gelen, lütuf ve gerçekle dolu biricik Oğul’un yüceliğini gördük."]],"en":[[1,"In the beginning was the Word, and the Word was with God, and the Word was God."],[2,"The same was in the beginning with God."],[3,"All things were made by him: and without him was made nothing that was made."],[4,"In him was life, and the life was the light of men."],[5,"And the light shineth in darkness, and the darkness did not comprehend it."],[6,"There was a man sent from God, whose name was John."],[7,"This man came for a witness, to give testimony of the light, that all men might believe through him."],[8,"He was not the light, but was to give testimony of the light."],[9,"That was the true light, which enlighteneth every man that cometh into this world."],[10,"He was in the world, and the world was made by him, and the world knew him not."],[11,"He came unto his own, and his own received him not."],[12,"But as many as received him, he gave them power to be made the sons of God, to them that believe in his name."],[13,"Who are born, not of blood, nor of the will of the flesh, nor of the will of man, but of God."],[14,"And the Word was made flesh, and dwelt among us, (and we saw his glory, the glory as it were of the only begotten of the Father,) full of grace and truth."]]},"John 1:14":{"tr":[[14,"Söz insan oldu ve aramızda yaşadı. O’nun yüceliğini, Baba’dan gelen, lütuf ve gerçekle dolu biricik Oğul’un yüceliğini gördük."]],"en":[[14,"And the Word was made flesh, and dwelt among us, (and we saw his glory, the glory as it were of the only begotten of the Father,) full of grace and truth."]]},"John 1:29":{"tr":[[29,"Ertesi gün Yahya, İsa’nın kendisine doğru geldiğini görünce şöyle dedi: “İşte, dünyanın günahını ortadan kaldıran Tanrı Kuzusu!"]],"en":[[29,"The next day, John saw Jesus coming to him, and he saith: Behold the Lamb of God, behold him who taketh away the sin of the world."]]},"John 1:33":{"tr":[[33,"Ben O’nu tanımıyordum. Ama suyla vaftiz etmek için beni gönderen, bana şöyle dedi: ‘Ruh’un kimin üzerine inip kaldığını görürsen, Kutsal Ruh’la vaftiz eden O’dur.’”"]],"en":[[33,"And I knew him not; but he who sent me to baptize with water, said to me: He upon whom thou shalt see the Spirit descending, and remaining upon him, he it is that baptizeth with the Holy Ghost."]]},"John 20:21":{"tr":[[21,"İsa yine onlara, “Size esenlik olsun!” dedi. “Baba beni gönderdiği gibi, ben de sizi gönderiyorum.”"]],"en":[[21,"He said therefore to them again: Peace be to you. As the Father hath sent me, I also send you."]]},"John 20:21-23":{"tr":[[21,"İsa yine onlara, “Size esenlik olsun!” dedi. “Baba beni gönderdiği gibi, ben de sizi gönderiyorum.”"],[22,"Bunu söyledikten sonra onların üzerine üfledi ve, “Kutsal Ruh’u alın” dedi."],[23,"“Kimin günahlarını bağışlarsanız, bağışlanmış olur; kimin günahlarını bağışlamazsanız, bağışlanmamış olur.”"]],"en":[[21,"He said therefore to them again: Peace be to you. As the Father hath sent me, I also send you."],[22,"When he had said this, he breathed on them; and he said to them: Receive ye the Holy Ghost."],[23,"Whose sins you shall forgive, they are forgiven them; and whose sins you shall retain, they are retained."]]},"John 20:22-23":{"tr":[[22,"Bunu söyledikten sonra onların üzerine üfledi ve, “Kutsal Ruh’u alın” dedi."],[23,"“Kimin günahlarını bağışlarsanız, bağışlanmış olur; kimin günahlarını bağışlamazsanız, bağışlanmamış olur.”"]],"en":[[22,"When he had said this, he breathed on them; and he said to them: Receive ye the Holy Ghost."],[23,"Whose sins you shall forgive, they are forgiven them; and whose sins you shall retain, they are retained."]]},"John 20:6-7":{"tr":[[6,"Arkasından Simun Petrus da geldi ve mezara girdi. Yerde duran keten bezleri gördü."],[7,"İsa’nın başına sarılan peşkir ise keten bezlerle birlikte değil, ayrı bir yerde dürülmüş olarak duruyordu."]],"en":[[6,"Then cometh Simon Peter, following him, and went into the sepulchre, and saw the linen cloths lying,"],[7,"And the napkin that had been about his head, not lying with the linen cloths, but apart, wrapped up into one place."]]},"John 21:25":{"tr":[[25,"İsa’nın yaptığı başka birçok şey daha var. Bunlar tek tek yazılsaydı, sanırım yazılan kitaplar dünyaya sığmazdı."]],"en":[[25,"But there are also many other things which Jesus did; which, if they were written every one, the world itself, I think, would not be able to contain the books that should be written."]]},"John 2:1":{"tr":[[1,"Üçüncü gün Celile’nin Kana köyünde bir düğün vardı. İsa’nın annesi de oradaydı."]],"en":[[1,"And the third day, there was a marriage in Cana of Galilee: and the mother of Jesus was there."]]},"John 2:1-11":{"tr":[[1,"Üçüncü gün Celile’nin Kana köyünde bir düğün vardı. İsa’nın annesi de oradaydı."],[2,"İsa’yla öğrencileri de düğüne çağrılmıştı."],[3,"Şarap tükenince İsa’nın annesi ona, “Şarapları kalmadı” dedi."],[4,"İsa ona, “Kadın, bundan sana ve bana ne?” dedi. “Benim saatim daha gelmedi.”"],[5,"Annesi hizmet edenlere, “Size ne derse onu yapın” dedi."],[6,"Orada, Yahudiler’in arınma geleneği için konmuş, her biri seksen ile yüz yirmi litre alan altı taş küp vardı."],[7,"İsa hizmet edenlere, “Küpleri suyla doldurun” dedi. Küpleri ağızlarına kadar doldurdular."],[8,"Sonra onlara, “Şimdi biraz alın, şölen başkanına götürün” dedi. Onlar da götürdüler."],[9,"Şölen başkanı şaraba dönüşmüş suyu tattı. Bunun nereden geldiğini bilmiyordu, ama suyu çekmiş olan hizmetkârlar biliyordu. Şölen başkanı güveyi çağırıp"],[10,"ona, “Herkes önce iyi şarabı, konuklar iyice içtikten sonra da kötüsünü sunar” dedi. “Ama sen iyi şarabı şimdiye kadar saklamışsın.”"],[11,"İsa bu ilk mucizesini Celile’nin Kana köyünde yaptı ve yüceliğini gösterdi. Öğrencileri de O’na iman ettiler."]],"en":[[1,"And the third day, there was a marriage in Cana of Galilee: and the mother of Jesus was there."],[2,"And Jesus also was invited, and his disciples, to the marriage."],[3,"And the wine failing, the mother of Jesus saith to him: They have no wine."],[4,"And Jesus saith to her: Woman, what is that to me and to thee? my hour is not yet come."],[5,"His mother saith to the waiters: Whatsoever he shall say to you, do ye."],[6,"Now there were set there six waterpots of stone, according to the manner of the purifying of the Jews, containing two or three measures apiece."],[7,"Jesus saith to them: Fill the waterpots with water. And they filled them up to the brim."],[8,"And Jesus saith to them: Draw out now, and carry to the chief steward of the feast. And they carried it."],[9,"And when the chief steward had tasted the water made wine, and knew not whence it was, but the waiters knew who had drawn the water; the chief steward calleth the bridegroom,"],[10,"And saith to him: Every man at first setteth forth good wine, and when men have well drunk, then that which is worse. But thou hast kept the good wine until now."],[11,"This beginning of miracles did Jesus in Cana of Galilee; and manifested his glory, and his disciples believed in him."]]},"John 2:16":{"tr":[[16,"Güvercin satanlara, “Bunları buradan çıkarın! Babamın evini pazar yerine çevirmeyin!” dedi."]],"en":[[16,"And to them that sold doves he said: Take these things hence, and make not the house of my Father a house of traffic."]]},"John 2:5":{"tr":[[5,"Annesi hizmet edenlere, “Size ne derse onu yapın” dedi."]],"en":[[5,"His mother saith to the waiters: Whatsoever he shall say to you, do ye."]]},"John 3:13":{"tr":[[13,"Gökten inmiş olan İnsanoğlu’ndan başka hiç kimse göğe çıkmamıştır."]],"en":[[13,"And no man hath ascended into heaven, but he that descended from heaven, the Son of man who is in heaven."]]},"John 3:16-17":{"tr":[[16,"Çünkü Tanrı dünyayı o kadar çok sevdi ki, biricik Oğlu’nu verdi. Öyle ki, O’na iman edenlerin hiçbiri mahvolmasın, hepsi sonsuz yaşama kavuşsun."],[17,"Tanrı Oğlu’nu dünyaya, dünyayı yargılamak için değil, dünya O’nun aracılığıyla kurtulsun diye gönderdi."]],"en":[[16,"For God so loved the world, as to give his only begotten Son; that whosoever believeth in him, may not perish, but may have life everlasting."],[17,"For God sent not his Son into the world, to judge the world, but that the world may be saved by him."]]},"John 4:24":{"tr":[[24,"“Tanrı ruhtur, O’na tapanlar ruhta ve gerçekte tapmalıdır.”"]],"en":[[24,"God is a spirit; and they that adore him, must adore him in spirit and in truth."]]},"John 5:29":{"tr":[[29,"“İyilik yapmış olanlar yaşamak üzere, kötülük yapmış olanlar yargılanmak üzere dirilecekler.”"]],"en":[[29,"And they that have done good things, shall come forth unto the resurrection of life; but they that have done evil, unto the resurrection of judgment."]]},"John 6:55":{"tr":[[55,"“Çünkü benim bedenim gerçek yiyecek, kanım gerçek içecektir.”"]],"en":[[56,"For my flesh is meat indeed: and my blood is drink indeed."]]},"John 6:66":{"tr":[[66,"Bunun üzerine öğrencilerinin birçoğu geri çekildi ve artık onunla dolaşmaz oldu."]],"en":[[67,"After this many of his disciples went back; and walked no more with him."]]},"John 8:28":{"tr":[[28,"Bunun üzerine İsa onlara şöyle dedi: “İnsanoğlu’nu yukarı kaldırdığınızda benim O olduğumu, kendiliğimden hiçbir şey yapmadığımı, ancak Baba’nın bana öğrettiklerini söylediğimi anlayacaksınız.”"]],"en":[[28,"Jesus therefore said to them: When you shall have lifted up the Son of man, then shall you know, that I am he, and that I do nothing of myself, but as the Father hath taught me, these things I speak:"]]},"John 8:36":{"tr":[[36,"“Eğer Oğul sizi özgür kılarsa, gerçekten özgür olursunuz.”"]],"en":[[36,"If therefore the son shall make you free, you shall be free indeed."]]},"John 8:44":{"tr":[[44,"“Siz babanız İblis’tensiniz ve babanızın arzularını yerine getirmek istiyorsunuz. O başlangıçtan beri katildi. Gerçeğe bağlı kalmadı, çünkü onda gerçek yoktur. Yalan söylediği zaman kendi doğasına uygun konuşur. Çünkü o yalancı ve yalanın babasıdır.”"]],"en":[[44,"You are of your father the devil, and the desires of your father you will do. He was a murderer from the beginning, and he stood not in the truth; because truth is not in him. When he speaketh a lie, he speaketh of his own: for he is a liar, and the father thereof."]]},"John 8:58":{"tr":[[58,"İsa, “Size doğrusunu söyleyeyim, İbrahim doğmadan önce BEN VARIM” dedi."]],"en":[[58,"Jesus said to them: Amen, amen I say to you, before Abraham was made, I am."]]},"Luke 10:30-35":{"tr":[[30,"İsa şöyle karşılık verdi: “Bir adam Yeruşalim’den Eriha’ya inerken haydutların eline düştü. Haydutlar onun giysilerini soydular, onu dövüp yarı ölü bırakarak gittiler."],[31,"Rastlantı sonucu o yoldan bir kâhin geçiyordu. Adamı görünce yolun öbür yanından geçip gitti."],[32,"Bir Levili de oraya gelip adamı görünce yolun öbür yanından geçip gitti."],[33,"Ama yolculuk eden bir Samiriyeli, adamın bulunduğu yere geldi. Onu görünce yüreği sızladı."],[34,"Yanına gidip yaralarına zeytinyağıyla şarap dökerek sardı. Sonra onu kendi hayvanına bindirip bir hana getirdi ve onunla ilgilendi."],[35,"Ertesi gün iki dinar çıkarıp hancıya verdi. ‘Ona iyi bak’ dedi. ‘Bundan fazla ne harcarsan, dönüşümde sana öderim.’”"]],"en":[[30,"And Jesus answering, said: A certain man went down from Jerusalem to Jericho, and fell among robbers, who also stripped him, and having wounded him went away, leaving him half dead."],[31,"And it chanced, that a certain priest went down the same way: and seeing him, passed by."],[32,"In like manner also a Levite, when he was near the place and saw him, passed by."],[33,"But a certain Samaritan being on his journey, came near him; and seeing him, was moved with compassion."],[34,"And going up to him, bound up his wounds, pouring in oil and wine: and setting him upon his own beast, brought him to an inn, and took care of him."],[35,"And the next day he took out two pence, and gave to the host, and said: Take care of him; and whatsoever thou shalt spend over and above, I, at my return, will repay thee."]]},"Luke 11:1":{"tr":[[1,"İsa bir yerde dua ediyordu. Duasını bitirince öğrencilerinden biri, “Ya Rab, Yahya’nın kendi öğrencilerine öğrettiği gibi sen de bize dua etmeyi öğret” dedi."]],"en":[[1,"And it came to pass, that as he was in a certain place praying, when he ceased, one of his disciples said to him: Lord, teach us to pray, as John also taught his disciples."]]},"Luke 11:5-8":{"tr":[[5,"İsa onlara şöyle dedi: “Diyelim ki, birinizin bir dostu var. Gece yarısı ona gidip, ‘Dostum, bana ödünç üç ekmek ver."],[6,"Yolculuk eden bir dostum yanıma geldi, ona sunacak bir şeyim yok’ diyorsunuz."],[7,"O da içeriden, ‘Beni rahatsız etme’ diye karşılık veriyor. ‘Kapı çoktan kilitlendi, çocuklarım da benimle yatakta. Kalkıp sana bir şey veremem.’"],[8,"Size şunu söyleyeyim, dostu olduğu için kalkıp ona vermese bile, ısrarı yüzünden kalkıp ne kadar gerekiyorsa verecektir.”"]],"en":[[5,"And he said to them: Which of you shall have a friend, and shall go to him at midnight, and shall say to him: Friend, lend me three loaves,"],[6,"Because a friend of mine is come off his journey to me, and I have not what to set before him."],[7,"And he from within should answer, and say: Trouble me not, the door is now shut, and my children are with me in bed; I cannot rise and give thee."],[8,"Yet if he shall continue knocking, I say to you, although he will not rise and give him, because he is his friend; yet, because of his importunity, he will rise, and give him as many as he needeth."]]},"Luke 12:16-21":{"tr":[[16,"İsa onlara şu benzetmeyi anlattı: “Zengin bir adamın toprakları bol ürün vermişti."],[17,"Adam kendi kendine, ‘Ne yapayım? Ürünlerimi toplayacak yerim yok’ diye düşündü."],[18,"‘Şunu yapacağım’ dedi. ‘Ambarlarımı yıkıp daha büyüklerini yapacağım. Bütün tahılımı ve mallarımı oraya toplayacağım."],[19,"Sonra kendime, ey canım, uzun yıllar yetecek kadar birikmiş malın var. Dinlen, ye, iç, keyfine bak diyeceğim.’"],[20,"Ama Tanrı ona, ‘Ey akılsız adam!’ dedi. ‘Bu gece canın senden istenecek. Hazırladığın bunca şey kime kalacak?’"],[21,"Kendisi için hazine biriktiren, ama Tanrı katında zengin olmayan kişinin durumu böyledir.”"]],"en":[[16,"And he spoke a similitude to them, saying: The land of a certain rich man brought forth plenty of fruits."],[17,"And he thought within himself, saying: What shall I do, because I have no room where to bestow my fruits?"],[18,"And he said: This will I do: I will pull down my barns, and will build greater; and into them will I gather all things that are grown to me, and my goods."],[19,"And I will say to my soul: Soul, thou hast much goods laid up for many years take thy rest; eat, drink, make good cheer."],[20,"But God said to him: Thou fool, this night do they require thy soul of thee: and whose shall those things be which thou hast provided?"],[21,"So is he that layeth up treasure for himself, and is not rich towards God."]]},"Luke 12:35-40":{"tr":[[35,"“Belleriniz kuşanılmış, kandilleriniz yanar durumda olsun."],[36,"Düğünden dönecek efendilerini bekleyen, efendileri gelip kapıyı çalınca ona hemen kapıyı açacak kişiler gibi olun."],[37,"Efendileri geldiğinde uyanık bulacağı kölelere ne mutlu! Size doğrusunu söyleyeyim, efendileri beline kuşağını bağlayıp onları sofraya oturtacak ve gelip onlara hizmet edecek."],[38,"Efendileri ister gece yarısı, ister sabaha karşı gelsin, onları uyanık bulursa, ne mutlu onlara!"],[39,"Şunu bilin ki, ev sahibi hırsızın hangi saatte geleceğini bilseydi, evinin soyulmasına izin vermezdi."],[40,"Siz de hazır olun. Çünkü İnsanoğlu beklemediğiniz bir saatte gelecek.”"]],"en":[[35,"Let your loins be girt, and lamps burning in your hands."],[36,"And you yourselves like to men who wait for their lord, when he shall return from the wedding; that when he cometh and knocketh, they may open to him immediately."],[37,"Blessed are those servants, whom the Lord when he cometh, shall find watching. Amen I say to you, that he will gird himself, and make them sit down to meat, and passing will minister unto them."],[38,"And if he shall come in the second watch, or come in the third watch, and find them so, blessed are those servants."],[39,"But this know ye, that if the householder did know at what hour the thief would come, he would surely watch, and would not suffer his house to be broken open."],[40,"Be you then also ready: for at what hour you think not, the Son of man will come."]]},"Luke 12:42-48":{"tr":[[42,"Rab şöyle dedi: “Efendisinin, hizmetkârlarının başına atayacağı, onlara zamanında yiyecek paylarını verecek güvenilir ve akıllı kâhya kimdir?"],[43,"Efendisi geldiğinde onu böyle yaparken bulacağı köleye ne mutlu!"],[44,"Size doğrusunu söyleyeyim, efendisi onu bütün malının başına geçirecek."],[45,"Ama o köle içinden, ‘Efendim gecikiyor’ deyip erkek ve kadın hizmetkârları dövmeye, yiyip içip sarhoş olmaya başlarsa,"],[46,"o kölenin efendisi, beklemediği günde ve bilmediği saatte gelecek. Onu şiddetle cezalandıracak ve imansızların arasına atacak."],[47,"Efendisinin isteğini bildiği halde hazırlık yapmayan, efendisinin isteğini yerine getirmeyen köle çok dayak yiyecek."],[48,"Ama bilmeden dayağı hak edecek şeyler yapan az dayak yiyecek. Kime çok verilmişse, ondan çok istenecek. Kime çok emanet edilmişse, ondan daha çoğu istenecek.”"]],"en":[[42,"And the Lord said: Who (thinkest thou) is the faithful and wise steward, whom his lord setteth over his family, to give them their measure of wheat in due season?"],[43,"Blessed is that servant, whom when his lord shall come, he shall find so doing."],[44,"Verily I say to you, he will set him over all that he possesseth."],[45,"But if that servant shall say in his heart: My lord is long a coming; and shall begin to strike the menservants and maidservants, and to eat and to drink and be drunk:"],[46,"The lord of that servant will come in the day that he hopeth not, and at the hour that he knoweth not, and shall separate him, and shall appoint him his portion with unbelievers."],[47,"And that servant who knew the will of his lord, and prepared not himself, and did not according to his will, shall be beaten with many stripes."],[48,"But he that knew not, and did things worthy of stripes, shall be beaten with few stripes. And unto whomsoever much is given, of him much shall be required: and to whom they have committed much, of him they will demand the more."]]},"Luke 13:24":{"tr":[[24,"“Dar kapıdan girmek için çaba gösterin. Size şunu söyleyeyim, birçokları girmeye çalışacak, ama giremeyecek.”"]],"en":[[24,"Strive to enter by the narrow gate; for many, I say to you, shall seek to enter, and shall not be able."]]},"Luke 13:6-9":{"tr":[[6,"İsa şu benzetmeyi anlattı: “Adamın birinin bağında dikili bir incir ağacı vardı. Ağaçta meyve aramaya geldi, ama bulamadı."],[7,"Bağcıya, ‘Bak, üç yıldır gelip bu incir ağacında meyve arıyorum, ama bulamıyorum’ dedi. ‘Kes onu! Neden toprağı boşuna işgal etsin?’"],[8,"Bağcı ona, ‘Efendim, bu yıl da ağaca dokunma’ diye karşılık verdi. ‘Çevresini kazıp gübreleyeyim."],[9,"Gelecek yıl meyve verirse ne iyi! Vermezse kesersin.’”"]],"en":[[6,"He spoke also this parable: A certain man had a fig tree planted in his vineyard, and he came seeking fruit on it, and found none."],[7,"And he said to the dresser of the vineyard: Behold, for these three years I come seeking fruit on this fig tree, and I find none. Cut it done therefore: why cumbereth it the ground?"],[8,"But he answering, said to him: Lord, let it alone this year also, until I dig about it, and dung it."],[9,"And if happily it bear fruit: but if not, then after that thou shalt cut it down."]]},"Luke 15:11-32":{"tr":[[11,"İsa şöyle devam etti: “Adamın birinin iki oğlu vardı."],[12,"Küçüğü babasına, ‘Baba, mirastan bana düşen payı ver’ dedi. Baba da malını ikisi arasında paylaştırdı."],[13,"Birkaç gün sonra küçük oğul her şeyini toplayıp uzak bir ülkeye gitti. Orada sefahat içinde yaşayarak malını çarçur etti."],[14,"Her şeyini harcadıktan sonra o ülkede büyük bir kıtlık baş gösterdi. Kendisi de yokluk çekmeye başladı."],[15,"Bunun üzerine gidip o ülkenin yurttaşlarından birinin yanına sığındı. Adam onu domuzlarını gütmek için tarlalarına gönderdi."],[16,"Domuzların yediği keçiboynuzlarıyla karnını doyurmak istiyordu, ama kimse ona bir şey vermiyordu."],[17,"Sonunda aklı başına geldi. ‘Babamın nice işçisinin yiyecek ekmeği artıp kalıyor da ben burada açlıktan ölüyorum’ dedi."],[18,"‘Kalkıp babamın yanına döneceğim ve ona, Baba, Tanrı’ya ve sana karşı günah işledim."],[19,"Artık oğlun olarak anılmaya layık değilim. Beni işçilerinden biri gibi kabul et diyeceğim.’"],[20,"Kalkıp babasının yanına döndü. Kendisi daha uzaktayken babası onu gördü, yüreği sızladı. Koşup onu kucakladı ve öptü."],[21,"Oğlu ona, ‘Baba, Tanrı’ya ve sana karşı günah işledim’ dedi. ‘Artık oğlun olarak anılmaya layık değilim.’"],[22,"Ama babası kölelerine, ‘Çabuk en iyi kaftanı getirip ona giydirin!’ dedi. ‘Parmağına yüzük takın, ayaklarına çarık giydirin."],[23,"Besili danayı getirip kesin. Yiyelim, eğlenelim."],[24,"Çünkü bu oğlum ölmüştü, yeniden yaşama kavuştu; kaybolmuştu, bulundu.’ Ve eğlenmeye başladılar."],[25,"O sırada büyük oğul tarladaydı. Gelip eve yaklaşınca çalgı ve oyun seslerini duydu."],[26,"Uşaklardan birini çağırıp neler olup bittiğini sordu."],[27,"Uşak ona, ‘Kardeşin geldi’ dedi. ‘Onu sağ salim geri kavuştuğu için baban besili danayı kestirdi.’"],[28,"Büyük oğul öfkelendi, içeri girmek istemedi. Babası dışarı çıkıp ona yalvardı."],[29,"O ise babasına şöyle karşılık verdi: ‘Bak, bunca yıldır sana hizmet ediyorum. Hiçbir zaman buyruğundan çıkmadım. Ama sen arkadaşlarımla eğlenmem için bana bir oğlak bile vermedin."],[30,"Oysa malını fahişelere yiyip bitiren bu oğlun eve dönünce onun için besili danayı kestirdin.’"],[31,"Babası ona, ‘Oğlum’ dedi, ‘sen her zaman benimlesin, neyim varsa senindir."],[32,"Ama sevinip eğlenmemiz gerekiyordu. Çünkü bu kardeşin ölmüştü, yeniden yaşama kavuştu; kaybolmuştu, bulundu.’”"]],"en":[[11,"And he said: A certain man had two sons:"],[12,"And the younger of them said to his father: Father, give me the portion of substance that falleth to me. And he divided unto them his substance."],[13,"And not many days after, the younger son, gathering all together, went abroad into a far country: and there wasted his substance, living riotously."],[14,"And after he had spent all, there came a mighty famine in that country; and he began to be in want."],[15,"And he went and cleaved to one of the citizens of that country. And he sent him into his farm to feed swine."],[16,"And he would fain have filled his belly with the husks the swine did eat; and no man gave unto him."],[17,"And returning to himself, he said: How many hired servants in my father’s house abound with bread, and I here perish with hunger?"],[18,"I will arise, and will go to my father, and say to him: Father, I have sinned against heaven, and before thee:"],[19,"I am not worthy to be called thy son: make me as one of thy hired servants."],[20,"And rising up he came to his father. And when he was yet a great way off, his father saw him, and was moved with compassion, and running to him fell upon his neck, and kissed him."],[21,"And the son said to him: Father, I have sinned against heaven, and before thee, I am not now worthy to be called thy son."],[22,"And the father said to his servants: Bring forth quickly the first robe, and put it on him, and put a ring on his hand, and shoes on his feet:"],[23,"And bring hither the fatted calf, and kill it, and let us eat and make merry:"],[24,"Because this my son was dead, and is come to life again: was lost, and is found. And they began to be merry."],[25,"Now his elder son was in the field, and when he came and drew nigh to the house, he heard music and dancing:"],[26,"And he called one of the servants, and asked what these things meant."],[27,"And he said to him: Thy brother is come, and thy father hath killed the fatted calf, because he hath received him safe."],[28,"And he was angry, and would not go in. His father therefore coming out began to entreat him."],[29,"And he answering, said to his father: Behold, for so many years do I serve thee, and I have never transgressed thy commandment, and yet thou hast never given me a kid to make merry with my friends:"],[30,"But as soon as this thy son is come, who hath devoured his substance with harlots, thou hast killed for him the fatted calf."],[31,"But he said to him: Son, thou art always with me, and all I have is thine."],[32,"But it was fit that we should make merry and be glad, for this thy brother was dead and is come to life again; he was lost, and is found."]]},"Luke 15:3-7":{"tr":[[3,"Bunun üzerine İsa onlara şu benzetmeyi anlattı:"],[4,"“Aranızda yüz koyunu olup da bunlardan birini kaybeden hanginiz doksan dokuzunu kırda bırakıp kaybolan koyunu buluncaya dek aramaz?"],[5,"Onu bulunca sevinçle omuzlarına alır."],[6,"Evine varınca dostlarını ve komşularını çağırıp onlara, ‘Benimle birlikte sevinin! Kaybolan koyunumu buldum’ der."],[7,"Size şunu söyleyeyim, tövbe etmesi gerekmeyen doksan dokuz doğru kişi için olduğundan daha büyük sevinç, tövbe eden tek bir günahkâr için gökte olacaktır."]],"en":[[3,"And he spoke to them this parable, saying:"],[4,"What man of you that hath an hundred sheep: and if he shall lose one of them, doth he not leave the ninety-nine in the desert, and go after that which was lost, until he find it?"],[5,"And when he hath found it, lay it upon his shoulders, rejoicing:"],[6,"And coming home, call together his friends and neighbours, saying to them: Rejoice with me, because I have found my sheep that was lost?"],[7,"I say to you, that even so there shall be joy in heaven upon one sinner that doth penance, more than upon ninety-nine just who need not penance."]]},"Luke 15:4-7":{"tr":[[4,"“Aranızda yüz koyunu olup da bunlardan birini kaybeden hanginiz doksan dokuzunu kırda bırakıp kaybolan koyunu buluncaya dek aramaz?"],[5,"Onu bulunca sevinçle omuzlarına alır."],[6,"Evine varınca dostlarını ve komşularını çağırıp onlara, ‘Benimle birlikte sevinin! Kaybolan koyunumu buldum’ der."],[7,"Size şunu söyleyeyim, tövbe etmesi gerekmeyen doksan dokuz doğru kişi için olduğundan daha büyük sevinç, tövbe eden tek bir günahkâr için gökte olacaktır."]],"en":[[4,"What man of you that hath an hundred sheep: and if he shall lose one of them, doth he not leave the ninety-nine in the desert, and go after that which was lost, until he find it?"],[5,"And when he hath found it, lay it upon his shoulders, rejoicing:"],[6,"And coming home, call together his friends and neighbours, saying to them: Rejoice with me, because I have found my sheep that was lost?"],[7,"I say to you, that even so there shall be joy in heaven upon one sinner that doth penance, more than upon ninety-nine just who need not penance."]]},"Luke 15:8-10":{"tr":[[8,"Ya da on gümüş parası olan bir kadın bunlardan birini kaybederse, kandil yakıp evi süpürmez mi, parayı buluncaya dek her yeri dikkatle aramaz mı?"],[9,"Parayı bulunca dostlarını ve komşularını çağırıp, ‘Benimle birlikte sevinin! Kaybettiğim parayı buldum’ der."],[10,"Size şunu söyleyeyim, tövbe eden tek bir günahkâr için de Tanrı’nın meleklerinin önünde sevinç olur.”"]],"en":[[8,"Or what woman having ten groats; if she lose one groat, doth not light a candle, and sweep the house, and seek diligently until she find it?"],[9,"And when she hath found it, call together her friends and neighbours, saying: Rejoice with me, because I have found the groat which I had lost."],[10,"So I say to you, there shall be joy before the angels of God upon one sinner doing penance."]]},"Luke 16:1-9":{"tr":[[1,"İsa öğrencilerine şunu da anlattı: “Zengin bir adamın bir kâhyası vardı. Kâhyanın, efendisinin malını çarçur ettiği adama bildirildi."],[2,"Zengin adam kâhyayı çağırıp ona, ‘Senin hakkında duyduğum bu şey ne?’ dedi. ‘Kâhyalığının hesabını ver. Artık kâhyam olamazsın.’"],[3,"Kâhya içinden şöyle dedi: ‘Ne yapacağım? Efendim kâhyalığı elimden alıyor. Toprağı kazmaya gücüm yok, dilenmeye utanırım."],[4,"Ne yapacağımı biliyorum: Kâhyalıktan uzaklaştırıldığımda insanlar beni evlerine alsınlar diye bir şey yapacağım.’"],[5,"Efendisine borcu olanları birer birer çağırdı. Birincisine, ‘Efendime borcun ne kadar?’ diye sordu."],[6,"Adam, ‘Yüz ölçek zeytinyağı’ dedi. Kâhya ona, ‘Al senedini, otur, çabuk elli yaz’ dedi."],[7,"Sonra bir başkasına, ‘Senin borcun ne kadar?’ diye sordu. O da, ‘Yüz ölçek buğday’ dedi. Kâhya ona, ‘Al senedini, seksen yaz’ dedi."],[8,"Efendisi, dürüst olmayan kâhyayı akıllıca davrandığı için övdü. Çünkü bu dünyanın çocukları kendi kuşaklarıyla ilişkilerinde ışığın çocuklarından daha akıllıdır."],[9,"Size şunu söyleyeyim, bu dünyanın haksız malıyla kendinize dost edinin. Öyle ki, mal tükendiğinde sizi sonsuz konutlara alsınlar.”"]],"en":[[1,"And he said also to his disciples: There was a certain rich man who had a steward: and the same was accused unto him, that he had wasted his goods."],[2,"And he called him, and said to him: How is it that I hear this of thee? give an account of thy stewardship: for now thou canst be steward no longer."],[3,"And the steward said within himself: What shall I do, because my lord taketh away from me the stewardship? To dig I am not able; to beg I am ashamed."],[4,"I know what I will do, that when I shall be removed from the stewardship, they may receive me into their houses."],[5,"Therefore calling together every one of his lord’s debtors, he said to the first: How much dost thou owe my lord?"],[6,"But he said: An hundred barrels of oil. And he said to him: Take thy bill and sit down quickly, and write fifty."],[7,"Then he said to another: And how much dost thou owe? Who said: An hundred quarters of wheat. He said to him: Take thy bill, and write eighty."],[8,"And the lord commended the unjust steward, forasmuch as he had done wisely: for the children of this world are wiser in their generation than the children of light."],[9,"And I say to you: Make unto you friends of the mammon of iniquity; that when you shall fail, they may receive you into everlasting dwellings."]]},"Luke 16:19-31":{"tr":[[19,"“Bir zengin vardı. Mor giysiler ve ince ketenler giyer, her gün büyük bir şatafat içinde eğlenirdi."],[20,"Zenginin kapısının önüne Lazar adında yoksul bir adam bırakılmıştı. Her yanı yara içindeydi."],[21,"Zenginin sofrasından düşen kırıntılarla karnını doyurmaya can atardı. Köpekler bile gelip yaralarını yalardı."],[22,"Bir gün yoksul adam öldü. Melekler onu İbrahim’in yanına götürdüler. Zengin de öldü ve gömüldü."],[23,"Zengin ölüler diyarında acılar içinde başını kaldırınca uzaktan İbrahim’i ve onun yanında Lazar’ı gördü."],[24,"‘Ey babam İbrahim, bana acı!’ diye seslendi. ‘Lazar’ı gönder de parmağının ucunu suya batırıp dilimi serinletsin. Çünkü bu alev içinde acı çekiyorum.’"],[25,"İbrahim ona, ‘Oğlum’ dedi, ‘hatırla, sen yaşarken iyi şeylere kavuştun, Lazar ise kötü şeylere. Şimdi o burada teselli ediliyor, sen ise acı çekiyorsun."],[26,"Bütün bunlardan başka, aramızda büyük bir uçurum var. Öyle ki, buradan size geçmek isteyenler geçemez, oradan da kimse bize geçemez.’"],[27,"Zengin adam, ‘Öyleyse, baba, sana yalvarırım, Lazar’ı babamın evine gönder’ dedi."],[28,"‘Beş kardeşim var. Lazar gidip onları uyarsın ki, onlar da bu azap yerine düşmesinler.’"],[29,"İbrahim, ‘Onların Musa’yla peygamberleri var, onları dinlesinler’ dedi."],[30,"Zengin adam, ‘Hayır, babam İbrahim’ dedi. ‘Ölülerden biri onlara giderse tövbe ederler.’"],[31,"İbrahim ona şöyle dedi: ‘Musa’yı ve peygamberleri dinlemezlerse, ölülerden biri dirilse bile ikna olmazlar.’”"]],"en":[[19,"There was a certain rich man, who was clothed in purple and fine linen; and feasted sumptuously every day."],[20,"And there was a certain beggar, named Lazarus, who lay at his gate, full of sores,"],[21,"Desiring to be filled with the crumbs that fell from the rich man’s table, and no one did give him; moreover the dogs came, and licked his sores."],[22,"And it came to pass, that the beggar died, and was carried by the angels into Abraham’s bosom. And the rich man also died: and he was buried in hell."],[23,"And lifting up his eyes when he was in torments, he saw Abraham afar off, and Lazarus in his bosom:"],[24,"And he cried, and said: Father Abraham, have mercy on me, and send Lazarus, that he may dip the tip of his finger in water, to cool my tongue: for I am tormented in this flame."],[25,"And Abraham said to him: Son, remember that thou didst receive good things in thy lifetime, and likewise Lazareth evil things, but now he is comforted; and thou art tormented."],[26,"And besides all this, between us and you, there is fixed a great chaos: so that they who would pass from hence to you, cannot, nor from thence come hither."],[27,"And he said: Then, father, I beseech thee, that thou wouldst send him to my father’s house, for I have five brethren,"],[28,"That he may testify unto them, lest they also come into this place of torments."],[29,"And Abraham said to him: They have Moses and the prophets; let them hear them."],[30,"But he said: No, father Abraham: but if one went to them from the dead, they will do penance."],[31,"And he said to him: If they hear not Moses and the prophets, neither will they believe, if one rise again from the dead."]]},"Luke 16:31":{"tr":[[31,"İbrahim ona şöyle dedi: ‘Musa’yı ve peygamberleri dinlemezlerse, ölülerden biri dirilse bile ikna olmazlar.’”"]],"en":[[31,"And he said to him: If they hear not Moses and the prophets, neither will they believe, if one rise again from the dead."]]},"Luke 18:2-5":{"tr":[[2,"İsa şöyle dedi: “Bir kentte Tanrı’dan korkmayan, insana değer vermeyen bir yargıç vardı."],[3,"Aynı kentte yaşayan dul bir kadın, sık sık yargıca gelip, ‘Hasmıma karşı bana hakkımı ver’ diyordu."],[4,"Yargıç bir süre bunu istemedi. Ama sonunda kendi kendine şöyle dedi: ‘Tanrı’dan korkmadığım, insana da değer vermediğim halde,"],[5,"bu dul kadın beni rahatsız ettiği için ona hakkını vereceğim. Yoksa sürekli gelip beni bezdirecek.’”"]],"en":[[2,"Saying: There was a judge in a certain city, who feared not God, nor regarded man."],[3,"And there was a certain widow in that city, and she came to him, saying: Avenge me of my adversary."],[4,"And he would not for a long time. But afterwards he said within himself: Although I fear not God, nor regard man,"],[5,"Yet because this widow is troublesome to me, I will avenge her, lest continually coming she weary me."]]},"Luke 18:9-14":{"tr":[[9,"Kendilerinin doğru olduğuna güvenip başkalarını hor gören bazı kişilere İsa şu benzetmeyi anlattı:"],[10,"“İki kişi dua etmek için tapınağa çıktı. Biri Ferisi, öbürü vergi görevlisiydi."],[11,"Ferisi ayakta kendi kendine şöyle dua etti: ‘Ey Tanrım, öteki insanlara, soygunculara, haksızlara, zina edenlere ya da şu vergi görevlisine benzemediğim için sana şükrederim."],[12,"Haftada iki kez oruç tutuyor, bütün kazancımın ondalığını veriyorum.’"],[13,"Vergi görevlisi ise uzakta durdu. Gözlerini göğe kaldırmaya bile cesaret edemiyordu. Göğsünü döverek, ‘Ey Tanrım, ben günahkâra merhamet et!’ diyordu."],[14,"Size şunu söyleyeyim, öbürü değil, bu adam Tanrı katında aklanmış olarak evine döndü. Çünkü kendini yücelten alçaltılacak, kendini alçaltan yüceltilecektir.”"]],"en":[[9,"And to some who trusted in themselves as just, and despised others, he spoke also this parable:"],[10,"Two men went up into the temple to pray: the one a Pharisee, and the other a publican."],[11,"The Pharisee standing, prayed thus with himself: O God, I give thee thanks that I am not as the rest of men, extortioners, unjust, adulterers, as also is this publican."],[12,"I fast twice in a week: I give tithes of all that I possess."],[13,"And the publican, standing afar off, would not so much as lift up his eyes towards heaven; but struck his breast, saying: O god, be merciful to me a sinner."],[14,"I say to you, this man went down into his house justified rather that the other: because every one that exalteth himself, shall be humbled: and he that humbleth himself, shall be exalted."]]},"Luke 19:12-27":{"tr":[[12,"İsa şöyle dedi: “Soylu bir adam, krallık yetkisi alıp dönmek üzere uzak bir ülkeye gitti."],[13,"Gitmeden önce on kölesini çağırıp onlara on mina verdi. ‘Ben dönünceye dek bu parayla ticaret yapın’ dedi."],[14,"Ama yurttaşları ondan nefret ediyorlardı. Arkasından bir heyet gönderip, ‘Bu adamın bize kral olmasını istemiyoruz’ dediler."],[15,"Soylu adam krallık yetkisini alıp geri döndü. Ticaret yapıp ne kazandıklarını öğrenmek için parayı verdiği köleleri çağırttı."],[16,"Birincisi gelip, ‘Efendim, minan on mina daha kazandırdı’ dedi."],[17,"Efendisi ona, ‘Aferin, iyi köle!’ dedi. ‘Çok küçük bir işte güvenilir olduğun için on kentin yönetimini sana veriyorum.’"],[18,"İkincisi gelip, ‘Efendim, minan beş mina daha kazandırdı’ dedi."],[19,"Efendisi buna da, ‘Sen de beş kentin başında ol’ dedi."],[20,"Bir başkası gelip şöyle dedi: ‘Efendim, işte minan! Onu bir mendile sarıp sakladım."],[21,"Senden korktum, çünkü sert bir adamsın. Yatırmadığını alır, ekmediğini biçersin.’"],[22,"Efendisi ona şöyle dedi: ‘Seni kötü köle, seni kendi sözünle yargılayacağım. Benim sert bir adam olduğumu, yatırmadığımı aldığımı, ekmediğimi biçtiğimi biliyordun, öyle mi?"],[23,"Öyleyse neden paramı bankaya yatırmadın? Ben de dönüşümde onu faiziyle birlikte alırdım.’"],[24,"Sonra yanında duranlara, ‘Minayı onun elinden alın, on minası olana verin’ dedi."],[25,"Onlar, ‘Efendimiz, onun zaten on minası var’ dediler."],[26,"Efendi, ‘Size şunu söyleyeyim, kimde varsa ona daha çok verilecek. Ama kimde yoksa, elindeki de alınacak’ dedi."],[27,"‘Kral olmamı istemeyen şu düşmanlarıma gelince, onları buraya getirin ve gözümün önünde öldürün.’”"]],"en":[[12,"He said therefore: A certain nobleman went into a far country, to receive for himself a kingdom, and to return."],[13,"And calling his ten servants, he gave them ten pounds, and said to them: Trade till I come."],[14,"But his citizens hated him: and they sent an embassage after him, saying: We will not have this man to reign over us."],[15,"And it came to pass, that he returned, having received the kingdom: and he commanded his servants to be called, to whom he had given the money, that he might know how much every man had gained by trading."],[16,"And the first came, saying: Lord, thy pound hath gained ten pounds."],[17,"And he said to him: Well done, thou good servant, because thou hast been faithful in a little, thou shalt have power over ten cities."],[18,"And the second came, saying: Lord, thy pound hath gained five pounds."],[19,"And he said to him: Be thou also over five cities."],[20,"And another came, saying: Lord, behold here is thy pound, which I have kept laid up in a napkin;"],[21,"For I feared thee, because thou art an austere man: thou takest up what thou didst not lay down, and thou reapest that which thou didst not sow."],[22,"He saith to him: Out of thy own mouth I judge thee, thou wicked servant. Thou knewest that I was an austere man, taking up what I laid not down, and reaping that which I did not sow:"],[23,"And why then didst thou not give my money into the bank, that at my coming, I might have exacted it with usury?"],[24,"And he said to them that stood by: Take the pound away from him, and give it to him that hath ten pounds."],[25,"And they said to him: Lord, he hath ten pounds."],[26,"But I say to you, that to every one that hath shall be given, and he shall abound: and from him that hath not, even that which he hath, shall be taken from him."],[27,"But as for those my enemies, who would not have me reign over them, bring them hither, and kill them before me."]]},"Luke 1:1-4":{"tr":[[1,"Aramızda gerçekleşen olayların öyküsünü yazmaya birçokları girişti."],[2,"Başlangıçtan beri olayları gözleriyle görmüş ve Tanrı sözünün hizmetkârları olmuş kişiler bunları bize aktardılar."],[3,"Ben de her şeyi başından beri dikkatle araştırdıktan sonra, sana, saygıdeğer Teofilos, bunları sırasıyla yazmayı uygun gördüm."],[4,"Öyle ki, sana öğretilen konuların kesin gerçek olduğunu bilesin."]],"en":[[1,"Forasmuch as many have taken in hand to set forth in order a narration of the things that have been accomplished among us;"],[2,"According as they have delivered them unto us, who from the beginning were eyewitnesses and ministers of the word:"],[3,"It seemed good to me also, having diligently attained to all things from the beginning, to write to thee in order, most excellent Theophilus,"],[4,"That thou mayest know the verity of those words in which thou hast been instructed."]]},"Luke 1:13":{"tr":[[13,"Melek ona şöyle dedi: “Korkma, Zekeriya, duan kabul edildi. Karın Elizabet sana bir oğul doğuracak. Adını Yahya koyacaksın."]],"en":[[13,"But the angel said to him: Fear not, Zachary, for thy prayer is heard; and thy wife Elizabeth shall bear thee a son, and thou shalt call his name John:"]]},"Luke 1:17":{"tr":[[17,"İlyas’ın ruhu ve gücüyle Rab’bin önünden gidecek. Babaların yüreklerini çocuklarına döndürecek, söz dinlemeyenleri doğruların anlayışına yöneltecek ve Rab için hazırlıklı bir halk yetiştirecek.”"]],"en":[[17,"And he shall go before him in the spirit and power of Elias; that he may turn the hearts of the fathers unto the children, and the incredulous to the wisdom of the just, to prepare unto the Lord a perfect people."]]},"Luke 1:26-38":{"tr":[[26,"Altıncı ayda Tanrı, Cebrail meleği Celile’de Nasıra denen bir kente,"],[27,"Davut’un soyundan Yusuf adında bir adamla nişanlı olan bir kıza gönderdi. Kızın adı Meryem’di."],[28,"Melek onun yanına gelip şöyle dedi: “Selam, ey lütuf dolu! Rab seninledir.”"],[29,"Meryem bu sözler karşısında çok şaşırdı, bu selamın ne anlama geldiğini düşünüp durdu."],[30,"Melek ona, “Korkma, Meryem, sen Tanrı’nın lütfunu kazandın” dedi."],[31,"“Bak, gebe kalıp bir oğul doğuracaksın. Adını İsa koyacaksın."],[32,"O büyük olacak, kendisine Yüceler Yücesi’nin Oğlu denecek. Rab Tanrı ona atası Davut’un tahtını verecek."],[33,"O da Yakup soyu üzerinde sonsuza dek egemenlik sürecek ve egemenliğinin sonu olmayacak.”"],[34,"Meryem meleğe, “Bu nasıl olur? Ben erkek yüzü görmedim ki” dedi."],[35,"Melek ona şöyle karşılık verdi: “Kutsal Ruh senin üzerine gelecek, Yüceler Yücesi’nin gücü sana gölge salacak. Bunun için doğacak olan kutsal çocuğa Tanrı Oğlu denecek."],[36,"Bak, akraban Elizabet de yaşlılığında bir oğula gebe kaldı. Kısır denilen kadın şimdi altıncı ayında."],[37,"Çünkü Tanrı için imkânsız hiçbir şey yoktur.”"],[38,"Meryem, “Ben Rab’bin kuluyum” dedi. “Bana dediğin gibi olsun.” Sonra melek onun yanından ayrıldı."]],"en":[[26,"And in the sixth month, the angel Gabriel was sent from God into a city of Galilee, called Nazareth,"],[27,"To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."],[28,"And the angel being come in, said unto her: Hail, full of grace, the Lord is with thee: blessed art thou among women."],[29,"Who having heard, was troubled at his saying, and thought with herself what manner of salutation this should be."],[30,"And the angel said to her: Fear not, Mary, for thou hast found grace with God."],[31,"Behold thou shalt conceive in thy womb, and shalt bring forth a son; and thou shalt call his name Jesus."],[32,"He shall be great, and shall be called the Son of the most High; and the Lord God shall give unto him the throne of David his father; and he shall reign in the house of Jacob for ever."],[33,"And of his kingdom there shall be no end."],[34,"And Mary said to the angel: How shall this be done, because I know not man?"],[35,"And the angel answering, said to her: The Holy Ghost shall come upon thee, and the power of the most High shall overshadow thee. And therefore also the Holy which shall be born of thee shall be called the Son of God."],[36,"And behold thy cousin Elizabeth, she also hath conceived a son in her old age; and this is the sixth month with her that is called barren:"],[37,"Because no word shall be impossible with God."],[38,"And Mary said: Behold the handmaid of the Lord; be it done to me according to thy word. And the angel departed from her."]]},"Luke 1:28":{"tr":[[28,"Melek onun yanına gelip şöyle dedi: “Selam, ey lütuf dolu! Rab seninledir.”"]],"en":[[28,"And the angel being come in, said unto her: Hail, full of grace, the Lord is with thee: blessed art thou among women."]]},"Luke 1:30":{"tr":[[30,"Melek ona, “Korkma, Meryem, sen Tanrı’nın lütfunu kazandın” dedi."]],"en":[[30,"And the angel said to her: Fear not, Mary, for thou hast found grace with God."]]},"Luke 1:32":{"tr":[[32,"“O büyük olacak, kendisine Yüceler Yücesi’nin Oğlu denecek. Rab Tanrı ona atası Davut’un tahtını verecek.”"]],"en":[[32,"He shall be great, and shall be called the Son of the most High; and the Lord God shall give unto him the throne of David his father; and he shall reign in the house of Jacob for ever."]]},"Luke 1:35":{"tr":[[35,"Melek ona şöyle karşılık verdi: “Kutsal Ruh senin üzerine gelecek, Yüceler Yücesi’nin gücü sana gölge salacak. Bunun için doğacak olan kutsal çocuğa Tanrı Oğlu denecek."]],"en":[[35,"And the angel answering, said to her: The Holy Ghost shall come upon thee, and the power of the most High shall overshadow thee. And therefore also the Holy which shall be born of thee shall be called the Son of God."]]},"Luke 1:37":{"tr":[[37,"Çünkü Tanrı için imkânsız hiçbir şey yoktur.”"]],"en":[[37,"Because no word shall be impossible with God."]]},"Luke 1:38":{"tr":[[38,"Meryem, “Ben Rab’bin kuluyum” dedi. “Bana dediğin gibi olsun.” Sonra melek onun yanından ayrıldı."]],"en":[[38,"And Mary said: Behold the handmaid of the Lord; be it done to me according to thy word. And the angel departed from her."]]},"Luke 1:39-56":{"tr":[[39,"O günlerde Meryem kalkıp aceleyle Yahuda’nın dağlık bölgesindeki bir kente gitti."],[40,"Zekeriya’nın evine girip Elizabet’i selamladı."],[41,"Elizabet, Meryem’in selamını duyunca, rahmindeki çocuk hopladı ve Elizabet Kutsal Ruh’la doldu."],[42,"Yüksek sesle şöyle dedi: “Kadınlar arasında sen kutsalsın, rahminin meyvesi de kutsaldır!"],[43,"Rabbimin annesinin yanıma gelmesi bana nereden nasip oldu?"],[44,"Bak, selamını duyar duymaz, rahmimdeki çocuk sevinçle hopladı."],[45,"Rab’bin kendisine söylediklerinin yerine geleceğine iman eden kadına ne mutlu!”"],[46,"Meryem şöyle dedi: “Canım Rab’bi yüceltir,"],[47,"ruhum Kurtarıcım Tanrı sayesinde sevinçle coşar."],[48,"Çünkü O, sıradan kulunu gözetti. İşte, bundan böyle bütün kuşaklar bana ‘Ne mutlu!’ diyecek."],[49,"Çünkü Güçlü Olan benim için büyük işler yaptı. O’nun adı kutsaldır."],[50,"O’ndan korkanlara kuşaklar boyu merhamet eder."],[51,"Bileğiyle büyük işler yaptı, yüreklerinde gurur besleyenleri dağıttı."],[52,"Hükümdarları tahtlarından indirdi, alçakgönüllüleri yükseltti."],[53,"Açları iyiliklerle doyurdu, zenginleri eli boş gönderdi."],[54,"Kulu İsrail’e yardım etti, merhametini unutmadı;"],[55,"atalarımıza, İbrahim’e ve onun soyuna sonsuza dek söz verdiği gibi.”"],[56,"Meryem yaklaşık üç ay Elizabet’in yanında kaldıktan sonra kendi evine döndü."]],"en":[[39,"And Mary rising up in those days, went into the hill country with haste into a city of Juda."],[40,"And she entered into the house of Zachary, and saluted Elizabeth."],[41,"And it came to pass, that when Elizabeth heard the salutation of Mary, the infant leaped in her womb. And Elizabeth was filled with the Holy Ghost:"],[42,"And she cried out with a loud voice, and said: Blessed art thou among women, and blessed is the fruit of thy womb."],[43,"And whence is this to me, that the mother of my Lord should come to me?"],[44,"For behold as soon as the voice of thy salutation sounded in my ears, the infant in my womb leaped for joy."],[45,"And blessed art thou that hast believed, because those things shall be accomplished that were spoken to thee by the Lord."],[46,"And Mary said: My soul doth magnify the Lord."],[47,"And my spirit hath rejoiced in God my Saviour."],[48,"Because he hath regarded the humility of his handmaid; for behold from henceforth all generations shall call me blessed."],[49,"Because he that is mighty, hath done great things to me; and holy is his name."],[50,"And his mercy is from generation unto generations, to them that fear him."],[51,"He hath shewed might in his arm: he hath scattered the proud in the conceit of their heart."],[52,"He hath put down the mighty from their seat, and hath exalted the humble."],[53,"He hath filled the hungry with good things; and the rich he hath sent empty away."],[54,"He hath received Israel his servant, being mindful of his mercy:"],[55,"As he spoke to our fathers, to Abraham and to his seed for ever."],[56,"And Mary abode with her about three months; and she returned to her own house."]]},"Luke 1:42":{"tr":[[42,"Yüksek sesle şöyle dedi: “Kadınlar arasında sen kutsalsın, rahminin meyvesi de kutsaldır!"]],"en":[[42,"And she cried out with a loud voice, and said: Blessed art thou among women, and blessed is the fruit of thy womb."]]},"Luke 1:43":{"tr":[[43,"Rabbimin annesinin yanıma gelmesi bana nereden nasip oldu?"]],"en":[[43,"And whence is this to me, that the mother of my Lord should come to me?"]]},"Luke 1:46-55":{"tr":[[46,"Meryem şöyle dedi: “Canım Rab’bi yüceltir,"],[47,"ruhum Kurtarıcım Tanrı sayesinde sevinçle coşar."],[48,"Çünkü O, sıradan kulunu gözetti. İşte, bundan böyle bütün kuşaklar bana ‘Ne mutlu!’ diyecek."],[49,"Çünkü Güçlü Olan benim için büyük işler yaptı. O’nun adı kutsaldır."],[50,"O’ndan korkanlara kuşaklar boyu merhamet eder."],[51,"Bileğiyle büyük işler yaptı, yüreklerinde gurur besleyenleri dağıttı."],[52,"Hükümdarları tahtlarından indirdi, alçakgönüllüleri yükseltti."],[53,"Açları iyiliklerle doyurdu, zenginleri eli boş gönderdi."],[54,"Kulu İsrail’e yardım etti, merhametini unutmadı;"],[55,"atalarımıza, İbrahim’e ve onun soyuna sonsuza dek söz verdiği gibi.”"]],"en":[[46,"And Mary said: My soul doth magnify the Lord."],[47,"And my spirit hath rejoiced in God my Saviour."],[48,"Because he hath regarded the humility of his handmaid; for behold from henceforth all generations shall call me blessed."],[49,"Because he that is mighty, hath done great things to me; and holy is his name."],[50,"And his mercy is from generation unto generations, to them that fear him."],[51,"He hath shewed might in his arm: he hath scattered the proud in the conceit of their heart."],[52,"He hath put down the mighty from their seat, and hath exalted the humble."],[53,"He hath filled the hungry with good things; and the rich he hath sent empty away."],[54,"He hath received Israel his servant, being mindful of his mercy:"],[55,"As he spoke to our fathers, to Abraham and to his seed for ever."]]},"Luke 1:48":{"tr":[[48,"Çünkü O, sıradan kulunu gözetti. İşte, bundan böyle bütün kuşaklar bana ‘Ne mutlu!’ diyecek."]],"en":[[48,"Because he hath regarded the humility of his handmaid; for behold from henceforth all generations shall call me blessed."]]},"Luke 22:19":{"tr":[[19,"İsa eline ekmek aldı, şükredip kırdı ve onlara verdi. “Bu sizin için verilen bedenimdir. Beni anmak için bunu yapın” dedi."]],"en":[[19,"And taking bread, he gave thanks, and brake; and gave to them, saying: This is my body, which is given for you. Do this for a commemoration of me."]]},"Luke 22:19-20":{"tr":[[19,"İsa eline ekmek aldı, şükredip kırdı ve onlara verdi. “Bu sizin için verilen bedenimdir. Beni anmak için bunu yapın” dedi."],[20,"Aynı şekilde yemekten sonra kâseyi alıp, “Bu kâse, sizin için akıtılan kanımla gerçekleşen yeni antlaşmadır” dedi."]],"en":[[19,"And taking bread, he gave thanks, and brake; and gave to them, saying: This is my body, which is given for you. Do this for a commemoration of me."],[20,"In like manner the chalice also, after he had supped, saying: This is the chalice, the new testament in my blood, which shall be shed for you."]]},"Luke 23:33-46":{"tr":[[33,"Kafatası denen yere varınca İsa’yı orada çarmıha gerdiler. Suçluları da biri sağında, öbürü solunda olmak üzere çarmıha gerdiler."],[34,"İsa, “Baba, onları bağışla, çünkü ne yaptıklarını bilmiyorlar” dedi. Askerler O’nun giysilerini aralarında paylaşmak için kura çektiler."],[35,"Halk durmuş seyrediyordu. Yöneticiler de, “Başkalarını kurtardı. Eğer Tanrı’nın Mesihi, O’nun seçtiği kişiyse, kendini de kurtarsın!” diyerek O’nunla alay ediyorlardı."],[36,"Askerler de O’nunla alay ettiler. Yanına gelip O’na ekşi şarap uzatarak,"],[37,"“Eğer sen Yahudiler’in Kralı’ysan, kendini kurtar!” dediler."],[38,"O’nun başının üstünde Grekçe, Latince ve İbranice olarak yazılmış şu yafta vardı: “Yahudiler’in Kralı budur.”"],[39,"Çarmıha gerilen suçlulardan biri O’na sövüp sayarak, “Sen Mesih değil misin? Haydi, kendini de bizi de kurtar!” dedi."],[40,"Öbürü ise onu azarlayarak, “Aynı cezaya çarptırılmışken sen Tanrı’dan hiç korkmaz mısın?” dedi."],[41,"“Biz cezamızı hak ettik, yaptıklarımızın karşılığını alıyoruz. Ama bu adam hiçbir kötülük yapmadı.”"],[42,"Sonra İsa’ya, “Ya İsa, egemenliğine kavuştuğun zaman beni an” dedi."],[43,"İsa ona, “Sana doğrusunu söyleyeyim, sen bugün benimle birlikte cennette olacaksın” dedi."],[44,"Saat on iki sularıydı. Güneş ışığını yitirdi ve saat üçe kadar bütün ülkenin üzerine karanlık çöktü."],[45,"Tapınaktaki perde ortasından yırtıldı."],[46,"İsa yüksek sesle, “Baba, ruhumu senin ellerine bırakıyorum!” diye haykırdı. Bunu söyleyince son nefesini verdi."]],"en":[[33,"And when they were come to the place which is called Calvary, they crucified him there; and the robbers, one on the right hand, and the other on the left."],[34,"And Jesus said: Father, forgive them, for they know not what they do. But they, dividing his garments, cast lots."],[35,"And the people stood beholding, and the rulers with them derided him, saying: He saved others; let him save himself, if he be Christ, the elect of God."],[36,"And the soldiers also mocked him, coming to him, and offering him vinegar,"],[37,"And saying: If thou be the king of the Jews, save thyself."],[38,"And there was also a superscription written over him in letters of Greek, and Latin, and Hebrew: THIS IS THE KING OF THE JEWS."],[39,"And one of those robbers who were hanged, blasphemed him, saying: If thou be Christ, save thyself and us."],[40,"But the other answering, rebuked him, saying: Neither dost thou fear God, seeing thou art condemned under the same condemnation?"],[41,"And we indeed justly, for we receive the due reward of our deeds; but this man hath done no evil."],[42,"And he said to Jesus: Lord, remember me when thou shalt come into thy kingdom."],[43,"And Jesus said to him: Amen I say to thee, this day thou shalt be with me in paradise."],[44,"And it was almost the sixth hour; and there was darkness over all the earth until the ninth hour."],[45,"And the sun was darkened, and the veil of the temple was rent in the midst."],[46,"And Jesus crying out with a loud voice, said: Father, into thy hands I commend my spirit. And saying this, he gave up the ghost."]]},"Luke 23:43":{"tr":[[43,"İsa ona, “Sana doğrusunu söyleyeyim, sen bugün benimle birlikte cennette olacaksın” dedi."]],"en":[[43,"And Jesus said to him: Amen I say to thee, this day thou shalt be with me in paradise."]]},"Luke 24:1-12":{"tr":[[1,"Haftanın ilk günü sabah çok erkenden, kadınlar hazırladıkları baharatı alarak mezara gittiler."],[2,"Mezarın girişindeki taşın yuvarlanmış olduğunu gördüler."],[3,"İçeri girdiler, ama Rab İsa’nın cesedini bulamadılar."],[4,"Buna şaşıp kalmışken, birden giysileri şimşek gibi parıldayan iki adam yanlarında belirdi."],[5,"Kadınlar korkuyla yere eğilince adamlar onlara, “Diri olanı neden ölüler arasında arıyorsunuz?” dediler."],[6,"“O burada değil, dirildi. Daha Celile’deyken size ne söylediğini hatırlayın:"],[7,"‘İnsanoğlu’nun günahlı insanların eline teslim edilmesi, çarmıha gerilmesi ve üçüncü gün dirilmesi gerek’ demişti.”"],[8,"Kadınlar İsa’nın sözlerini hatırladılar."],[9,"Mezardan dönüp bütün bu olanları on bir öğrenciye ve geri kalan herkese anlattılar."],[10,"Bunları elçilere anlatanlar Mecdelli Meryem, Yohanna, Yakup’un annesi Meryem ve onlarla birlikte olan öbür kadınlardı."],[11,"Ama elçiler bu sözleri saçma buldular ve kadınlara inanmadılar."],[12,"Petrus ise kalkıp mezara koştu. Eğilip içeri bakınca yalnızca keten bezleri gördü. Olanlara şaşarak oradan ayrıldı."]],"en":[[1,"And on the first day of the week, very early in the morning, they came to the sepulchre, bringing the spices which they had prepared."],[2,"And they found the stone rolled back from the sepulchre."],[3,"And going in, they found not the body of the Lord Jesus."],[4,"And it came to pass, as they were astonished in their mind at this, behold, two men stood by them, in shining apparel."],[5,"And as they were afraid, and bowed down their countenance towards the ground, they said unto them: Why seek you the living with the dead?"],[6,"He is not here, but is risen. Remember how he spoke unto you, when he was in Galilee,"],[7,"Saying: The Son of man must be delivered into the hands of sinful men, and be crucified, and the third day rise again."],[8,"And they remembered his words."],[9,"And going back from the sepulchre, they told all these things to the eleven, and to all the rest."],[10,"And it was Mary Magdalen, and Joanna, and Mary of James, and the other women that were with them, who told these things to the apostles."],[11,"And these words seemed to them as idle tales; and they did not believe them."],[12,"But Peter rising up, ran to the sepulchre, and stooping down, he saw the linen cloths laid by themselves; and went away wondering in himself at that which was come to pass."]]},"Luke 2:1-20":{"tr":[[1,"O günlerde Sezar Augustus, bütün dünyada nüfus sayımı yapılmasını buyurdu."],[2,"Bu ilk sayım, Kirinius’un Suriye valiliği sırasında yapıldı."],[3,"Herkes yazılmak için kendi kentine gitti."],[4,"Yusuf da Davut’un soyundan ve ailesinden olduğu için Celile’deki Nasıra kentinden Yahudiye’deki Davut’un kenti Beytlehem’e gitti."],[5,"Kendisiyle nişanlı olan ve gebe bulunan Meryem’le birlikte yazılmak için oraya gitti."],[6,"Onlar oradayken Meryem’in doğuracağı vakit geldi."],[7,"İlk oğlunu doğurdu, onu kundağa sarıp bir yemliğe yatırdı. Çünkü handa onlara yer yoktu."],[8,"O bölgede kırlarda kalıp geceleyin sürülerini bekleyen çobanlar vardı."],[9,"Rab’bin bir meleği onlara göründü, Rab’bin görkemi çevrelerini aydınlattı ve çok korktular."],[10,"Melek onlara, “Korkmayın!” dedi. “Size bütün halkı çok sevindirecek bir müjde getiriyorum."],[11,"Bugün Davut’un kentinde size bir Kurtarıcı doğdu. O, Rab Mesih’tir."],[12,"Size şu bir işaret olacak: Kundağa sarılmış, yemlikte yatan bir bebek bulacaksınız.”"],[13,"Birden göksel ordudan büyük bir topluluk meleğe katıldı. Tanrı’yı övüp şöyle diyorlardı:"],[14,"“En yücelerde Tanrı’ya yücelik olsun, yeryüzünde iyi niyetli insanlara esenlik olsun!”"],[15,"Melekler onların yanından göğe dönünce, çobanlar birbirlerine, “Haydi, Beytlehem’e gidelim de Rab’bin bize bildirdiği bu olayı görelim” dediler."],[16,"Aceleyle gidip Meryem’le Yusuf’u ve yemlikte yatan bebeği buldular."],[17,"Bebeği görünce, onunla ilgili kendilerine söylenenleri anladılar."],[18,"Duyanların hepsi çobanların anlattıklarına şaştı."],[19,"Meryem ise bütün bu sözleri yüreğinde saklıyor, onlar üzerinde derin derin düşünüyordu."],[20,"Çobanlar, kendilerine söylendiği gibi işitip gördükleri her şey için Tanrı’yı yüceltip överek döndüler."]],"en":[[1,"And it came to pass, that in those days there went out a decree from Caesar Augustus, that the whole world should be enrolled."],[2,"This enrolling was first made by Cyrinus, the governor of Syria."],[3,"And all went to be enrolled, every one into his own city."],[4,"And Joseph also went up from Galilee, out of the city of Nazareth into Judea, to the city of David, which is called Bethlehem: because he was of the house and family of David,"],[5,"To be enrolled with Mary his espoused wife, who was with child."],[6,"And it came to pass, that when they were there, her days were accomplished, that she should be delivered."],[7,"And she brought forth her firstborn son, and wrapped him up in swaddling clothes, and laid him in a manger; because there was no room for them in the inn."],[8,"And there were in the same country shepherds watching, and keeping the night watches over their flock."],[9,"And behold an angel of the Lord stood by them, and the brightness of God shone round about them; and they feared with a great fear."],[10,"And the angel said to them: Fear not; for, behold, I bring you good tidings of great joy, that shall be to all the people:"],[11,"For, this day, is born to you a Saviour, who is Christ the Lord, in the city of David."],[12,"And this shall be a sign unto you. You shall find the infant wrapped in swaddling clothes, and laid in a manger."],[13,"And suddenly there was with the angel a multitude of the heavenly army, praising God, and saying:"],[14,"Glory to God in the highest; and on earth peace to men of good will."],[15,"And it came to pass, after the angels departed from them into heaven, the shepherds said one to another: Let us go over to Bethlehem, and let us see this word that is come to pass, which the Lord hath shewed to us."],[16,"And they came with haste; and they found Mary and Joseph, and the infant lying in the manger."],[17,"And seeing, they understood of the word that had been spoken to them concerning this child."],[18,"And all that heard, wondered; and at those things that were told them by the shepherds."],[19,"But Mary kept all these words, pondering them in her heart."],[20,"And the shepherds returned, glorifying and praising God, for all the things they had heard and seen, as it was told unto them."]]},"Luke 2:22-38":{"tr":[[22,"Musa’nın Yasası uyarınca arınma günleri dolunca, Yusuf’la Meryem çocuğu Rab’be adamak için Yeruşalim’e götürdüler."],[23,"Rab’bin Yasası’nda yazıldığı gibi: “Rahmi ilk açan her erkek çocuk Rab’be adanmış sayılacak.”"],[24,"Rab’bin Yasası’nda söylendiği gibi, bir çift kumru ya da iki güvercin yavrusu kurban etmek için oraya gittiler."],[25,"Yeruşalim’de Şimon adında bir adam vardı. Doğru ve dindar biriydi; İsrail’in avutulmasını bekliyordu. Kutsal Ruh onun üzerindeydi."],[26,"Kutsal Ruh ona, Rab’bin Mesihi’ni görmeden ölmeyeceğini bildirmişti."],[27,"Ruh’un yönlendirmesiyle tapınağa geldi. Annesiyle babası, Yasa’nın gereğini yerine getirmek için çocuk İsa’yı içeri getirdiklerinde,"],[28,"Şimon çocuğu kucağına aldı ve Tanrı’yı övüp şöyle dedi:"],[29,"“Ya Rab, sözün uyarınca şimdi kulunu esenlik içinde salıveriyorsun."],[30,"Çünkü gözlerim senin kurtarışını gördü;"],[31,"bütün halkların gözü önünde hazırladığın kurtarışı."],[32,"O, uluslara yol gösteren bir ışık ve halkın İsrail’in yüceliğidir.”"],[33,"Çocuğun annesiyle babası, onun hakkında söylenenlere şaştılar."],[34,"Şimon onları kutsadı ve annesi Meryem’e şöyle dedi: “Bu çocuk İsrail’de birçoklarının düşmesine ve yükselmesine neden olmak ve karşı çıkılacak bir işaret olmak üzere belirlendi."],[35,"Senin yüreğini de bir kılıç delip geçecek. Öyle ki, birçok yürekteki düşünceler açığa çıksın.”"],[36,"Aşer oymağından Fanuel’in kızı Anna adında bir peygamber kadın vardı. Çok yaşlıydı; evlendikten sonra kocasıyla yedi yıl yaşamıştı."],[37,"Seksen dört yaşına kadar dul kalmıştı. Tapınaktan hiç ayrılmaz, oruç tutup dua ederek gece gündüz Tanrı’ya hizmet ederdi."],[38,"Tam o sırada gelip Tanrı’ya şükretti ve Yeruşalim’in kurtuluşunu bekleyen herkese çocuktan söz etti."]],"en":[[22,"And after the days of her purification, according to the law of Moses, were accomplished, they carried him to Jerusalem, to present him to the Lord:"],[23,"As it is written in the law of the Lord: Every male opening the womb shall be called holy to the Lord:"],[24,"And to offer a sacrifice, according as it is written in the law of the Lord, a pair of turtledoves, or two young pigeons:"],[25,"And behold there was a man in Jerusalem named Simeon, and this man was just and devout, waiting for the consolation of Israel; and the Holy Ghost was in him."],[26,"And he had received an answer from the Holy Ghost, that he should not see death, before he had seen the Christ of the Lord."],[27,"And he came by the Spirit into the temple. And when his parents brought in the child Jesus, to do for him according to the custom of the law,"],[28,"He also took him into his arms, and blessed God, and said:"],[29,"Now thou dost dismiss thy servant, O Lord, according to thy word in peace;"],[30,"Because my eyes have seen thy salvation,"],[31,"Which thou hast prepared before the face of all peoples:"],[32,"A light to the revelation of the Gentiles, and the glory of thy people Israel."],[33,"And his father and mother were wondering at those things which were spoken concerning him."],[34,"And Simeon blessed them, and said to Mary his mother: Behold this child is set for the fall, and for the resurrection of many in Israel, and for a sign which shall be contradicted;"],[35,"And thy own soul a sword shall pierce, that, out of many hearts, thoughts may be revealed."],[36,"And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser; she was far advanced in years, and had lived with her husband seven years from her virginity."],[37,"And she was a widow until fourscore and four years; who departed not from the temple, by fastings and prayers serving night and day."],[38,"Now she, at the same hour, coming in, confessed to the Lord; and spoke of him to all that looked for the redemption of Israel."]]},"Luke 2:41-52":{"tr":[[41,"İsa’nın annesiyle babası her yıl Fısıh Bayramı’nda Yeruşalim’e giderlerdi."],[42,"İsa on iki yaşındayken, bayram geleneği uyarınca yine Yeruşalim’e gittiler."],[43,"Bayram günlerinin sonunda eve dönerlerken, çocuk İsa Yeruşalim’de kaldı. Annesiyle babası bunun farkında değildi."],[44,"Onun kafilede olduğunu sanarak bir günlük yol aldılar. Sonra onu akrabaları ve tanıdıkları arasında aramaya başladılar."],[45,"Bulamayınca, onu aramak için Yeruşalim’e döndüler."],[46,"Üç gün sonra onu tapınakta, öğretmenlerin arasında oturmuş, onları dinlerken ve onlara sorular sorarken buldular."],[47,"Onu dinleyen herkes, anlayışına ve verdiği cevaplara şaşıp kalıyordu."],[48,"Annesiyle babası onu görünce hayret ettiler. Annesi ona, “Oğlum, bunu bize neden yaptın?” dedi. “Bak, baban da ben de seni büyük bir kaygıyla arıyorduk.”"],[49,"İsa onlara, “Beni neden aradınız?” dedi. “Babamın evinde bulunmam gerektiğini bilmiyor muydunuz?”"],[50,"Ama onlar, kendilerine söylediği sözü anlamadılar."],[51,"İsa onlarla birlikte Nasıra’ya döndü ve onların sözünü dinledi. Annesi bütün bu olayları yüreğinde saklıyordu."],[52,"İsa bilgelikte ve boyda gelişiyor, Tanrı’nın ve insanların beğenisini kazanıyordu."]],"en":[[41,"And his parents went every year to Jerusalem, at the solemn day of the pasch,"],[42,"And when he was twelve years old, they going up into Jerusalem, according to the custom of the feast,"],[43,"And having fulfilled the days, when they returned, the child Jesus remained in Jerusalem; and his parents knew it not."],[44,"And thinking that he was in the company, they came a day’s journey, and sought him among their kinsfolks and acquaintance."],[45,"And not finding him, they returned into Jerusalem, seeking him."],[46,"And it came to pass, that, after three days, they found him in the temple, sitting in the midst of the doctors, hearing them, and asking them questions."],[47,"And all that heard him were astonished at his wisdom and his answers."],[48,"And seeing him, they wondered. And his mother said to him: Son, why hast thou done so to us? behold thy father and I have sought thee sorrowing."],[49,"And he said to them: How is it that you sought me? did you not know, that I must be about my father’s business?"],[50,"And they understood not the word that he spoke unto them."],[51,"And he went down with them, and came to Nazareth, and was subject to them. And his mother kept all these words in her heart."],[52,"And Jesus advanced in wisdom, and age, and grace with God and men."]]},"Luke 3:3":{"tr":[[3,"Yahya Şeria Irmağı’nın bütün çevresini dolaşarak günahların bağışlanması için tövbe vaftizini duyurdu."]],"en":[[3,"And he came into all the country about the Jordan, preaching the baptism of penance for the remission of sins;"]]},"Luke 7:41-43":{"tr":[[41,"“Bir alacaklının iki borçlusu vardı. Birinin ona beş yüz, ötekinin elli dinar borcu vardı."],[42,"Borçlarını ödeyemedikleri için alacaklı ikisinin de borcunu bağışladı. Şimdi bunlardan hangisi onu daha çok sevecek?”"],[43,"Simun, “Sanırım, daha çok borcu bağışlanan” diye karşılık verdi. İsa, “Doğru yargıladın” dedi."]],"en":[[41,"A certain creditor had two debtors, the one who owed five hundred pence, and the other fifty."],[42,"And whereas they had not wherewith to pay, he forgave them both. Which therefore of the two loveth him most?"],[43,"Simon answering, said: I suppose that he to whom he forgave most. And he said to him: Thou hast judged rightly."]]},"Luke 9:31":{"tr":[[31,"Yücelik içinde görünen bu iki kişi, İsa’nın Yeruşalim’de gerçekleştireceği ayrılışından söz ediyorlardı."]],"en":[[31,"Appearing in majesty. And they spoke of his decease that he should accomplish in Jerusalem."]]},"Malachi 2:16":{"tr":[[16,"“Boşanmaktan nefret ediyorum” diyor İsrail’in Tanrısı RAB. “Karısını boşayan kişi giysisini zorbalıkla örtmüş olur” diyor Her Şeye Egemen RAB. “Bu yüzden kendinize dikkat edin, eşlerinize ihanet etmeyin.”"]],"en":[[16,"When thou shalt hate her put her away, saith the Lord the God of Israel: but iniquity shall cover his garment, saith the Lord of hosts, keep your spirit, and despise not."]]},"Mark 10:11-12":{"tr":[[11,"İsa onlara şöyle dedi: “Karısını boşayıp başka bir kadınla evlenen, karısına karşı zina etmiş olur."],[12,"Kocasını boşayıp başka bir erkekle evlenen kadın da zina etmiş olur.”"]],"en":[[11,"And he saith to them: Whosoever shall put away his wife and marry another, committeth adultery against her."],[12,"And if the wife shall put away her husband, and be married to another, she committeth adultery."]]},"Mark 10:45":{"tr":[[45,"“Çünkü İnsanoğlu da hizmet edilmeye değil, hizmet etmeye ve canını birçokları için fidye olarak vermeye geldi.”"]],"en":[[45,"For the Son of man also is not come to be ministered unto, but to minister, and to give his life a redemption for many."]]},"Mark 10:9":{"tr":[[9,"“Bu nedenle Tanrı’nın birleştirdiğini insan ayırmasın.”"]],"en":[[9,"What therefore God hath joined together, let not man put asunder."]]},"Mark 12:29":{"tr":[[29,"İsa şöyle karşılık verdi: “Birincisi şudur: ‘Dinle, ey İsrail! Tanrımız Rab tek Rab’dir."]],"en":[[29,"And Jesus answered him: The first commandment of all is, Hear, O Israel: the Lord thy God is one God."]]},"Mark 14:22":{"tr":[[22,"Onlar yemek yerken İsa eline ekmek aldı, şükredip kırdı ve onlara verdi. “Alın, bu benim bedenimdir” dedi."]],"en":[[22,"And whilst they were eating, Jesus took bread; and blessing, broke, and gave to them, and said: Take ye. This is my body."]]},"Mark 14:61-64":{"tr":[[61,"İsa ise susuyor, hiçbir yanıt vermiyordu. Başkâhin yine sordu: “Sen Yüce Olan’ın Oğlu Mesih misin?”"],[62,"İsa, “Benim” dedi. “İnsanoğlu’nun Kudretli Olan’ın sağında oturduğunu ve göklerin bulutlarıyla geldiğini göreceksiniz.”"],[63,"Bunun üzerine başkâhin giysilerini yırtıp şöyle dedi: “Artık tanığa ne gerek var?"],[64,"Küfrünü duydunuz. Ne düşünüyorsunuz?” Hepsi, onun ölümü hak ettiğine karar verdiler."]],"en":[[61,"But he held his peace, and answered nothing. Again the high priest asked him, and said to him: Art thou the Christ the Son of the blessed God?"],[62,"And Jesus said to him: I am. And you shall see the Son of man sitting on the right hand of the power of God, and coming with the clouds of heaven."],[63,"Then the high priest rending his garments, saith: What need we any further witnesses?"],[64,"You have heard the blasphemy. What think you? Who all condemned him to be guilty of death."]]},"Mark 16:2":{"tr":[[2,"Haftanın ilk günü sabah çok erken, güneş doğarken mezara gittiler."]],"en":[[2,"And very early in the morning, the first day of the week, they come to the sepulchre, the sun being now risen."]]},"Mark 1:14-15":{"tr":[[14,"Yahya tutuklandıktan sonra İsa Celile’ye gitti ve Tanrı Egemenliği’nin Müjdesi’ni duyurmaya başladı."],[15,"“Zaman doldu, Tanrı’nın Egemenliği yaklaştı. Tövbe edin, Müjde’ye iman edin!” diyordu."]],"en":[[14,"And after that John was delivered up, Jesus came into Galilee, preaching the gospel of the kingdom of God,"],[15,"And saying: The time is accomplished, and the kingdom of God is at hand: repent, and believe the gospel."]]},"Mark 2:19":{"tr":[[19,"İsa onlara şöyle karşılık verdi: “Güvey aralarındayken düğün çağrılıları oruç tutabilir mi? Güvey aralarında olduğu sürece oruç tutamazlar.”"]],"en":[[19,"And Jesus saith to them: Can the children of the marriage fast, as long as the bridegroom is with them? As long as they have the bridegroom with them, they cannot fast."]]},"Mark 2:27":{"tr":[[27,"İsa onlara, “Şabat Günü insan için yapıldı, insan Şabat Günü için yapılmadı” dedi."]],"en":[[27,"And he said to them: The sabbath was made for man, and not man for the sabbath."]]},"Mark 2:5-7":{"tr":[[5,"İsa onların imanını görünce felçliye, “Oğlum, günahların bağışlandı” dedi."],[6,"Orada oturan bazı din bilginleri içlerinden şöyle düşündüler:"],[7,"“Bu adam neden böyle konuşuyor? Küfrediyor! Tek olan Tanrı’dan başka kim günahları bağışlayabilir?”"]],"en":[[5,"And when Jesus had seen their faith, he saith to the sick of the palsy: Son, thy sins are forgiven thee."],[6,"And there were some of the scribes sitting there, and thinking in their hearts:"],[7,"Why doth this man speak thus? he blasphemeth. Who can forgive sins, but God only?"]]},"Mark 3:22-26":{"tr":[[22,"Yeruşalim’den gelen din bilginleri, “Onu Baalzevul ele geçirmiş” diyorlardı. “Cinleri, cinlerin önderinin gücüyle kovuyor.”"],[23,"İsa onları yanına çağırıp benzetmelerle konuştu: “Şeytan Şeytan’ı nasıl kovabilir?"],[24,"Bir ülke kendi içinde bölünürse ayakta duramaz."],[25,"Bir ev kendi içinde bölünürse ayakta duramaz."],[26,"Şeytan da kendine karşı ayaklanıp bölünürse ayakta duramaz, sonu gelir.”"]],"en":[[22,"And the scribes who were come down from Jerusalem, said: He hath Beelzebub, and by the prince of devils he casteth out devils."],[23,"And after he had called them together, he said to them in parables: How can Satan cast out Satan?"],[24,"And if a kingdom be divided against itself, that kingdom cannot stand."],[25,"And if a house be divided against itself, that house cannot stand."],[26,"And if Satan be risen up against himself, he is divided, and cannot stand, but hath an end."]]},"Mark 4:26-29":{"tr":[[26,"İsa şöyle dedi: “Tanrı’nın Egemenliği, toprağa tohum eken bir adama benzer."],[27,"Adam gece uyur, gündüz kalkar; bu arada tohum filizlenip büyür, ama nasıl olduğunu bilmez."],[28,"Toprak kendiliğinden ürün verir: önce filiz, sonra başak, sonra da başakta olgun tane."],[29,"Ürün olgunlaşınca adam hemen orağı vurur, çünkü hasat zamanı gelmiştir.”"]],"en":[[26,"And he said: So is the kingdom of God, as if a man should cast seed into the earth,"],[27,"And should sleep, and rise, night and day, and the seed should spring, and grow up whilst he knoweth not."],[28,"For the earth of itself bringeth forth fruit, first the blade, then the ear, afterwards the full corn in the ear."],[29,"And when the fruit is brought forth, immediately he putteth in the sickle, because the harvest is come."]]},"Matthew 10:16":{"tr":[[16,"“İşte, sizi kurtların arasına koyun gibi gönderiyorum. Bu yüzden yılanlar gibi akıllı, güvercinler gibi saf olun.”"]],"en":[[16,"Behold I send you as sheep in the midst of wolves. Be ye therefore wise as serpents and simple as doves."]]},"Matthew 10:37":{"tr":[[37,"“Annesini ya da babasını benden çok seven bana layık değildir. Oğlunu ya da kızını benden çok seven bana layık değildir.”"]],"en":[[37,"He that loveth father or mother more than me, is not worthy of me; and he that loveth son or daughter more than me, is not worthy of me."]]},"Matthew 11:27":{"tr":[[27,"“Babam her şeyi bana teslim etti. Oğul’u Baba’dan başka kimse tanımaz. Baba’yı da Oğul’dan ve Oğul’un O’nu tanıtmak istediği kişilerden başka kimse tanımaz.”"]],"en":[[27,"All things are delivered to me by my Father. And no one knoweth the Son, but the Father: neither doth any one know the Father, but the Son, and he to whom it shall please the Son to reveal him."]]},"Matthew 13:10-17":{"tr":[[10,"Öğrenciler İsa’ya gelip, “Onlara neden benzetmelerle konuşuyorsun?” diye sordular."],[11,"İsa şöyle karşılık verdi: “Göklerin Egemenliği’nin sırlarını bilmek size verildi, onlara verilmedi."],[12,"Çünkü kimde varsa ona daha çok verilecek ve bolluk içinde olacak. Ama kimde yoksa, elindeki de alınacak."],[13,"Onlarla benzetmelerle konuşmamın nedeni şu: Bakarlar ama görmezler, dinlerler ama işitmez ve anlamazlar."],[14,"Yeşaya’nın onlarla ilgili peygamberliği yerine geliyor: ‘Kulaklarınızla işitecek ama hiç anlamayacaksınız; gözlerinizle bakacak ama hiç görmeyeceksiniz."],[15,"Çünkü bu halkın yüreği duyarsızlaştı. Kulakları ağır işitiyor, gözlerini kapadılar. Öyle ki, gözleriyle görmesinler, kulaklarıyla işitmesinler, yürekleriyle anlayıp bana dönmesinler ve ben onları iyileştirmeyeyim.’"],[16,"Ama ne mutlu size, çünkü gözleriniz görüyor, kulaklarınız işitiyor!"],[17,"Size doğrusunu söyleyeyim, birçok peygamber ve doğru kişi sizin gördüklerinizi görmeyi özledi ama göremedi; sizin işittiklerinizi işitmeyi özledi ama işitemedi.”"]],"en":[[10,"And his disciples came and said to him: Why speakest thou to them in parables?"],[11,"Who answered and said to them: Because to you it is given to know the mysteries of the kingdom of heaven: but to them it is not given."],[12,"For he that hath, to him shall be given, and he shall abound: but he that hath not, from him shall be taken away that also which he hath."],[13,"Therefore do I speak to them in parables: because seeing they see not, and hearing they hear not, neither do they understand."],[14,"And the prophecy of Isaias is fulfilled in them, who saith: By hearing you shall hear, and shall not understand: and seeing you shall see, and shall not perceive."],[15,"For the heart of this people is grown gross, and with their ears they have been dull of hearing, and their eyes they have shut: lest at any time they should see with their eyes, and hear with their ears, and understand with their heart, and be converted, and I should heal them."],[16,"But blessed are your eyes, because they see, and your ears, because they hear."],[17,"For, amen, I say to you, many prophets and just men have desired to see the things that you see, and have not seen them, and to hear the things that you hear and have not heard them."]]},"Matthew 13:24-30":{"tr":[[24,"İsa onlara bir benzetme daha anlattı: “Göklerin Egemenliği, tarlasına iyi tohum eken bir adama benzer."],[25,"Ama herkes uyurken adamın düşmanı gelip buğdayın arasına delice ekti ve gitti."],[26,"Buğday filizlenip başak verince delice de ortaya çıktı."],[27,"Ev sahibinin köleleri gelip ona, ‘Efendimiz, sen tarlana iyi tohum ekmedin mi? Bu delice nereden çıktı?’ dediler."],[28,"O da, ‘Bunu bir düşman yaptı’ dedi. Köleler, ‘Gidip delicelerin hepsini toplamamızı ister misin?’ diye sordular."],[29,"‘Hayır’ dedi, ‘delicelerin hepsini toplarken buğdayı da onlarla birlikte kökünden sökebilirsiniz."],[30,"Bırakın, ikisi hasada kadar birlikte büyüsün. Hasat zamanı orakçılara, önce deliceleri toplayıp yakmak için demet demet bağlayın, sonra buğdayı ambarıma toplayın diyeceğim.’”"]],"en":[[24,"Another parable he proposed to them, saying: The kingdom of heaven is likened to a man that sowed good seeds in his field."],[25,"But while men were asleep, his enemy came and oversowed cockle among the wheat and went his way."],[26,"And when the blade was sprung up, and had brought forth fruit, then appeared also the cockle."],[27,"And the servants of the goodman of the house coming said to him: Sir, didst thou not sow good seed in thy field? whence then hath it cockle?"],[28,"And he said to them: An enemy hath done this. And the servants said to him: Wilt thou that we go and gather it up?"],[29,"And he said: No, lest perhaps gathering up the cockle, you root up the wheat also together with it."],[30,"Suffer both to grow until the harvest, and in the time of the harvest I will say to the reapers: Gather up first the cockle, and bind it into bundles to burn, but the wheat gather ye into my barn."]]},"Matthew 13:3-9":{"tr":[[3,"İsa onlara birçok şeyi benzetmelerle anlattı: “Ekinci tohum ekmeye çıktı."],[4,"Tohum ekerken bazı tohumlar yol kenarına düştü; kuşlar gelip onları yedi."],[5,"Bazıları, toprağı az olan kayalık yerlere düştü. Toprak derin olmadığı için hemen filizlendi."],[6,"Ama güneş doğunca kavruldu ve kökü olmadığı için kurudu."],[7,"Bazıları dikenler arasına düştü. Dikenler büyüyüp onları boğdu."],[8,"Bazıları da iyi toprağa düştü ve ürün verdi: kimi yüz, kimi altmış, kimi otuz kat."],[9,"Kulağı olan işitsin.”"]],"en":[[3,"And he spoke to them many things in parables, saying: Behold the sower went forth to sow."],[4,"And whilst he soweth some fell by the way side, and the birds of the air came and ate them up."],[5,"And other some fell upon stony ground, where they had not much earth: and they sprung up immediately, because they had no deepness of earth."],[6,"And when the sun was up they were scorched: and because they had not root, they withered away."],[7,"And others fell among thorns: and the thorns grew up and choked them."],[8,"And others fell upon good ground: and they brought forth fruit, some an hundredfold, some sixtyfold, and some thirtyfold."],[9,"He that hath ears to hear, let him hear."]]},"Matthew 13:31-32":{"tr":[[31,"İsa onlara bir benzetme daha anlattı: “Göklerin Egemenliği, bir adamın alıp tarlasına ektiği hardal tanesine benzer."],[32,"Hardal tanesi bütün tohumların en küçüğüdür. Ama büyüyünce bahçe bitkilerinin en büyüğü olur, bir ağaç olur; gökteki kuşlar gelip dallarına konar.”"]],"en":[[31,"Another parable he proposed unto them, saying: The kingdom of heaven is like to a grain of mustard seed, which a man took and sowed in his field."],[32,"Which is the least indeed of all seeds; but when it is grown up, it is greater than all herbs, and becometh a tree, so that the birds of the air come, and dwell in the branches thereof."]]},"Matthew 13:33":{"tr":[[33,"Onlara bir benzetme daha anlattı: “Göklerin Egemenliği, bir kadının alıp üç ölçek una karıştırdığı ve bütün hamuru kabartan mayaya benzer.”"]],"en":[[33,"Another parable he spoke to them: The kingdom of heaven is like to leaven, which a woman took and hid in three measures of meal, until the whole was leavened."]]},"Matthew 13:44":{"tr":[[44,"“Göklerin Egemenliği tarlaya gömülü bir hazineye benzer. Onu bulan adam yeniden gömer, sevincinden gidip nesi var nesi yok satar ve o tarlayı satın alır."]],"en":[[44,"The kingdom of heaven is like unto a treasure hidden in a field. Which a man having found, hid it, and for joy thereof goeth, and selleth all that he hath, and buyeth that field."]]},"Matthew 13:45-46":{"tr":[[45,"Yine Göklerin Egemenliği, güzel inciler arayan bir tüccara benzer."],[46,"Tüccar çok değerli bir inci bulunca gidip nesi var nesi yok satar ve o inciyi satın alır."]],"en":[[45,"Again the kingdom of heaven is like to a merchant seeking good pearls."],[46,"Who when he had found one pearl of great price, went his way, and sold all that he had, and bought it."]]},"Matthew 13:47-50":{"tr":[[47,"Yine Göklerin Egemenliği, denize atılan ve her türden balığı toplayan bir ağa benzer."],[48,"Ağ dolunca balıkçılar onu kıyıya çekerler. Oturup iyi balıkları kaplara toplar, işe yaramayanları atarlar."],[49,"Çağın sonunda da böyle olacak. Melekler gelip kötüleri doğruların arasından ayıracaklar"],[50,"ve onları ateşli fırına atacaklar. Orada ağlayış ve diş gıcırtısı olacak.”"]],"en":[[47,"Again the kingdom of heaven is like to a net cast into the sea, and gathering together of all kind of fishes."],[48,"Which, when it was filled, they drew out, and sitting by the shore, they chose out the good into vessels, but the bad they cast forth."],[49,"So shall it be at the end of the world. The angels shall go out, and shall separate the wicked from among the just."],[50,"And shall cast them into the furnace of fire: there shall be weeping and gnashing of teeth."]]},"Matthew 16:16":{"tr":[[16,"Simun Petrus, “Sen yaşayan Tanrı’nın Oğlu Mesih’sin” diye karşılık verdi."]],"en":[[16,"Simon Peter answered and said: Thou art Christ, the Son of the living God."]]},"Matthew 16:18":{"tr":[[18,"“Ben de sana şunu söyleyeyim: Sen Petrus’sun ve ben kilisemi bu kaya üzerine kuracağım. Ölüler diyarının kapıları ona karşı direnemeyecek."]],"en":[[18,"And I say to thee: That thou art Peter; and upon this rock I will build my church, and the gates of hell shall not prevail against it."]]},"Matthew 16:18-19":{"tr":[[18,"“Ben de sana şunu söyleyeyim: Sen Petrus’sun ve ben kilisemi bu kaya üzerine kuracağım. Ölüler diyarının kapıları ona karşı direnemeyecek."],[19,"Göklerin Egemenliği’nin anahtarlarını sana vereceğim. Yeryüzünde bağlayacağın her şey gökte de bağlanmış olacak; yeryüzünde çözeceğin her şey gökte de çözülmüş olacak.”"]],"en":[[18,"And I say to thee: That thou art Peter; and upon this rock I will build my church, and the gates of hell shall not prevail against it."],[19,"And I will give to thee the keys of the kingdom of heaven. And whatsoever thou shalt bind upon earth, it shall be bound also in heaven: and whatsoever thou shalt loose upon earth, it shall be loosed also in heaven."]]},"Matthew 16:19":{"tr":[[19,"Göklerin Egemenliği’nin anahtarlarını sana vereceğim. Yeryüzünde bağlayacağın her şey gökte de bağlanmış olacak; yeryüzünde çözeceğin her şey gökte de çözülmüş olacak.”"]],"en":[[19,"And I will give to thee the keys of the kingdom of heaven. And whatsoever thou shalt bind upon earth, it shall be bound also in heaven: and whatsoever thou shalt loose upon earth, it shall be loosed also in heaven."]]},"Matthew 17:1-8":{"tr":[[1,"Altı gün sonra İsa, yanına Petrus’u, Yakup’u ve Yakup’un kardeşi Yuhanna’yı alarak onları yüksek bir dağa, baş başa kalabilecekleri bir yere götürdü."],[2,"Orada onların önünde İsa’nın görünümü değişti. Yüzü güneş gibi parladı, giysileri ışık gibi bembeyaz oldu."],[3,"O anda Musa ile İlyas onlara göründü; İsa’yla konuşuyorlardı."],[4,"Petrus İsa’ya, “Ya Rab, burada olmamız ne iyi!” dedi. “İstersen burada üç çardak kurayım; biri sana, biri Musa’ya, biri de İlyas’a.”"],[5,"Petrus daha sözünü bitirmeden parlak bir bulut onları gölgeledi. Buluttan gelen bir ses, “Sevgili Oğlum budur, O’ndan hoşnudum, O’nu dinleyin!” dedi."],[6,"Öğrenciler bunu duyunca yüzüstü yere kapandılar, çok korktular."],[7,"İsa gelip onlara dokundu. “Kalkın, korkmayın” dedi."],[8,"Başlarını kaldırınca İsa’dan başka kimseyi görmediler."]],"en":[[1,"And after six days Jesus taketh unto him Peter and James, and John his brother, and bringeth them up into a high mountain apart:"],[2,"And he was transfigured before them. And his face did shine as the sun: and his garments became white as snow."],[3,"And behold there appeared to them Moses and Elias talking with him."],[4,"And Peter answering, said to Jesus: Lord, it is good for us to be here: if thou wilt, let us make here three tabernacles, one for thee, and one for Moses, and one for Elias."],[5,"And as he was yet speaking, behold a bright cloud overshadowed them. And lo, a voice out of the cloud, saying: This is my beloved Son, in whom I am well pleased: hear ye him."],[6,"And the disciples hearing, fell upon their face, and were very much afraid."],[7,"And Jesus came and touched them: and said to them, Arise, and fear not."],[8,"And they lifting up their eyes saw no one but only Jesus."]]},"Matthew 18:23-35":{"tr":[[23,"“Bu nedenle Göklerin Egemenliği, köleleriyle hesaplaşmak isteyen bir krala benzer."],[24,"Kral hesaplaşmaya başlayınca, kendisine on bin talant borcu olan bir köleyi getirdiler."],[25,"Borcunu ödeyemediği için efendisi, kendisinin, karısının, çocuklarının ve bütün malının satılıp borcun ödenmesini buyurdu."],[26,"Köle yere kapanıp, ‘Efendim, bana sabret, her şeyi ödeyeceğim’ diye yalvardı."],[27,"Efendisi köleye acıdı, onu serbest bıraktı ve borcunu bağışladı."],[28,"Ama köle dışarı çıkınca, kendisine yüz dinar borcu olan bir köle arkadaşını buldu. Onu yakalayıp boğazına sarıldı, ‘Borcunu öde!’ dedi."],[29,"Arkadaşı ayaklarına kapanıp, ‘Bana sabret, borcumu ödeyeceğim’ diye yalvardı."],[30,"Ama o istemedi; gidip borcunu ödeyinceye dek arkadaşını zindana attırdı."],[31,"Öbür köleler olanları görünce çok üzüldüler. Gidip bütün olanları efendilerine anlattılar."],[32,"Bunun üzerine efendisi köleyi çağırıp ona, ‘Seni kötü köle!’ dedi. ‘Bana yalvardığın için bütün borcunu bağışladım."],[33,"Benim sana acıdığım gibi senin de köle arkadaşına acıman gerekmez miydi?’"],[34,"Efendisi öfkelendi ve bütün borcunu ödeyinceye dek onu işkencecilere teslim etti."],[35,"Her biriniz kardeşini yürekten bağışlamazsanız, göksel Babam da size öyle davranacak.”"]],"en":[[23,"Therefore is the kingdom of heaven likened to a king, who would take an account of his servants."],[24,"And when he had begun to take the account, one was brought to him, that owed him ten thousand talents."],[25,"And as he had not wherewith to pay it, his lord commanded that he should be sold, and his wife and children and all that he had, and payment to be made."],[26,"But that servant falling down, besought him, saying: Have patience with me, and I will pay thee all."],[27,"And the lord of that servant being moved with pity, let him go and forgave him the debt."],[28,"But when that servant was gone out, he found one of his fellow servants that owed him an hundred pence: and laying hold of him, throttled him, saying: Pay what thou owest."],[29,"And his fellow servant falling down, besought him, saying: Have patience with me, and I will pay thee all."],[30,"And he would not: but went and cast him into prison, till he paid the debt."],[31,"Now his fellow servants seeing what was done, were very much grieved, and they came and told their lord all that was done."],[32,"Then his lord called him; and said to him: Thou wicked servant, I forgave thee all the debt, because thou besoughtest me:"],[33,"Shouldst not thou then have had compassion also on thy fellow servant, even as I had compassion on thee?"],[34,"And his lord being angry, delivered him to the torturers until he paid all the debt."],[35,"So also shall my heavenly Father do to you, if you forgive not every one his brother from your hearts."]]},"Matthew 19:12":{"tr":[[12,"“Çünkü ana rahminden hadım doğanlar var, insanlar tarafından hadım edilenler var, Göklerin Egemenliği uğruna kendilerini hadım edenler de var. Bunu kabul edebilen kabul etsin.”"]],"en":[[12,"For there are eunuchs, who were born so from their mother’s womb: and there are eunuchs, who were made so by men: and there are eunuchs, who have made themselves eunuchs for the kingdom of heaven. He that can take, let him take it."]]},"Matthew 19:16":{"tr":[[16,"Bir adam İsa’ya gelip, “Öğretmenim, sonsuz yaşama kavuşmak için ne iyilik yapmalıyım?” diye sordu."]],"en":[[16,"And behold one came and said to him: Good master, what good shall I do that I may have life everlasting?"]]},"Matthew 19:16-21":{"tr":[[16,"Bir adam İsa’ya gelip, “Öğretmenim, sonsuz yaşama kavuşmak için ne iyilik yapmalıyım?” diye sordu."],[17,"İsa ona, “Bana iyilik konusunda neden soru soruyorsun? İyi olan yalnız biri var, o da Tanrı’dır” dedi. “Yaşama kavuşmak istiyorsan, buyrukları yerine getir.”"],[18,"Adam, “Hangi buyrukları?” diye sordu. İsa şöyle dedi: “‘Adam öldürmeyeceksin, zina etmeyeceksin, çalmayacaksın, yalan yere tanıklık etmeyeceksin,"],[19,"annene babana saygı göstereceksin’ ve ‘Komşunu kendin gibi seveceksin.’”"],[20,"Genç adam, “Bunların hepsini gençliğimden beri yerine getirdim, daha neyim eksik?” dedi."],[21,"İsa ona şöyle dedi: “Eğer yetkin olmak istiyorsan, git, malını mülkünü sat, parasını yoksullara ver, göklerde hazinen olur. Sonra gel, beni izle.”"]],"en":[[16,"And behold one came and said to him: Good master, what good shall I do that I may have life everlasting?"],[17,"Who said to him: Why asketh thou me concerning good? One is good, God. But if thou wilt enter into life, keep the commandments."],[18,"He said to him: Which? And Jesus said: Thou shalt do no murder, Thou shalt not commit adultery, Thou shalt not steal, Thou shalt not bear false witness."],[19,"Honour thy father and thy mother: and, Thou shalt love thy neighbor as thyself."],[20,"The young man saith to him: All these I have kept from my youth, what is yet wanting to me?"],[21,"Jesus saith to him: If thou wilt be perfect, go sell what thou hast, and give to the poor, and thou shalt have treasure in heaven: and come follow me."]]},"Matthew 19:3-9":{"tr":[[3,"Bazı Ferisiler İsa’yı denemek için gelip, “Bir adamın herhangi bir nedenle karısını boşaması Kutsal Yasa’ya uygun mu?” diye sordular."],[4,"İsa şöyle karşılık verdi: “Yaradan’ın başlangıçtan beri onları erkek ve dişi olarak yarattığını okumadınız mı?"],[5,"Ve şöyle dedi: ‘Bu nedenle adam annesini babasını bırakıp karısına bağlanacak ve ikisi tek beden olacak.’"],[6,"Böylece artık iki değil, tek bedendirler. Bu nedenle Tanrı’nın birleştirdiğini insan ayırmasın.”"],[7,"Ferisiler, “Öyleyse Musa neden boşanma belgesi verip karısını boşamasını buyurdu?” dediler."],[8,"İsa, “Yüreklerinizin katılığı yüzünden Musa karılarınızı boşamanıza izin verdi” dedi. “Ama başlangıçta böyle değildi."],[9,"Size şunu söyleyeyim: Fuhuş dışında bir nedenle karısını boşayıp başkasıyla evlenen zina etmiş olur. Boşanmış bir kadınla evlenen de zina etmiş olur.”"]],"en":[[3,"And there came to him the Pharisees tempting him, and saying: Is it lawful for a man to put away his wife for every cause?"],[4,"Who answering, said to them: Have ye not read, that he who made man from the beginning, Made them male and female? And he said:"],[5,"For this cause shall a man leave father and mother, and shall cleave to his wife, and they two shall be in one flesh."],[6,"Therefore now they are not two, but one flesh. What therefore God hath joined together, let no man put asunder."],[7,"They say to him: Why then did Moses command to give a bill of divorce, and to put away?"],[8,"He saith to them: Because Moses by reason of the hardness of your heart permitted you to put away your wives: but from the beginning it was not so."],[9,"And I say to you, that whosoever shall put away his wife, except it be for fornication, and shall marry another, committeth adultery: and he that shall marry her that is put away, committeth adultery."]]},"Matthew 19:6":{"tr":[[6,"Böylece artık iki değil, tek bedendirler. Bu nedenle Tanrı’nın birleştirdiğini insan ayırmasın.”"]],"en":[[6,"Therefore now they are not two, but one flesh. What therefore God hath joined together, let no man put asunder."]]},"Matthew 1:1":{"tr":[[1,"İbrahim oğlu, Davut oğlu İsa Mesih’in soy kütüğü."]],"en":[[1,"The book of the generation of Jesus Christ, the son of David, the son of Abraham:"]]},"Matthew 1:21":{"tr":[[21,"“Bir oğul doğuracak. Adını İsa koyacaksın, çünkü halkını günahlarından o kurtaracak.”"]],"en":[[21,"And she shall bring forth a son: and thou shalt call his name JESUS. For he shall save his people from their sins."]]},"Matthew 20:1-16":{"tr":[[1,"“Göklerin Egemenliği, bağında çalışacak işçi tutmak için sabah erkenden çıkan bir ev sahibine benzer."],[2,"Adam işçilerle günlüğü bir dinara anlaştı ve onları bağına gönderdi."],[3,"Sabah saat dokuza doğru yine dışarı çıktı ve çarşı meydanında boş duran başka adamlar gördü."],[4,"Onlara, ‘Siz de bağa gidin, hakkınız neyse veririm’ dedi. Onlar da gittiler."],[5,"Adam öğleye ve saat üçe doğru yine çıkıp aynı şeyi yaptı."],[6,"Saat beşe doğru yine çıktı, boş duran başkalarını buldu. Onlara, ‘Neden bütün gün burada boş duruyorsunuz?’ diye sordu."],[7,"‘Kimse bizi tutmadı da ondan’ dediler. Adam, ‘Siz de bağa gidin’ dedi."],[8,"Akşam olunca bağın sahibi kâhyasına, ‘İşçileri çağır, sonuncudan başlayarak birinciye kadar ücretlerini öde’ dedi."],[9,"Saat beşe doğru tutulan işçiler geldiler ve her biri bir dinar aldı."],[10,"İlk tutulanlar gelince daha fazla alacaklarını sandılar. Ama onlar da birer dinar aldılar."],[11,"Parayı alınca ev sahibine söylenmeye başladılar:"],[12,"‘Şu sonuncular yalnız bir saat çalıştı. Sen ise onları, günün yükünü ve kavurucu sıcağını çeken bizlerle bir tuttun.’"],[13,"Ev sahibi onlardan birine şöyle karşılık verdi: ‘Arkadaş, sana haksızlık etmiyorum. Benimle bir dinara anlaşmadın mı?"],[14,"Hakkını al, git. Ben bu sonuncuya da sana verdiğim kadar vermek istiyorum."],[15,"Kendi paramı istediğim gibi kullanmaya hakkım yok mu? Yoksa cömertliğimi kıskanıyor musun?’"],[16,"İşte böylece sonuncular birinci, birinciler sonuncu olacak.”"]],"en":[[1,"The kingdom of heaven is like to an householder, who went out early in the morning to hire labourers into his vineyard."],[2,"And having agreed with the labourers for a penny a day, he sent them into his vineyard."],[3,"And going about the third hour, he saw others standing in the market place idle."],[4,"And he said to them: Go you also into my vineyard, and I will give you what shall be just."],[5,"And they went their way. And again he went out about the sixth and the ninth hour, and did in like manner."],[6,"But about the eleventh hour he went out and found others standing, and he saith to them: Why stand you here all the day idle?"],[7,"They say to him: Because no man hath hired us. He saith to them: Go you also into my vineyard."],[8,"And when evening was come, the lord of the vineyard saith to his steward: Call the labourers and pay them their hire, beginning from the last even to the first."],[9,"When therefore they were come, that came about the eleventh hour, they received every man a penny."],[10,"But when the first also came, they thought that they should receive more: and they also received every man a penny."],[11,"And receiving it they murmured against the master of the house,"],[12,"Saying: These last have worked but one hour, and thou hast made them equal to us, that have borne the burden of the day and the heats."],[13,"But he answering said to one of them: Friend, I do thee no wrong: didst thou not agree with me for a penny?"],[14,"Take what is thine, and go thy way: I will also give to this last even as to thee."],[15,"Or, is it not lawful for me to do what I will? is thy eye evil, because I am good?"],[16,"So shall the last be first, and the first last. For many are called, but few chosen."]]},"Matthew 20:28":{"tr":[[28,"“Tıpkı İnsanoğlu’nun hizmet edilmeye değil, hizmet etmeye ve canını birçokları için fidye olarak vermeye geldiği gibi.”"]],"en":[[28,"Even as the Son of man is not come to be ministered unto, but to minister, and to give his life a redemption for many."]]},"Matthew 21:28-32":{"tr":[[28,"“Siz ne dersiniz? Bir adamın iki oğlu vardı. Birincisine gidip, ‘Oğlum, bugün git, bağda çalış’ dedi."],[29,"Oğlu, ‘İstemiyorum’ diye karşılık verdi. Ama sonra pişman olup gitti."],[30,"Adam ikinci oğluna gidip aynı şeyi söyledi. O da, ‘Hemen gidiyorum, efendim’ dedi, ama gitmedi."],[31,"Bu ikisinden hangisi babasının istediğini yaptı?” “Birincisi” dediler. İsa onlara şöyle dedi: “Size doğrusunu söyleyeyim, vergi görevlileri ve fahişeler Tanrı’nın Egemenliği’ne sizden önce giriyorlar."],[32,"Çünkü Yahya size doğruluk yolunu göstermeye geldi, ama siz ona inanmadınız. Vergi görevlileri ve fahişeler ise ona inandılar. Siz bunu gördükten sonra bile pişman olup ona inanmadınız.”"]],"en":[[28,"But what think you? A certain man had two sons; and coming to the first, he said: Son, go work today in my vineyard."],[29,"And he answering, said: I will not. But afterwards, being moved with repentance, he went."],[30,"And coming to the other, he said in like manner. And he answering, said: I go, Sir; and he went not."],[31,"Which of the two did the father’s will? They say to him: The first. Jesus saith to them: Amen I say to you, that the publicans and the harlots shall go into the kingdom of God before you."],[32,"For John came to you in the way of justice, and you did not believe him. But the publicans and the harlots believed him: but you, seeing it, did not even afterwards repent, that you might believe him."]]},"Matthew 21:33-41":{"tr":[[33,"“Bir benzetme daha dinleyin. Bir toprak sahibi bağ dikti, çevresini çitle çevirdi, içinde bir üzüm çukuru kazdı, bir bekçi kulesi yaptı. Sonra bağı bağcılara kiraya verip başka bir ülkeye gitti."],[34,"Bağ bozumu yaklaşınca, ürününü almak için kölelerini bağcılara gönderdi."],[35,"Bağcılar ise kölelerini yakaladılar; birini dövdüler, birini öldürdüler, birini de taşladılar."],[36,"Toprak sahibi bu kez öncekilerden daha çok köle gönderdi. Bağcılar onlara da aynı şeyi yaptılar."],[37,"Sonunda, ‘Oğluma saygı gösterirler’ diyerek oğlunu onlara gönderdi."],[38,"Ama bağcılar oğlunu görünce birbirlerine, ‘Mirasçı bu’ dediler. ‘Gelin, onu öldürelim, mirası bize kalsın.’"],[39,"Onu yakalayıp bağın dışına attılar ve öldürdüler."],[40,"Şimdi bağın sahibi gelince bu bağcılara ne yapacak?”"],[41,"Ona, “O kötüleri acımasızca yok edecek, bağı da ürünü zamanında kendisine verecek başka bağcılara kiraya verecek” dediler."]],"en":[[33,"Hear ye another parable. There was a man an householder, who planted a vineyard, and made a hedge round about it, and dug in it a press, and built a tower, and let it out to husbandmen; and went into a strange country."],[34,"And when the time of the fruits drew nigh, he sent his servants to the husbandmen that they might receive the fruits thereof."],[35,"And the husbandmen laying hands on his servants, beat one, and killed another, and stoned another."],[36,"Again he sent other servants more than the former; and they did to them in like manner."],[37,"And last of all he sent to them his son, saying: They will reverence my son."],[38,"But the husbandmen seeing the son, said among themselves: This is the heir: come, let us kill him, and we shall have his inheritance."],[39,"And taking him, they cast him forth out of the vineyard, and killed him."],[40,"When therefore the lord of the vineyard shall come, what will he do to those husbandmen?"],[41,"They say to him: He will bring those evil men to an evil end; and will let out his vineyard to other husbandmen, that shall render him the fruit in due season."]]},"Matthew 21:9":{"tr":[[9,"İsa’nın önünden giden ve arkasından gelen kalabalık, “Davut Oğlu’na hozana! Rab’bin adıyla gelene övgüler olsun! En yücelerde hozana!” diye bağırıyordu."]],"en":[[9,"And the multitudes that went before and that followed, cried, saying: Hosanna to the son of David: Blessed is he that cometh in the name of the Lord: Hosanna in the highest."]]},"Matthew 22:2-14":{"tr":[[2,"“Göklerin Egemenliği, oğlu için düğün şöleni hazırlayan bir krala benzer."],[3,"Kral, düğüne çağrılanları getirmek için kölelerini gönderdi, ama çağrılanlar gelmek istemediler."],[4,"Kral başka köleler gönderdi, onlara şöyle dedi: ‘Çağrılanlara söyleyin, ziyafetimi hazırladım. Boğalarım ve besili hayvanlarım kesildi, her şey hazır. Düğüne gelin!’"],[5,"Ama çağrılanlar aldırmadılar; biri tarlasına, öbürü ticaretine gitti."],[6,"Geri kalanlar ise kralın kölelerini yakalayıp hakaret ettiler ve öldürdüler."],[7,"Kral buna çok öfkelendi. Askerlerini gönderip o katilleri yok etti, kentlerini yaktı."],[8,"Sonra kölelerine şöyle dedi: ‘Düğün hazır, ama çağrılanlar buna layık değildi."],[9,"Siz ana yolların kavşaklarına gidin, bulduğunuz herkesi düğüne çağırın.’"],[10,"Köleler yollara çıkıp iyi kötü, buldukları herkesi topladılar. Düğün salonu konuklarla doldu."],[11,"Kral konukları görmek için içeri girince, orada düğün giysisi giymemiş bir adam gördü."],[12,"Ona, ‘Arkadaş, düğün giysisi olmadan buraya nasıl girdin?’ dedi. Adamın dili tutuldu."],[13,"Bunun üzerine kral hizmetkârlara, ‘Bunun elini ayağını bağlayıp dışarıdaki karanlığa atın’ dedi. ‘Orada ağlayış ve diş gıcırtısı olacak.’"],[14,"Çünkü çağrılanlar çok, ama seçilenler azdır.”"]],"en":[[2,"The kingdom of heaven is likened to a king, who made a marriage for his son."],[3,"And he sent his servants, to call them that were invited to the marriage; and they would not come."],[4,"Again he sent other servants, saying: Tell them that were invited, Behold, I have prepared my dinner; my beeves and fatlings are killed, and all things are ready: come ye to the marriage."],[5,"But they neglected, and went their own ways, one to his farm, and another to his merchandise."],[6,"And the rest laid hands on his servants, and having treated them contumeliously, put them to death."],[7,"But when the king had heard of it, he was angry, and sending his armies, he destroyed those murderers, and burnt their city."],[8,"Then he saith to his servants: The marriage indeed is ready; but they that were invited were not worthy."],[9,"Go ye therefore into the highways; and as many as you shall find, call to the marriage."],[10,"And his servants going forth into the ways, gathered together all that they found, both bad and good: and the marriage was filled with guests."],[11,"And the king went in to see the guests: and he saw there a man who had not on a wedding garment."],[12,"And he saith to him: Friend, how camest thou in hither not having a wedding garment? But he was silent."],[13,"Then the king said to the waiters: Bind his hands and feet, and cast him into the exterior darkness: there shall be weeping and gnashing of teeth."],[14,"For many are called, but few are chosen."]]},"Matthew 22:21":{"tr":[[21,"“Sezar’ın” dediler. Bunun üzerine İsa, “Öyleyse Sezar’ın hakkını Sezar’a, Tanrı’nın hakkını Tanrı’ya verin” dedi."]],"en":[[21,"They say to him: Caesar’s. Then he saith to them: Render therefore to Caesar the things that are Caesar’s; and to God, the things that are God’s."]]},"Matthew 22:37-40":{"tr":[[37,"İsa ona şöyle dedi: “‘Tanrın Rab’bi bütün yüreğinle, bütün canınla ve bütün aklınla seveceksin.’"],[38,"İlk ve en büyük buyruk budur."],[39,"İkincisi de buna benzer: ‘Komşunu kendin gibi seveceksin.’"],[40,"Kutsal Yasa’nın tümü ve peygamberlerin sözleri bu iki buyruğa dayanır.”"]],"en":[[37,"Jesus said to him: Thou shalt love the Lord thy God with thy whole heart, and with thy whole soul, and with thy whole mind."],[38,"This is the greatest and the first commandment."],[39,"And the second is like to this: Thou shalt love thy neighbor as thyself."],[40,"On these two commandments dependeth the whole law and the prophets."]]},"Matthew 23:27-28":{"tr":[[27,"“Vay başınıza, ey din bilginleri ve Ferisiler, sizi ikiyüzlüler! Sizler badanalı mezarlara benzersiniz. Onlar dışarıdan güzel görünür, ama içleri ölü kemikleriyle ve her türlü pislikle doludur."],[28,"Siz de dışarıdan insanlara doğru görünürsünüz, ama içiniz ikiyüzlülük ve kötülükle dolu.”"]],"en":[[27,"Woe to you scribes and Pharisees, hypocrites; because you are like to whited sepulchres, which outwardly appear to men beautiful, but within are full of dead men’s bones, and of all filthiness."],[28,"So you also outwardly indeed appear to men just; but inwardly you are full of hypocrisy and iniquity."]]},"Matthew 25:1-13":{"tr":[[1,"“O gün Göklerin Egemenliği, kandillerini alıp güveyi karşılamaya çıkan on kıza benzeyecek."],[2,"Bunlardan beşi akılsız, beşi akıllıydı."],[3,"Akılsızlar kandillerini aldılar, ama yanlarına yağ almadılar."],[4,"Akıllılar ise kandilleriyle birlikte kaplarda yağ da aldılar."],[5,"Güvey gecikince hepsi uyuklayıp uykuya daldılar."],[6,"Gece yarısı bir ses duyuldu: ‘İşte güvey geliyor! Onu karşılamaya çıkın!’"],[7,"Bunun üzerine kızların hepsi kalkıp kandillerini hazırladılar."],[8,"Akılsızlar akıllılara, ‘Yağınızdan biraz verin, kandillerimiz sönüyor’ dediler."],[9,"Akıllılar ise, ‘Olmaz, hem bize hem size yetmeyebilir’ dediler. ‘Satıcılara gidip kendinize yağ alın.’"],[10,"Onlar yağ almaya gidince güvey geldi. Hazır olan kızlar onunla birlikte düğün şölenine girdiler ve kapı kapandı."],[11,"Sonra öbür kızlar da gelip, ‘Efendimiz, efendimiz, bize kapıyı aç!’ dediler."],[12,"O ise, ‘Size doğrusunu söyleyeyim, sizi tanımıyorum’ dedi."],[13,"Bu nedenle uyanık durun, çünkü o günü de saati de bilmiyorsunuz.”"]],"en":[[1,"Then shall the kingdom of heaven be like to ten virgins, who taking their lamps went out to meet the bridegroom and the bride."],[2,"And five of them were foolish, and five wise."],[3,"But the five foolish, having taken their lamps, did not take oil with them:"],[4,"But the wise took oil in their vessels with the lamps."],[5,"And the bridegroom tarrying, they all slumbered and slept."],[6,"And at midnight there was a cry made: Behold the bridegroom cometh, go ye forth to meet him."],[7,"Then all those virgins arose and trimmed their lamps."],[8,"And the foolish said to the wise: Give us of your oil, for our lamps are gone out."],[9,"The wise answered, saying: Lest perhaps there be not enough for us and for you, go ye rather to them that sell, and buy for yourselves."],[10,"Now whilst they went to buy, the bridegroom came: and they that were ready, went in with him to the marriage, and the door was shut."],[11,"But at last come also the other virgins, saying: Lord, Lord, open to us."],[12,"But he answering said: Amen I say to you, I know you not."],[13,"Watch ye therefore, because you know not the day nor the hour."]]},"Matthew 25:14-30":{"tr":[[14,"“Göklerin Egemenliği, yolculuğa çıkacak olan bir adama benzer. Adam kölelerini çağırıp malını onlara emanet etti."],[15,"Her birine yeteneğine göre, birine beş talant, birine iki talant, birine de bir talant verdi ve yola çıktı."],[16,"Beş talant alan hemen gidip bu parayla ticaret yaptı ve beş talant daha kazandı."],[17,"İki talant alan da aynı şekilde iki talant daha kazandı."],[18,"Ama bir talant alan gidip toprağı kazdı ve efendisinin parasını sakladı."],[19,"Uzun bir süre sonra bu kölelerin efendisi dönüp onlarla hesaplaştı."],[20,"Beş talant alan gelip beş talant daha getirdi. ‘Efendim, bana beş talant emanet etmiştin. Bak, beş talant daha kazandım’ dedi."],[21,"Efendisi ona, ‘Aferin, iyi ve güvenilir köle!’ dedi. ‘Az şeyde güvenilir olduğun için seni çok şeyin başına geçireceğim. Efendinin sevincine katıl!’"],[22,"İki talant alan da gelip, ‘Efendim, bana iki talant emanet etmiştin. Bak, iki talant daha kazandım’ dedi."],[23,"Efendisi ona, ‘Aferin, iyi ve güvenilir köle!’ dedi. ‘Az şeyde güvenilir olduğun için seni çok şeyin başına geçireceğim. Efendinin sevincine katıl!’"],[24,"Sonra bir talant alan geldi. ‘Efendim, senin sert bir adam olduğunu biliyordum’ dedi. ‘Ekmediğin yerden biçer, harman savurmadığın yerden toplarsın."],[25,"Korktum, gidip talantını toprağa gömdüm. İşte, paran burada.’"],[26,"Efendisi ona şöyle karşılık verdi: ‘Seni kötü ve tembel köle! Ekmediğim yerden biçtiğimi, harman savurmadığım yerden topladığımı biliyordun, öyle mi?"],[27,"O halde paramı bankaya yatırmalıydın. Ben de dönünce paramı faiziyle geri alırdım."],[28,"Şimdi talantı elinden alın, on talantı olana verin."],[29,"Çünkü kimde varsa ona daha çok verilecek ve bolluk içinde olacak. Ama kimde yoksa, elindeki de alınacak."],[30,"Bu yararsız köleyi dışarıdaki karanlığa atın. Orada ağlayış ve diş gıcırtısı olacak.’”"]],"en":[[14,"For even as a man going into a far country, called his servants, and delivered to them his goods;"],[15,"And to one he gave five talents, and to another two, and to another one, to every one according to his proper ability: and immediately he took his journey."],[16,"And he that had received the five talents, went his way, and traded with the same, and gained other five."],[17,"And in like manner he that had received the two, gained other two."],[18,"But he that had received the one, going his way digged into the earth, and hid his lord’s money."],[19,"But after a long time the lord of those servants came, and reckoned with them."],[20,"And he that had received the five talents coming, brought other five talents, saying: Lord, thou didst deliver to me five talents, behold I have gained other five over and above."],[21,"His lord said to him: Well done, good and faithful servant, because thou hast been faithful over a few things, I will place thee over many things: enter thou into the joy of thy lord."],[22,"And he also that had received the two talents came and said: Lord, thou deliveredst two talents to me: behold I have gained other two."],[23,"His lord said to him: Well done, good and faithful servant: because thou hast been faithful over a few things, I will place thee over many things: enter thou into the joy of thy lord."],[24,"But he that had received the one talent, came and said: Lord, I know that thou art a hard man; thou reapest where thou hast not sown, and gatherest where thou hast not strewed."],[25,"And being afraid I went and hid thy talent in the earth: behold here thou hast that which is thine."],[26,"And his lord answering, said to him: Wicked and slothful servant, thou knewest that I reap where I sow not, and gather where I have not strewed:"],[27,"Thou oughtest therefore to have committed my money to the bankers, and at my coming I should have received my own with usury."],[28,"Take ye away therefore the talent from him, and give it to him that hath ten talents."],[29,"For to every one that hath shall be given, and he shall abound: but from him that hath not, that also which he seemeth to have shall be taken away."],[30,"And the unprofitable servant cast ye out into the exterior darkness. There shall be weeping and gnashing of teeth."]]},"Matthew 25:31-46":{"tr":[[31,"“İnsanoğlu kendi yüceliği içinde bütün meleklerle birlikte geldiği zaman, yüce tahtına oturacak."],[32,"Bütün uluslar onun önünde toplanacak. Çobanın koyunları keçilerden ayırdığı gibi, o da insanları birbirinden ayıracak."],[33,"Koyunları sağına, keçileri soluna koyacak."],[34,"O zaman Kral sağındakilere şöyle diyecek: ‘Ey Babam’ın kutsadıkları, gelin! Dünya kurulduğundan beri sizin için hazırlanmış olan egemenliği miras alın."],[35,"Çünkü acıkmıştım, bana yiyecek verdiniz. Susamıştım, bana içecek verdiniz. Yabancıydım, beni içeri aldınız."],[36,"Çıplaktım, beni giydirdiniz. Hastaydım, bana baktınız. Zindandaydım, yanıma geldiniz.’"],[37,"O zaman doğru kişiler ona şöyle karşılık verecekler: ‘Ya Rab, seni ne zaman aç görüp doyurduk, susamış görüp su verdik?"],[38,"Seni ne zaman yabancı görüp içeri aldık, çıplak görüp giydirdik?"],[39,"Seni ne zaman hasta ya da zindanda görüp yanına geldik?’"],[40,"Kral da onlara şöyle diyecek: ‘Size doğrusunu söyleyeyim, bu en önemsiz kardeşlerimden birine yaptığınızı bana yapmış oldunuz.’"],[41,"Sonra solundakilere şöyle diyecek: ‘Ey lanetliler, çekilin önümden! İblis ve melekleri için hazırlanmış sonsuz ateşe gidin."],[42,"Çünkü acıkmıştım, bana yiyecek vermediniz. Susamıştım, bana içecek vermediniz."],[43,"Yabancıydım, beni içeri almadınız. Çıplaktım, beni giydirmediniz. Hastaydım, zindandaydım, bana bakmadınız.’"],[44,"O zaman onlar da şöyle karşılık verecekler: ‘Ya Rab, seni ne zaman aç, susamış, yabancı, çıplak, hasta ya da zindanda görüp de sana hizmet etmedik?’"],[45,"O da onlara şöyle diyecek: ‘Size doğrusunu söyleyeyim, bu en önemsizlerden birine yapmadığınızı bana da yapmamış oldunuz.’"],[46,"Bunlar sonsuz cezaya, doğrular ise sonsuz yaşama gidecekler.”"]],"en":[[31,"And when the Son of man shall come in his majesty, and all the angels with him, then shall he sit upon the seat of his majesty."],[32,"And all nations shall be gathered together before him, and he shall separate them one from another, as the shepherd separateth the sheep from the goats:"],[33,"And he shall set the sheep on his right hand, but the goats on his left."],[34,"Then shall the king say to them that shall be on his right hand: Come, ye blessed of my Father, possess you the kingdom prepared for you from the foundation of the world."],[35,"For I was hungry, and you gave me to eat; I was thirsty, and you gave me to drink; I was a stranger, and you took me in:"],[36,"Naked, and you covered me: sick, and you visited me: I was in prison, and you came to me."],[37,"Then shall the just answer him, saying: Lord, when did we see thee hungry, and fed thee; thirsty, and gave thee drink?"],[38,"And when did we see thee a stranger, and took thee in? or naked, and covered thee?"],[39,"Or when did we see thee sick or in prison, and came to thee?"],[40,"And the king answering, shall say to them: Amen I say to you, as long as you did it to one of these my least brethren, you did it to me."],[41,"Then he shall say to them also that shall be on his left hand: Depart from me, you cursed, into everlasting fire which was prepared for the devil and his angels."],[42,"For I was hungry, and you gave me not to eat: I was thirsty, and you gave me not to drink."],[43,"I was a stranger, and you took me not in: naked, and you covered me not: sick and in prison, and you did not visit me."],[44,"Then they also shall answer him, saying: Lord, when did we see thee hungry, or thirsty, or a stranger, or naked, or sick, or in prison, and did not minister to thee?"],[45,"Then he shall answer them, saying: Amen I say to you, as long as you did it not to one of these least, neither did you do it to me."],[46,"And these shall go into everlasting punishment: but the just, into life everlasting."]]},"Matthew 25:40":{"tr":[[40,"Kral da onlara şöyle diyecek: ‘Size doğrusunu söyleyeyim, bu en önemsiz kardeşlerimden birine yaptığınızı bana yapmış oldunuz.’"]],"en":[[40,"And the king answering, shall say to them: Amen I say to you, as long as you did it to one of these my least brethren, you did it to me."]]},"Matthew 25:41":{"tr":[[41,"Sonra solundakilere şöyle diyecek: ‘Ey lanetliler, çekilin önümden! İblis ve melekleri için hazırlanmış sonsuz ateşe gidin."]],"en":[[41,"Then he shall say to them also that shall be on his left hand: Depart from me, you cursed, into everlasting fire which was prepared for the devil and his angels."]]},"Matthew 26:26":{"tr":[[26,"Onlar yemek yerken İsa eline ekmek aldı, şükredip kırdı ve öğrencilerine verdi. “Alın, yiyin, bu benim bedenimdir” dedi."]],"en":[[26,"And whilst they were at supper, Jesus took bread, and blessed, and broke: and gave to his disciples, and said: Take ye, and eat. This is my body."]]},"Matthew 26:28":{"tr":[[28,"“Bu benim kanımdır, birçokları için günahların bağışlanması amacıyla akıtılan antlaşma kanıdır.”"]],"en":[[28,"For this is my blood of the new testament, which shall be shed for many unto remission of sins."]]},"Matthew 26:36-46":{"tr":[[36,"Sonra İsa öğrencileriyle birlikte Getsemani denen yere geldi. Onlara, “Ben şuraya gidip dua edeyim, siz burada oturun” dedi."],[37,"Petrus’la Zebedi’nin iki oğlunu yanına aldı. Kederlenmeye ve sıkıntıya düşmeye başladı."],[38,"Onlara, “Ölesiye kederliyim” dedi. “Burada kalın, benimle birlikte uyanık durun.”"],[39,"Biraz ötede yüzüstü yere kapanıp şöyle dua etti: “Babam, mümkünse bu kâse benden uzaklaştırılsın. Yine de benim değil, senin istediğin olsun.”"],[40,"Öğrencilerinin yanına döndüğünde onları uyumuş buldu. Petrus’a, “Demek benimle birlikte bir saat bile uyanık kalamadınız!” dedi."],[41,"“Ayartılmamak için uyanık durup dua edin. Ruh isteklidir, ama beden güçsüzdür.”"],[42,"İsa ikinci kez gidip şöyle dua etti: “Babam, eğer ben içmeden bu kâsenin benden uzaklaştırılması mümkün değilse, senin istediğin olsun.”"],[43,"Dönüşünde onları yine uyumuş buldu. Gözlerini açık tutamıyorlardı."],[44,"Onları bırakıp yine gitti ve üçüncü kez aynı sözlerle dua etti."],[45,"Sonra öğrencilerin yanına dönerek onlara, “Hâlâ uyuyup dinleniyor musunuz?” dedi. “İşte, saat yaklaştı. İnsanoğlu günahkârların eline teslim ediliyor."],[46,"Kalkın, gidelim. İşte, bana ihanet eden yaklaştı.”"]],"en":[[36,"Then Jesus came with them into a country place which is called Gethsemani; and he said to his disciples: Sit you here, till I go yonder and pray."],[37,"And taking with him Peter and the two sons of Zebedee, he began to grow sorrowful and to be sad."],[38,"Then he saith to them: My soul is sorrowful even unto death: stay you here, and watch with me."],[39,"And going a little further, he fell upon his face, praying, and saying: My Father, if it be possible, let this chalice pass from me. Nevertheless not as I will, but as thou wilt."],[40,"And he cometh to his disciples, and findeth them asleep, and he saith to Peter: What? Could you not watch one hour with me?"],[41,"Watch ye, and pray that ye enter not into temptation. The spirit indeed is willing, but the flesh weak."],[42,"Again the second time, he went and prayed, saying: My Father, if this chalice may not pass away, but I must drink it, thy will be done."],[43,"And he cometh again and findeth them sleeping: for their eyes were heavy."],[44,"And leaving them, he went again: and he prayed the third time, saying the selfsame word."],[45,"Then he cometh to his disciples, and saith to them: Sleep ye now and take your rest; behold the hour is at hand, and the Son of man shall be betrayed into the hands of sinners."],[46,"Rise, let us go: behold he is at hand that will betray me."]]},"Matthew 26:44":{"tr":[[44,"Onları bırakıp yine gitti ve üçüncü kez aynı sözlerle dua etti."]],"en":[[44,"And leaving them, he went again: and he prayed the third time, saying the selfsame word."]]},"Matthew 26:52":{"tr":[[52,"Bunun üzerine İsa ona, “Kılıcını yerine koy!” dedi. “Kılıç çekenlerin hepsi kılıçla ölecek.”"]],"en":[[52,"Then Jesus saith to him: Put up again thy sword into its place: for all that take the sword shall perish with the sword."]]},"Matthew 27:27-31":{"tr":[[27,"O zaman valinin askerleri İsa’yı vali konağına götürüp bütün taburu O’nun çevresine topladılar."],[28,"Giysilerini çıkarıp sırtına kırmızı bir kaftan giydirdiler."],[29,"Dikenlerden bir taç örüp başına koydular, sağ eline de bir kamış tutuşturdular. Önünde diz çöküp, “Selam, ey Yahudiler’in Kralı!” diyerek O’nunla alay ettiler."],[30,"O’nun üzerine tükürdüler, elindeki kamışı alıp başına vurdular."],[31,"O’nunla alay ettikten sonra kaftanı üzerinden çıkardılar, kendi giysilerini giydirip O’nu çarmıha germeye götürdüler."]],"en":[[27,"Then the soldiers of the governor taking Jesus into the hall, gathered together unto him the whole band;"],[28,"And stripping him, they put a scarlet cloak about him."],[29,"And platting a crown of thorns, they put it upon his head, and a reed in his right hand. And bowing the knee before him, they mocked him, saying: Hail, king of the Jews."],[30,"And spitting upon him, they took the reed, and struck his head."],[31,"And after they had mocked him, they took off the cloak from him, and put on him his own garments, and led him away to crucify him."]]},"Matthew 28:13":{"tr":[[13,"“Şöyle deyin: ‘Biz uyurken öğrencileri gece gelip onu çaldılar.’”"]],"en":[[13,"Saying: Say you, His disciples came by night, and stole him away when we were asleep."]]},"Matthew 28:18-20":{"tr":[[18,"İsa yanlarına gelip onlarla konuştu: “Gökte ve yeryüzünde bütün yetki bana verildi."],[19,"Bu nedenle gidin, bütün ulusları öğrencim olarak yetiştirin; onları Baba, Oğul ve Kutsal Ruh’un adıyla vaftiz edin;"],[20,"size buyurduğum her şeye uymayı onlara öğretin. İşte ben, dünyanın sonuna dek her an sizinle birlikteyim.”"]],"en":[[18,"And Jesus coming, spoke to them, saying: All power is given to me in heaven and in earth."],[19,"Going therefore, teach ye all nations; baptizing them in the name of the Father, and of the Son, and of the Holy Ghost."],[20,"Teaching them to observe all things whatsoever I have commanded you: and behold I am with you all days, even to the consummation of the world."]]},"Matthew 28:19":{"tr":[[19,"Bu nedenle gidin, bütün ulusları öğrencim olarak yetiştirin; onları Baba, Oğul ve Kutsal Ruh’un adıyla vaftiz edin;"]],"en":[[19,"Going therefore, teach ye all nations; baptizing them in the name of the Father, and of the Son, and of the Holy Ghost."]]},"Matthew 28:20":{"tr":[[20,"size buyurduğum her şeye uymayı onlara öğretin. İşte ben, dünyanın sonuna dek her an sizinle birlikteyim.”"]],"en":[[20,"Teaching them to observe all things whatsoever I have commanded you: and behold I am with you all days, even to the consummation of the world."]]},"Matthew 3:13-17":{"tr":[[13,"O zaman İsa, Yahya tarafından vaftiz edilmek üzere Celile’den Şeria Irmağı’na, onun yanına geldi."],[14,"Ama Yahya, “Benim senin tarafından vaftiz edilmem gerekirken sen mi bana geliyorsun?” diyerek onu engellemeye çalıştı."],[15,"İsa ona, “Şimdilik buna izin ver. Çünkü doğru olan her şeyi bu şekilde yerine getirmemiz uygundur” diye karşılık verdi. Bunun üzerine Yahya razı oldu."],[16,"İsa vaftiz olur olmaz sudan çıktı. O anda gökler açıldı ve Tanrı’nın Ruhu’nun bir güvercin gibi inip üzerine geldiğini gördü."],[17,"Göklerden gelen bir ses, “Sevgili Oğlum budur, O’ndan hoşnudum” dedi."]],"en":[[13,"Then cometh Jesus from Galilee to the Jordan, unto John, to be baptized by him."],[14,"But John stayed him, saying: I ought to be baptized by thee, and comest thou to me?"],[15,"And Jesus answering, said to him: Suffer it to be so now. For so it becometh us to fulfill all justice. Then he suffered him."],[16,"And Jesus being baptized, forthwith came out of the water: and lo, the heavens were opened to him: and he saw the Spirit of God descending as a dove, and coming upon him."],[17,"And behold a voice from heaven, saying: This is my beloved Son, in whom I am well pleased."]]},"Matthew 3:17":{"tr":[[17,"Gökten bir ses, “Sevgili Oğlum budur, ondan hoşnudum” dedi."]],"en":[[17,"And behold a voice from heaven, saying: This is my beloved Son, in whom I am well pleased."]]},"Matthew 4:10":{"tr":[[10,"İsa ona, “Çekil git, Şeytan!” dedi. “‘Tanrın Rab’be tapacak, yalnız O’na kulluk edeceksin’ diye yazılmıştır.”"]],"en":[[10,"Then Jesus saith to him: Begone, Satan: for it is written, The Lord thy God shalt thou adore, and him only shalt thou serve."]]},"Matthew 4:4":{"tr":[[4,"İsa şöyle karşılık verdi: “‘İnsan yalnız ekmekle değil, Tanrı’nın ağzından çıkan her sözle yaşar’ diye yazılmıştır.”"]],"en":[[4,"Who answered and said: It is written, Not in bread alone doth man live, but in every word that proceedeth from the mouth of God."]]},"Matthew 4:8-9":{"tr":[[8,"İblis bu kez İsa’yı çok yüksek bir dağa çıkardı; ona dünyanın bütün krallıklarını ve görkemlerini gösterdi."],[9,"“Yere kapanıp bana taparsan, bütün bunları sana vereceğim” dedi."]],"en":[[8,"Again the devil took him up into a very high mountain, and shewed him all the kingdoms of the world, and the glory of them,"],[9,"And said to him: All these will I give thee, if falling down thou wilt adore me."]]},"Matthew 5:21-22":{"tr":[[21,"“Atalarımıza, ‘Adam öldürmeyeceksin, adam öldüren yargılanacak’ dendiğini duydunuz."],[22,"Ama ben size diyorum ki, kardeşine öfkelenen herkes yargılanacak. Kardeşine ‘Aptal!’ diyen, Yüksek Kurul’da yargılanacak. ‘Ahmak!’ diyen de cehennem ateşini hak edecek.”"]],"en":[[21,"You have heard that it was said to them of old: Thou shalt not kill. And whosoever shall kill shall be in danger of the judgment."],[22,"But I say to you, that whosoever is angry with his brother, shall be in danger of the judgment. And whosoever shall say to his brother, Raca, shall be in danger of the council. And whosoever shall say, Thou Fool, shall be in danger of hell fire."]]},"Matthew 5:28":{"tr":[[28,"“Ama ben size diyorum ki, bir kadına şehvetle bakan her erkek, yüreğinde onunla zina etmiş olur.”"]],"en":[[28,"But I say to you, that whosoever shall look on a woman to lust after her, hath already committed adultery with her in his heart."]]},"Matthew 5:3":{"tr":[[3,"“Ne mutlu ruhta yoksul olanlara! Çünkü Göklerin Egemenliği onlarındır."]],"en":[[3,"Blessed are the poor in spirit: for theirs is the kingdom of heaven."]]},"Matthew 5:3-12":{"tr":[[3,"“Ne mutlu ruhta yoksul olanlara! Çünkü Göklerin Egemenliği onlarındır."],[4,"Ne mutlu yaslı olanlara! Çünkü onlar teselli edilecekler."],[5,"Ne mutlu yumuşak huylu olanlara! Çünkü onlar yeryüzünü miras alacaklar."],[6,"Ne mutlu doğruluğa acıkıp susayanlara! Çünkü onlar doyurulacaklar."],[7,"Ne mutlu merhametli olanlara! Çünkü onlar merhamet bulacaklar."],[8,"Ne mutlu yüreği temiz olanlara! Çünkü onlar Tanrı’yı görecekler."],[9,"Ne mutlu barışı sağlayanlara! Çünkü onlara Tanrı’nın çocukları denecek."],[10,"Ne mutlu doğruluk uğruna zulüm görenlere! Çünkü Göklerin Egemenliği onlarındır."],[11,"Benim yüzümden insanlar size sövüp zulmettikleri, size karşı yalan yere her türlü kötü sözü söyledikleri zaman ne mutlu size!"],[12,"Sevinin, sevinçle coşun! Çünkü göklerdeki ödülünüz büyüktür. Sizden önceki peygamberlere de böyle zulmettiler.”"]],"en":[[3,"Blessed are the poor in spirit: for theirs is the kingdom of heaven."],[4,"Blessed are the meek: for they shall possess the land."],[5,"Blessed are they that mourn: for they shall be comforted."],[6,"Blessed are they that hunger and thirst after justice: for they shall have their fill."],[7,"Blessed are the merciful: for they shall obtain mercy."],[8,"Blessed are the clean of heart: for they shall see God."],[9,"Blessed are the peacemakers: for they shall be called children of God."],[10,"Blessed are they that suffer persecution for justice’ sake: for theirs is the kingdom of heaven."],[11,"Blessed are ye when they shall revile you, and persecute you, and speak all that is evil against you, untruly, for my sake:"],[12,"Be glad and rejoice, for your reward is very great in heaven. For so they persecuted the prophets that were before you."]]},"Matthew 5:39":{"tr":[[39,"Ama ben size diyorum ki, kötüye karşı direnmeyin. Sağ yanağınıza bir tokat atana öbür yanağınızı da çevirin."]],"en":[[39,"But I say to you not to resist evil: but if one strike thee on thy right cheek, turn to him also the other:"]]},"Matthew 5:9":{"tr":[[9,"Ne mutlu barışı sağlayanlara! Çünkü onlara Tanrı’nın çocukları denecek."]],"en":[[9,"Blessed are the peacemakers: for they shall be called children of God."]]},"Matthew 6:24":{"tr":[[24,"“Hiç kimse iki efendiye kulluk edemez. Ya birinden nefret edip ötekini sever, ya da birine bağlanıp ötekini hor görür. Siz hem Tanrı’ya hem paraya kulluk edemezsiniz.”"]],"en":[[24,"No man can serve two masters. For either he will hate the one, and love the other: or he will sustain the one, and despise the other. You cannot serve God and mammon."]]},"Matthew 6:6":{"tr":[[6,"“Ama sen dua edeceğin zaman iç odana gir, kapını kapa ve gizlide olan Babana dua et. Gizlilik içinde yapılanı gören Baban seni ödüllendirecek.”"]],"en":[[6,"But thou when thou shalt pray, enter into thy chamber, and having shut the door, pray to thy Father in secret: and thy Father who seeth in secret will repay thee."]]},"Matthew 6:7":{"tr":[[7,"Dua ederken putperestler gibi boş sözler yinelemeyin. Onlar söz çokluğuyla seslerini duyurabileceklerini sanırlar."]],"en":[[7,"And when you are praying, speak not much, as the heathens. For they think that in their much speaking they may be heard."]]},"Matthew 6:9":{"tr":[[9,"“Siz şöyle dua edin: ‘Göklerdeki Babamız, adın kutsal kılınsın.’”"]],"en":[[9,"Thus therefore shall you pray: Our Father who art in heaven, hallowed be thy name."]]},"Matthew 6:9-13":{"tr":[[9,"Siz şöyle dua edin: “Göklerdeki Babamız, adın kutsal kılınsın."],[10,"Egemenliğin gelsin. Gökte olduğu gibi yeryüzünde de senin istediğin olsun."],[11,"Gündelik ekmeğimizi bugün de bize ver."],[12,"Bize borçlu olanları bağışladığımız gibi, sen de bizim borçlarımızı bağışla."],[13,"Bizi ayartılmaya uğratma, kötü olandan kurtar.”"]],"en":[[9,"Thus therefore shall you pray: Our Father who art in heaven, hallowed be thy name."],[10,"Thy kingdom come. Thy will be done on earth as it is in heaven."],[11,"Give us this day our supersubstantial bread."],[12,"And forgive us our debts, as we also forgive our debtors."],[13,"And lead us not into temptation. But deliver us from evil. Amen."]]},"Matthew 7:12":{"tr":[[12,"“İnsanların size nasıl davranmasını istiyorsanız, siz de onlara öyle davranın. Kutsal Yasa’nın ve peygamberlerin öğrettiği budur.”"]],"en":[[12,"All things therefore whatsoever you would that men should do to you, do you also to them. For this is the law and the prophets."]]},"Matthew 7:24-27":{"tr":[[24,"“Bu sözlerimi duyup uygulayan herkes, evini kaya üzerine kuran akıllı adama benzer."],[25,"Yağmur yağdı, seller bastı, yeller esip o evi dövdü; ama ev yıkılmadı, çünkü temeli kaya üzerine kurulmuştu.”"],[26,"“Bu sözlerimi duyup da uygulamayan herkes, evini kum üzerine kuran akılsız adama benzer."],[27,"Yağmur yağdı, seller bastı, yeller esip o eve çarptı; ev de yıkıldı. Yıkılışı da korkunç oldu.”"]],"en":[[24,"Every one therefore that heareth these my words, and doth them, shall be likened to a wise man that built his house upon a rock,"],[25,"And the rain fell, and the floods came, and the winds blew, and they beat upon that house, and it fell not, for it was founded on a rock."],[26,"And every one that heareth these my words, and doth them not, shall be like a foolish man that built his house upon the sand,"],[27,"And the rain fell, and the floods came, and the winds blew, and they beat upon that house, and it fell, and great was the fall thereof."]]},"Matthew 7:7-8":{"tr":[[7,"“Dileyin, size verilecek; arayın, bulacaksınız; kapıyı çalın, size açılacak."],[8,"Çünkü her dileyen alır, arayan bulur, kapı çalana açılır.”"]],"en":[[7,"Ask, and it shall be given you: seek, and you shall find: knock, and it shall be opened to you."],[8,"For every one that asketh, receiveth: and he that seeketh, findeth: and to him that knocketh, it shall be opened."]]},"Numbers 11:25":{"tr":[[25,"RAB bulutun içinde inip Musa’yla konuştu. Onun üzerindeki Ruh’tan alıp yetmiş ileri gelenin üzerine koydu. Ruh üzerlerine konunca peygamberlik ettiler, ama bunu bir daha yapmadılar."]],"en":[[25,"And the Lord came down in a cloud, and spoke to him, taking away of the spirit that was in Moses, and giving to the seventy men. And when the spirit had rested on them they prophesied, nor did they cease afterwards."]]},"Numbers 21:8-9":{"tr":[[8,"RAB Musa’ya şöyle dedi: “Tunçtan bir yılan yap ve onu işaret olarak bir sırığın üstüne dik. Yılanın soktuğu kim ona bakarsa yaşayacak.”"],[9,"Musa da tunçtan bir yılan yapıp onu işaret olarak sırığın üstüne dikti. Yılanın soktuğu kişiler tunç yılana bakınca iyileşiyordu."]],"en":[[8,"And the Lord said to him: Make brazen serpent, and set it up for a sign: whosoever being struck shall look on it, shall live."],[9,"Moses therefore made a brazen serpent, and set it up for a sign: which when they that were bitten looked upon, they were healed."]]},"Numbers 25:1-3":{"tr":[[1,"İsrailliler Şittim’de kalırken halk Moavlı kadınlarla fuhşa başladı."],[2,"Bu kadınlar halkı ilahlarına sunulan kurbanlara çağırdılar. Halk yedi ve onların ilahlarına tapındı."],[3,"Böylece İsrail Peor’daki Baal’a bağlandı ve RAB’bin öfkesi İsrail’e karşı alevlendi."]],"en":[[1,"And Israel at that time abode in Settim, and the people committed fornication with the daughters of Moab,"],[2,"Who called them to their sacrifices. And they ate of them, and adored their gods."],[3,"And Israel was initiated to Beelphegor: upon which the Lord being angry,"]]},"Numbers 34:1-12":{"tr":[[1,"RAB Musa’ya şöyle dedi:"],[2,"“İsrail halkına şunu buyur: ‘Kenan ülkesine girdiğinizde, mülk olarak size düşecek toprak, sınırlarıyla birlikte Kenan ülkesidir."],[3,"Güney bölgeniz Edom sınırı boyunca Zin Çölü’nden başlayacak. Güney sınırınız doğuda Lut Gölü’nün ucundan başlayacak,"],[4,"Akrabbim yokuşunun güneyinden dönüp Zin’e uzanacak, Kadeş-Barnea’nın güneyinden geçip Hasar-Addar’a varacak ve oradan Asmon’a geçecek."],[5,"Sınır Asmon’dan Mısır Vadisi’ne dönecek ve denizde bitecek."],[6,"Batı sınırınız Akdeniz ve kıyısı olacak. Batı sınırınız budur."],[7,"Kuzey sınırınız şöyle olacak: Akdeniz’den Hor Dağı’na kadar bir çizgi çekeceksiniz."],[8,"Hor Dağı’ndan Levo-Hamat’a kadar çizeceksiniz; sınır Sedat’a uzanacak,"],[9,"oradan Zifron’a varıp Hasar-Enan’da bitecek. Kuzey sınırınız budur."],[10,"Doğu sınırınızı Hasar-Enan’dan Şefam’a kadar çizeceksiniz."],[11,"Sınır Şefam’dan Ayin’in doğusundaki Rivla’ya inecek, oradan inip Kinneret Gölü’nün doğu kıyısına varacak."],[12,"Sonra Şeria Irmağı boyunca inip Lut Gölü’nde bitecek. Dört bir yanıyla ülkeniz bu olacak.’”"]],"en":[[1,"And the Lord spoke to Moses, saying:"],[2,"Command the children of Israel, and then shalt say to them: When you are entered into the land of Chanaan, and it shall be fallen into your possession by lot, it shall be bounded by these limits:"],[3,"The south side shall begin from the wilderness of Sin, which is by Edom: and shall have the most salt sea for its furthest limits eastward:"],[4,"Which limits shall go round on the south side by the ascent of the Scorpion and so into Senna, and reach toward the south as far as Cadesbarne, from whence the frontiers shall go out to the town called Adar, and shall reach as far as Asemona."],[5,"And the limits shall fetch a compass from Asemona to the torrent of Egypt, and shall end in the shore of the great sea."],[6,"And the west side shall begin from the great sea, and the same shall be the end thereof."],[7,"But toward the north side the borders shall begin from the great sea, reaching to the most high mountain,"],[8,"From which they shall come to Emath, as far as the borders of Sedada:"],[9,"And the limits shall go as far as Zephrona, and the village of Enan. These shall be the borders on the north side."],[10,"From thence they shall mark out the bounds towards the east side from the village of Enan unto Sephama."],[11,"And from Sephama the bounds shall go down to Rebla over against the fountain of Daphnis: from thence they shall come eastward to the sea of Cenereth,"],[12,"And shall reach as far as the Jordan, and at the last shall be closed in by the most salt sea. This shall be your land with its borders round about."]]},"Philippians 2:12":{"tr":[[12,"Bu nedenle, sevgili kardeşlerim, her zaman söz dinlediğiniz gibi, yalnız ben yanınızdayken değil, özellikle şimdi yanınızda değilken korku ve saygıyla kurtuluşunuzu sonuca ulaştırın."]],"en":[[12,"Wherefore, my dearly beloved, (as you have always obeyed, not as in my presence only, but much more now in my absence,) with fear and trembling work out your salvation."]]},"Philippians 2:13":{"tr":[[13,"Çünkü kendi iyi amacı uğruna hem isteğinizi hem eyleminizi etkileyen Tanrı’dır."]],"en":[[13,"For it is God who worketh in you, both to will and to accomplish, according to his good will."]]},"Philippians 2:6-11":{"tr":[[6,"O, Tanrı özüne sahip olduğu halde, Tanrı’ya eşitliği sımsıkı sarılacak bir hak saymadı."],[7,"Ama kul özünü alıp insan benzeyişinde doğarak kendini boşalttı."],[8,"İnsan biçiminde görünerek ölüme, çarmıh üzerinde ölüme bile boyun eğerek kendini alçalttı."],[9,"Bunun için de Tanrı O’nu pek çok yükseltti ve O’na her adın üstünde olan adı bağışladı."],[10,"Öyle ki, İsa’nın adı anıldığında gökteki, yerdeki ve yer altındakilerin hepsi diz çöksün,"],[11,"ve her dil, Baba Tanrı’nın yüceliği için İsa Mesih’in Rab olduğunu açıkça söylesin."]],"en":[[6,"Who being in the form of God, thought it not robbery to be equal with God:"],[7,"But emptied himself, taking the form of a servant, being made in the likeness of men, and in habit found as a man."],[8,"He humbled himself, becoming obedient unto death, even to the death of the cross."],[9,"For which cause God also hath exalted him, and hath given him a name which is above all names:"],[10,"That in the name of Jesus every knee should bow, of those that are in heaven, on earth, and under the earth:"],[11,"And that every tongue should confess that the Lord Jesus Christ is in the glory of God the Father."]]},"Philippians 2:8":{"tr":[[8,"İnsan biçiminde görünerek ölüme, çarmıh üzerinde ölüme bile boyun eğerek kendini alçalttı."]],"en":[[8,"He humbled himself, becoming obedient unto death, even to the death of the cross."]]},"Philippians 2:9":{"tr":[[9,"Bunun için de Tanrı O’nu pek çok yükseltti ve O’na her adın üstünde olan adı bağışladı."]],"en":[[9,"For which cause God also hath exalted him, and hath given him a name which is above all names:"]]},"Philippians 3:21":{"tr":[[21,"O, her şeyi kendine bağımlı kılmasını sağlayan güçle bizim düşkün bedenimizi değiştirip kendi yüce bedenine benzetecektir."]],"en":[[21,"Who will reform the body of our lowness, made like to the body of his glory, according to the operation whereby also he is able to subdue all things unto himself."]]},"Philippians 3:8":{"tr":[[8,"Bundan da öte, Rabbim Mesih İsa’yı tanımanın üstün değeri yanında her şeyi zarar sayıyorum. O’nun uğruna her şeyi yitirdim. Mesih’i kazanmak için hepsini süprüntü sayıyorum."]],"en":[[8,"Furthermore I count all things to be but loss for the excellent knowledge of Jesus Christ my Lord; for whom I have suffered the loss of all things, and count them but as dung, that I may gain Christ:"]]},"Psalm 119:105":{"tr":[[105,"Sözün adımlarım için kandil, yolum için ışıktır."]],"en":[[105,"NUN. Thy word is a lamp to my feet, and a light to my paths."]]},"Psalm 24:8":{"tr":[[8,"Kimdir bu yüce Kral? Güçlü ve yiğit RAB, savaşta yiğit olan RAB."]],"en":[[8,"Who is this King of Glory? the Lord who is strong and mighty: the Lord mighty in battle."]]},"Psalm 51:19":{"tr":[[19,"Tanrı’nın istediği kurban kırık bir ruhtur. Kırık ve pişman bir yüreği küçümsemezsin, ey Tanrı."]],"en":[[19,"A sacrifice to God is an afflicted spirit: a contrite and humbled heart, O God, thou wilt not despise."]]},"Revelation 12:1":{"tr":[[1,"Gökte büyük bir belirti göründü: Güneşe bürünmüş bir kadın; ayın üzerinde duruyor, başında on iki yıldızdan bir taç var."]],"en":[[1,"And a great sign appeared in heaven: A woman clothed with the sun, and the moon under her feet, and on her head a crown of twelve stars:"]]},"Revelation 12:9":{"tr":[[9,"Bütün dünyayı saptıran ve İblis ya da Şeytan denen büyük ejderha, o eski yılan yere atıldı. Onunla birlikte melekleri de atıldı."]],"en":[[9,"And that great dragon was cast out, that old serpent, who is called the devil and Satan, who seduceth the whole world; and he was cast unto the earth, and his angels were thrown down with him."]]},"Revelation 17:14":{"tr":[[14,"“Bunlar Kuzu’ya karşı savaşacaklar. Ama Kuzu onları yenecek. Çünkü O rablerin Rabbi, kralların Kralı’dır. O’nunla birlikte olan çağrılmışlar, seçilmişler ve sadık olanlar da onları yenecek.”"]],"en":[[14,"These shall fight with the Lamb, and the Lamb shall overcome them, because he is Lord of lords, and King of kings, and they that are with him are called, and elect, and faithful."]]},"Revelation 19:20":{"tr":[[20,"Canavar ve onun adına belirtiler gösteren sahte peygamber yakalandı. Sahte peygamber bu belirtilerle canavarın işaretini almış olanları ve canavarın heykeline tapanları saptırmıştı. Bu ikisi, kükürtle yanan ateş gölüne diri diri atıldı."]],"en":[[20,"And the beast was taken, and with him the false prophet, who wrought signs before him, wherewith he seduced them who received the character of the beast, and who adored his image. These two were cast alive into the pool of fire, burning with brimstone."]]},"Revelation 1:17":{"tr":[[17,"O’nu görünce ölü gibi ayaklarının dibine yığıldım. O ise sağ elini üzerime koyarak şöyle dedi: “Korkma! İlk ve son benim.”"]],"en":[[17,"And when I had seen him, I fell at his feet as dead. And he laid his right hand upon me, saying: Fear not. I am the First and the Last,"]]},"Revelation 21:4":{"tr":[[4,"“Onların gözlerinden bütün yaşları silecek. Artık ölüm olmayacak. Yas, ağlayış, acı da olmayacak. Çünkü önceki düzen geçip gitti.”"]],"en":[[4,"And God shall wipe away all tears from their eyes: and death shall be no more, nor mourning, nor crying, nor sorrow shall be any more, for the former things are passed away."]]},"Revelation 22:20":{"tr":[[20,"Bunlara tanıklık eden, “Evet, tez geliyorum!” diyor. Amin! Gel, Rab İsa!"]],"en":[[20,"He that giveth testimony of these things, saith, Surely I come quickly: Amen. Come, Lord Jesus."]]},"Revelation 2:1-7":{"tr":[[1,"“Efes’teki kilisenin meleğine yaz: Sağ elinde yedi yıldızı tutan, yedi altın kandillik arasında yürüyen şöyle diyor:"],[2,"Yaptıklarını, emeğini, sabrını biliyorum. Kötüleri hoş görmediğini, elçi olmadıkları halde elçi olduklarını söyleyenleri sınadığını ve yalancı olduklarını gördüğünü biliyorum."],[3,"Sabrın var, benim adım uğruna sıkıntılara katlandın ve yorulmadın."],[4,"Ne var ki, sana karşı bir şikâyetim var: İlk sevgini bıraktın."],[5,"Ne kadar yüksekten düştüğünü hatırla. Tövbe et ve ilk yaptıklarını yap. Tövbe etmezsen yanına gelip kandilliğini yerinden kaldıracağım."],[6,"Ama şu yanın var: Nikolaosçuların yaptıklarından nefret ediyorsun. Ben de onlardan nefret ediyorum."],[7,"Kulağı olan, Ruh’un kiliselere ne dediğini işitsin. Galip gelene Tanrı’nın cennetindeki yaşam ağacından yemeyi bağışlayacağım.”"]],"en":[[1,"Unto the angel of the church of Ephesus write: These things saith he, who holdeth the seven stars in his right hand, who walketh in the midst of the seven golden candlesticks:"],[2,"I know thy works, and thy labour, and thy patience, and how thou canst not bear them that are evil, and thou hast tried them, who say they are apostles, and are not, and hast found them liars:"],[3,"And thou hast patience, and hast endured for my name, and hast not fainted."],[4,"But I have somewhat against thee, because thou hast left thy first charity."],[5,"Be mindful therefore from whence thou art fallen: and do penance, and do the first works. Or else I come to thee, and will move thy candlestick out of its place, except thou do penance."],[6,"But this thou hast, that thou hatest the deeds of the Nicolaites, which I also hate."],[7,"He, that hath an ear, let him hear what the Spirit saith to the churches: To him, that overcometh, I will give to eat of the tree of life, which is in the paradise of my God."]]},"Revelation 2:12-17":{"tr":[[12,"“Bergama’daki kilisenin meleğine yaz: Keskin, iki ağızlı kılıcı olan şöyle diyor:"],[13,"Nerede yaşadığını biliyorum. Şeytan’ın tahtı oradadır. Yine de adıma sımsıkı bağlısın. Şeytan’ın yaşadığı yerde, aranızda öldürülen sadık tanığım Antipas’ın günlerinde bile bana olan imanını inkâr etmedin."],[14,"Ne var ki, sana karşı birkaç şikâyetim var: Aranızda Balam’ın öğretisine uyanlar var. Balam, putlara sunulan kurbanların etini yemeleri ve fuhuş yapmaları için İsrailliler’in yoluna tuzak kurmayı Balak’a öğretmişti."],[15,"Aynı şekilde, aranızda Nikolaosçuların öğretisine uyanlar da var."],[16,"Bu yüzden tövbe et! Yoksa yakında yanına gelip ağzımdaki kılıçla onlara karşı savaşacağım."],[17,"Kulağı olan, Ruh’un kiliselere ne dediğini işitsin. Galip gelene saklı mandan vereceğim. Ona üzerinde yeni bir ad yazılı beyaz bir taş da vereceğim. Bu adı, alandan başka kimse bilmez.”"]],"en":[[12,"And to the angel of the church of Pergamus write: These things, saith he, that hath the sharp two edged sword:"],[13,"I know where thou dwellest, where the seat of Satan is: and thou holdest fast my name, and hast not denied my faith. Even in those days when Antipas was my faithful witness, who was slain among you, where Satan dwelleth."],[14,"But I have against thee a few things: because thou hast there them that hold the doctrine of Balaam, who taught Balac to cast a stumblingblock before the children of Israel, to eat, and to commit fornication:"],[15,"So hast thou also them that hold the doctrine of the Nicolaites."],[16,"In like manner do penance: if not, I will come to thee quickly, and will fight against them with the sword of my mouth."],[17,"He, that hath an ear, let him hear what the Spirit saith to the churches: To him that overcometh, I will give the hidden manna, and will give him a white counter, and in the counter, a new name written, which no man knoweth, but he that receiveth it."]]},"Revelation 2:18-29":{"tr":[[18,"“Tiyatira’daki kilisenin meleğine yaz: Gözleri alev alev, ayakları parlak tunç gibi olan Tanrı Oğlu şöyle diyor:"],[19,"Yaptıklarını, sevgini, imanını, hizmetini ve sabrını biliyorum. Son yaptıklarının ilk yaptıklarından çok olduğunu biliyorum."],[20,"Ne var ki, sana karşı bir şikâyetim var: Kendine peygamber diyen İzebel denen kadına göz yumuyorsun. O, öğretisiyle kullarımı fuhuş yapmaya, putlara sunulan kurbanların etini yemeye yöneltip saptırıyor."],[21,"Tövbe etmesi için ona süre tanıdım, ama fuhşundan tövbe etmek istemiyor."],[22,"İşte, onu yatağa düşüreceğim. Onun yaptıklarından tövbe etmezlerse, onunla zina edenleri de büyük sıkıntıya sokacağım."],[23,"Çocuklarını öldüreceğim. Böylece bütün kiliseler, düşünceleri ve yürekleri araştıranın ben olduğumu anlayacaklar. Her birinize yaptıklarınıza göre karşılık vereceğim."],[24,"Ama Tiyatira’da bu öğretiye uymayan, bazılarının ‘Şeytan’ın derin sırları’ dediği şeyleri öğrenmemiş olan geri kalanlarınıza şunu söylüyorum: Üzerinize başka bir yük koymayacağım."],[25,"Yalnız, ben gelinceye dek elinizde olana sımsıkı sarılın."],[26,"Galip gelene ve sonuna dek isteğimi yerine getirene uluslar üzerinde yetki vereceğim."],[27,"Babam’dan aldığım yetkiyle o, ulusları demir çomakla güdecek, onları çömlek gibi kıracak."],[28,"Ona sabah yıldızını da vereceğim."],[29,"Kulağı olan, Ruh’un kiliselere ne dediğini işitsin.”"]],"en":[[18,"And to the angel of the church of Thyatira write: These things saith the Son of God, who hath his eyes like to a flame of fire, and his feet like to fine brass."],[19,"I know thy works, and thy faith, and thy charity, and thy ministry, and thy patience, and thy last works which are more than the former."],[20,"But I have against thee a few things: because thou sufferest the woman Jezabel, who calleth herself a prophetess, to teach, and to seduce my servants, to commit fornication, and to eat of things sacrificed to idols."],[21,"And I gave her a time that she might do penance, and she will not repent of her fornication."],[22,"Behold, I will cast her into a bed: and they that commit adultery with her shall be in very great tribulation, except they do penance from their deeds."],[23,"And I will kill her children with death, and all the churches shall know that I am he that searcheth the reins and hearts, and I will give to every one of you according to your works. But to you I say,"],[24,"And to the rest who are at Thyatira: Whosoever have not this doctrine, and who have not known the depths of Satan, as they say, I will not put upon you any other burthen."],[25,"Yet that, which you have, hold fast till I come."],[26,"And he that shall overcome, and keep my works unto the end, I will give him power over the nations."],[27,"And he shall rule them with a rod of iron, and as the vessel of a potter they shall be broken,"],[28,"As I also have received of my Father: and I will give him the morning star."],[29,"He that hath an ear, let him hear what the Spirit saith to the churches."]]},"Revelation 2:8-11":{"tr":[[8,"“İzmir’deki kilisenin meleğine yaz: İlk ve son olan, ölmüş ve yeniden yaşama kavuşmuş olan şöyle diyor:"],[9,"Çektiğin sıkıntıyı ve yoksulluğunu biliyorum. Ama sen zenginsin! Yahudi olmadıkları halde Yahudi olduklarını söyleyenlerin sövgülerini de biliyorum. Onlar Şeytan’ın havrasıdır."],[10,"Çekeceğin acılardan korkma! İşte, denenmeniz için İblis bazılarınızı zindana atmak üzere. On gün sıkıntı çekeceksiniz. Ölüm pahasına sadık kal, sana yaşam tacını vereceğim."],[11,"Kulağı olan, Ruh’un kiliselere ne dediğini işitsin. Galip gelen ikinci ölümden hiç zarar görmeyecek.”"]],"en":[[8,"And to the angel of the church of Smyrna write: These things saith the First and the Last, who was dead, and is alive:"],[9,"I know thy tribulation and thy poverty, but thou art rich: and thou art blasphemed by them that say they are Jews and are not, but are the synagogue of Satan."],[10,"Fear none of those things which thou shalt suffer. Behold, the devil will cast some of you into prison that you may be tried: and you shall have tribulation ten days. Be thou faithful until death: and I will give thee the crown of life."],[11,"He, that hath an ear, let him hear what the Spirit saith to the churches: He that shall overcome, shall not be hurt by the second death."]]},"Revelation 3:1-6":{"tr":[[1,"“Sard’daki kilisenin meleğine yaz: Tanrı’nın yedi ruhuna ve yedi yıldıza sahip olan şöyle diyor: Yaptıklarını biliyorum. Yaşıyor diye tanınıyorsun, ama ölüsün."],[2,"Uyan! Geriye kalan ve ölmek üzere olan şeyleri güçlendir. Çünkü yaptıklarının Tanrım’ın gözünde eksiksiz olmadığını gördüm."],[3,"Aldığın ve duyduğun öğretiyi hatırla. Ona uy ve tövbe et. Eğer uyanmazsan hırsız gibi geleceğim; hangi saatte geleceğimi bilmeyeceksin."],[4,"Ama Sard’da giysilerini kirletmemiş birkaç kişi var. Onlar beyazlar giyinip benimle birlikte yürüyecekler, çünkü buna layıktırlar."],[5,"Galip gelen böylece beyazlar giyinecek. Onun adını yaşam kitabından hiçbir zaman silmeyeceğim. Babam’ın ve meleklerinin önünde onun adını açıkça anacağım."],[6,"Kulağı olan, Ruh’un kiliselere ne dediğini işitsin.”"]],"en":[[1,"And to the angel of the church of Sardis, write: These things saith he, that hath the seven spirits of God, and the seven stars: I know thy works, that thou hast the name of being alive: and thou art dead."],[2,"Be watchful and strengthen the things that remain, which are ready to die. For I find not thy works full before my God."],[3,"Have in mind therefore in what manner thou hast received and heard: and observe, and do penance. If then thou shalt not watch, I will come to thee as a thief, and thou shalt not know at what hour I will come to thee."],[4,"But thou hast a few names in Sardis, which have not defiled their garments: and they shall walk with me in white, because they are worthy."],[5,"He that shall overcome, shall thus be clothed in white garments, and I will not blot out his name out of the book of life, and I will confess his name before my Father, and before his angels."],[6,"He that hath an ear, let him hear what the Spirit saith to the churches."]]},"Revelation 3:14":{"tr":[[14,"“Laodikya’daki kilisenin meleğine yaz: Amin olan, sadık ve gerçek tanık, Tanrı’nın yaratılışının başlangıcı şöyle diyor:"]],"en":[[14,"And to the angel of the church of Laodicea, write: These things saith the Amen, the faithful and true witness, who is the beginning of the creation of God:"]]},"Revelation 3:14-22":{"tr":[[14,"“Laodikya’daki kilisenin meleğine yaz: Amin olan, sadık ve gerçek tanık, Tanrı’nın yaratılışının başlangıcı şöyle diyor:"],[15,"Yaptıklarını biliyorum. Ne soğuksun, ne sıcak. Keşke soğuk ya da sıcak olsaydın!"],[16,"Ama ılık olduğun, ne sıcak ne soğuk olduğun için seni ağzımdan kusacağım."],[17,"Zenginim, servet edindim, hiçbir şeye gereksinimim yok diyorsun. Oysa zavallı, acınacak halde, yoksul, kör ve çıplak olduğunu bilmiyorsun."],[18,"Sana öğüt veriyorum: Zengin olmak için benden ateşte arıtılmış altın satın al. Çıplaklığının utancını örtmek için giyeceğin beyaz giysileri, görebilmek için de gözlerine süreceğin merhemi benden satın al."],[19,"Ben sevdiklerimin hepsini azarlar, terbiye ederim. Bu nedenle gayrete gel, tövbe et."],[20,"İşte, kapıda durmuş kapıyı çalıyorum. Biri sesimi işitir ve kapıyı açarsa, onun yanına gireceğim. Ben onunla, o da benimle birlikte yemek yiyecek."],[21,"Galip gelene, benim galip gelip Babam’la birlikte O’nun tahtına oturduğum gibi, benimle birlikte tahtıma oturma hakkını vereceğim."],[22,"Kulağı olan, Ruh’un kiliselere ne dediğini işitsin.”"]],"en":[[14,"And to the angel of the church of Laodicea, write: These things saith the Amen, the faithful and true witness, who is the beginning of the creation of God:"],[15,"I know thy works, that thou art neither cold, nor hot. I would thou wert cold, or hot."],[16,"But because thou art lukewarm, and neither cold, not hot, I will begin to vomit thee out of my mouth."],[17,"Because thou sayest: I am rich, and made wealthy, and have need of nothing: and knowest not, that thou art wretched, and miserable, and poor, and blind, and naked."],[18,"I counsel thee to buy of me gold fire tried, that thou mayest be made rich; and mayest be clothed in white garments, and that the shame of thy nakedness may not appear; and anoint thy eyes with eyesalve, that thou mayest see."],[19,"Such as I love, I rebuke and chastise. Be zealous therefore, and do penance."],[20,"Behold, I stand at the gate, and knock. If any man shall hear my voice, and open to me the door, I will come in to him, and will sup with him, and he with me."],[21,"To him that shall overcome, I will give to sit with me in my throne: as I also have overcome, and am set down with my Father in his throne."],[22,"He that hath an ear, let him hear what the Spirit saith to the churches."]]},"Revelation 3:7-13":{"tr":[[7,"“Filadelfya’daki kilisenin meleğine yaz: Kutsal ve gerçek olan, Davut’un anahtarını taşıyan, kimsenin kapatamayacağı biçimde açan ve kimsenin açamayacağı biçimde kapatan şöyle diyor:"],[8,"Yaptıklarını biliyorum. İşte önüne kimsenin kapatamayacağı açık bir kapı koydum. Gücünün az olduğunu biliyorum. Yine de sözüme uydun ve adımı inkâr etmedin."],[9,"İşte, Yahudi olmadıkları halde Yahudi olduklarını söyleyen yalancıları, Şeytan’ın havrasından olanları getirip ayaklarının önünde yere kapanmalarını sağlayacağım. Seni sevdiğimi anlayacaklar."],[10,"Sabırla dayanmaya ilişkin buyruğuma uyduğun için, ben de yeryüzünde yaşayanları denemek üzere bütün dünyanın başına gelecek olan deneme saatinde seni koruyacağım."],[11,"Tez geliyorum! Kimse tacını elinden almasın diye elinde olana sımsıkı sarıl."],[12,"Galip geleni Tanrım’ın tapınağında bir direk yapacağım. Oradan bir daha hiç ayrılmayacak. Onun üzerine Tanrım’ın adını, Tanrım’ın kentinin, yani Tanrım’ın yanından, gökten inecek olan yeni Yeruşalim’in adını ve benim yeni adımı yazacağım."],[13,"Kulağı olan, Ruh’un kiliselere ne dediğini işitsin.”"]],"en":[[7,"And to the angel of the church of Philadelphia, write: These things saith the Holy One and the true one, he that hath the key of David; he that openeth, and no man shutteth; shutteth, and no man openeth:"],[8,"I know thy works. Behold, I have given before thee a door opened, which no man can shut: because thou hast a little strength, and hast kept my word, and hast not denied my name."],[9,"Behold, I will bring of the synagogue of Satan, who say they are Jews, and are not, but do lie. Behold, I will make them to come and adore before thy feet. And they shall know that I have loved thee."],[10,"Because thou hast kept the word of my patience, I will also keep thee from the hour of the temptation, which shall come upon the whole world to try them that dwell upon the earth."],[11,"Behold, I come quickly: hold fast that which thou hast, that no man take thy crown."],[12,"He that shall overcome, I will make him a pillar in the temple of my God; and he shall go out no more; and I will write upon him the name of my God, and the name of the city of my God, the new Jerusalem, which cometh down out of heaven from my God, and my new name."],[13,"He that hath an ear, let him hear what the Spirit saith to the churches."]]},"Revelation 4:8":{"tr":[[8,"Dört yaratığın her birinin altışar kanadı vardı; her yanları, içleri dışları gözlerle doluydu. Gece gündüz durmadan şöyle diyorlardı: “Kutsal, kutsal, kutsaldır her şeye gücü yeten Rab Tanrı! O vardı, vardır ve gelecektir.”"]],"en":[[8,"And the four living creatures had each of them six wings; and round about and within they are full of eyes. And they rested not day and night, saying: Holy, holy, holy, Lord God Almighty, who was, and who is, and who is to come."]]},"Revelation 5:8":{"tr":[[8,"Kuzu tomarı alınca, dört yaratıkla yirmi dört ihtiyar O’nun önünde yere kapandılar. Her birinin elinde birer lir ve kutsalların duaları olan buhurla dolu altın taslar vardı."]],"en":[[8,"And when he had opened the book, the four living creatures, and the four and twenty ancients fell down before the Lamb, having every one of them harps, and golden vials full of odours, which are the prayers of saints:"]]},"Revelation 7:9":{"tr":[[9,"Bundan sonra baktım, her ulustan, her oymaktan, her halktan, her dilden, kimsenin sayamayacağı kadar büyük bir kalabalık tahtın ve Kuzu’nun önünde duruyordu. Beyaz kaftanlar giymişlerdi, ellerinde hurma dalları vardı."]],"en":[[9,"After this I saw a great multitude, which no man could number, of all nations, and tribes, and peoples, and tongues, standing before the throne, and in sight of the Lamb, clothed with white robes, and palms in their hands:"]]},"Romans 12:2":{"tr":[[2,"Bu dünyanın gidişine uymayın; bunun yerine, Tanrı’nın iyi, beğenilir ve yetkin isteğinin ne olduğunu ayırt edebilmek için düşüncenizin yenilenmesiyle değişin."]],"en":[[2,"And be not conformed to this world; but be reformed in the newness of your mind, that you may prove what is the good, and the acceptable, and the perfect will of God."]]},"Romans 1:5":{"tr":[[5,"O’nun aracılığıyla, O’nun adı uğruna bütün uluslar arasında imandan kaynaklanan söz dinlemeyi sağlamak için lütuf ve elçilik görevini aldık."]],"en":[[5,"By whom we have received grace and apostleship for obedience to the faith, in all nations, for his name;"]]},"Romans 4:11-18":{"tr":[[11,"İbrahim, daha sünnet edilmeden önce imanla aklandığını gösteren bir mühür olarak sünnet belirtisini aldı. Öyle ki, sünnetsiz oldukları halde iman eden herkesin babası olsun ve onlar da doğru sayılsın."],[12,"Aynı zamanda, yalnız sünnetli olmakla kalmayıp atamız İbrahim’in sünnet edilmeden önce sahip olduğu imanın izinden yürüyen sünnetlilerin de babasıdır."],[13,"İbrahim’e ve soyuna, dünyanın mirasçısı olacağı sözü Kutsal Yasa aracılığıyla değil, imandan gelen doğruluk aracılığıyla verildi."],[14,"Eğer Yasa’ya dayananlar mirasçı olursa, iman boşa çıkar, söz de geçersiz olur."],[15,"Çünkü Yasa gazabı doğurur. Yasa’nın olmadığı yerde Yasa’yı çiğneme de olmaz."],[16,"İşte bu nedenle vaat imana dayanır. Öyle ki, lütuf sonucu olsun ve yalnız Yasa’ya bağlı olanlar için değil, İbrahim’in imanına sahip olanlar için de, yani bütün soy için geçerli olsun. İbrahim hepimizin babasıdır."],[17,"Yazılmış olduğu gibi: “Seni birçok ulusun babası yaptım.” İbrahim, ölüleri dirilten ve var olmayan şeyleri var olan şeylermiş gibi çağıran Tanrı’nın önünde iman etti."],[18,"İbrahim, umudun olmadığı yerde umutla iman etti ve kendisine, “Senin soyun böyle olacak” dendiği gibi birçok ulusun babası oldu."]],"en":[[11,"And he received the sign of circumcision, a seal of the justice of the faith, which he had, being uncircumcised; that he might be the father of all them that believe, being uncircumcised, that unto them also it may be reputed to justice:"],[12,"And might be the father of circumcision; not to them only, that are of the circumcision, but to them also that follow the steps of the faithful, that is in the uncircumcision of our father Abraham."],[13,"For not through the law was the promise to Abraham, or to his seed, that he should be heir of the world; but through the justice of faith."],[14,"For if they who are of the law be heirs, faith is made void, the promise is made of no effect."],[15,"For the law worketh wrath. For where there is no law, neither is there transgression."],[16,"Therefore is it of faith, that according to grace the promise might be firm to all the seed; not to that only which is of the law, but to that also which is of the faith of Abraham, who is the father of us all,"],[17,"(As it is written: I have made thee a father of many nations,) before God, whom he believed, who quickeneth the dead; and calleth those things that are not, as those that are."],[18,"Who against hope believed in hope; that he might be made the father of many nations, according to that which was said to him: So shall thy seed be."]]},"Romans 4:3":{"tr":[[3,"Kutsal Yazı ne diyor? “İbrahim Tanrı’ya iman etti ve bu ona doğruluk sayıldı.”"]],"en":[[3,"For what saith the scripture? Abraham believed God, and it was reputed to him unto justice."]]},"Romans 8:15":{"tr":[[15,"Çünkü sizi yeniden korkuya sürükleyecek kölelik ruhunu almadınız. Tersine, Tanrı’nın oğulları olmanızı sağlayan Ruh’u aldınız. Bu Ruh aracılığıyla, “Abba, Baba!” diye yakarırız."]],"en":[[15,"For you have not received the spirit of bondage again in fear; but you have received the spirit of adoption of sons, whereby we cry: Abba (Father)."]]},"Romans 8:26":{"tr":[[26,"Aynı şekilde Ruh da zayıflığımızda bize yardım eder. Çünkü nasıl dua etmemiz gerektiğini bilmiyoruz; ama Ruh’un kendisi sözle anlatılamaz iniltilerle bizim için aracılık eder."]],"en":[[26,"Likewise the Spirit also helpeth our infirmity. For we know not what we should pray for as we ought; but the Spirit himself asketh for us with unspeakable groanings."]]},"Romans 9:4,5":{"tr":[[4,"Onlar İsraillidir. Tanrı’nın oğulları olma hakkı, yücelik, antlaşmalar, Kutsal Yasa, tapınma ve vaatler onlarındır."],[5,"Atalar onlarındır ve Mesih bedence onlardandır. O her şeyin üzerinde, sonsuza dek övülecek Tanrı’dır. Amin."]],"en":[[4,"Who are Israelites, to whom belongeth the adoption as of children, and the glory, and the testament, and the giving of the law, and the service of God, and the promises:"],[5,"Whose are the fathers, and of whom is Christ, according to the flesh, who is over all things, God blessed for ever. Amen."]]},"Romans 9:4-5":{"tr":[[4,"Onlar İsraillidir. Tanrı’nın oğulları olma hakkı, yücelik, antlaşmalar, Kutsal Yasa, tapınma ve vaatler onlarındır."],[5,"Atalar onlarındır ve Mesih bedence onlardandır. O her şeyin üzerinde, sonsuza dek övülecek Tanrı’dır. Amin."]],"en":[[4,"Who are Israelites, to whom belongeth the adoption as of children, and the glory, and the testament, and the giving of the law, and the service of God, and the promises:"],[5,"Whose are the fathers, and of whom is Christ, according to the flesh, who is over all things, God blessed for ever. Amen."]]},"Titus 2:13":{"tr":[[13,"Mutlu umudumuzun gerçekleşmesini, büyük Tanrımız ve Kurtarıcımız İsa Mesih’in yüceliğinin görünmesini bekliyoruz."]],"en":[[13,"Looking for the blessed hope and coming of the glory of the great God and our Saviour Jesus Christ,"]]},"Titus 3:5":{"tr":[[5,"Bizi kurtardı; bunu yaptığımız doğru işler yüzünden değil, kendi merhameti uyarınca, yeniden doğuşu sağlayan yıkanmayla ve Kutsal Ruh’un yenileyişiyle yaptı."]],"en":[[5,"Not by the works of justice, which we have done, but according to his mercy, he saved us, by the laver of regeneration, and renovation of the Holy Ghost;"]]},"1 Corinthians 5:7":{"tr":[[7,"Eski mayadan arının ki, yeni bir hamur olasınız. Zaten mayasızsınız. Çünkü Fısıh kuzumuz Mesih kurban edildi."]],"en":[[7,"Purge out the old leaven, that you may be a new paste, as you are unleavened. For Christ our pasch is sacrificed."]]},"1 Corinthians 7:18":{"tr":[[18,"Sünnetli olarak çağrılan biri sünnetsiz görünmeye çalışmasın. Sünnetsiz olarak çağrılan biri de sünnet olmasın."]],"en":[[18,"Is any man called, being circumcised? let him not procure uncircumcision. Is any man called in uncircumcision? let him not be circumcised."]]},"2 Chronicles 3:1":{"tr":[[1,"Süleyman, Rab’bin Tapınağı’nı Kudüs’te, Moriya dağında yapmaya başladı. Rab orada babası Davut’a görünmüştü. Burası, Davut’un belirlediği yer, Yevuslu Ornan’ın harman yeriydi."]],"en":[[1,"And Solomon began to build the house of the Lord in Jerusalem, in mount Moria, which had been shewn to David his father, in the place which David had prepared in the thrashingfloor of Ornan the Jebusite."]]},"Acts 21:20":{"tr":[[20,"Onlar bunu duyunca Tanrı’yı yücelttiler ve Pavlus’a şöyle dediler: “Kardeş, görüyorsun, Yahudiler arasında iman etmiş binlerce kişi var ve hepsi Kutsal Yasa’ya bağlılıkta gayretli."]],"en":[[20,"But they hearing it, glorified God, and said to him: Thou seest, brother, how many thousands there are among the Jews that have believed: and they are all zealous for the law."]]},"Acts 21:24-26":{"tr":[[24,"Bu adamları yanına al, onlarla birlikte arın ve başlarını tıraş ettirebilmeleri için masraflarını sen öde. Böylece herkes, senin hakkında duyduklarının asılsız olduğunu, senin de Yasa’ya uyarak yaşadığını anlayacak."],[25,"İman eden Yahudi olmayanlara gelince, onlara kararımızı yazdık: Putlara sunulan yiyeceklerden, kandan, boğulmuş hayvan etinden ve fuhuştan kaçınsınlar.”"],[26,"Bunun üzerine Pavlus adamları yanına aldı. Ertesi gün onlarla birlikte arındı ve Tapınağa girdi. Her biri için sunu sununcaya dek sürecek arınma günlerinin ne zaman tamamlanacağını bildirdi."]],"en":[[24,"Take these, and sanctify thyself with them: and bestow on them, that they may shave their heads: and all will know that the things which they have heard of thee, are false; but that thou thyself also walkest keeping the law."],[25,"But as touching the Gentiles that believe, we have written, decreeing that they should only refrain themselves from that which has been offered to idols, and from blood, and from things strangles, and from fornication."],[26,"Then Paul took the men, and the next day being purified with them, entered into the temple, giving notice of the accomplishment of the days of purification, until an oblation should be offered for every one of them."]]},"Acts 23:6":{"tr":[[6,"Pavlus, Yüksek Kurul’dakilerin bir kısmının Saduki, bir kısmının Ferisi olduğunu bilerek seslendi: “Kardeşler, ben Ferisiyim, Ferisi oğluyum. Ölülerin dirileceği umudu yüzünden yargılanıyorum!”"]],"en":[[6,"And Paul knowing that the one part were Sadducees, and the other Pharisees, cried out in the council: Men, brethren, I am a Pharisee, the son of Pharisees: concerning the hope and resurrection of the dead I am called in question."]]},"Acts 2:41":{"tr":[[41,"Petrus’un sözünü kabul edenler vaftiz edildi. O gün topluluğa yaklaşık üç bin kişi katıldı."]],"en":[[41,"They therefore that received his word, were baptized; and there were added in that day about three thousand souls."]]},"Acts 5:34-39":{"tr":[[34,"Ama Yüksek Kurul’da bütün halkın saydığı bir Kutsal Yasa öğretmeni, Gamaliel adında bir Ferisi ayağa kalktı ve havarilerin bir süre dışarı çıkarılmasını buyurdu."],[35,"Sonra kurula şöyle dedi: “Ey İsrailliler, bu adamlara ne yapacağınıza dikkat edin."],[36,"Bir süre önce Teudas ortaya çıktı, kendini önemli biri sanıyordu. Ona dört yüz kadar adam katıldı. Ama o öldürüldü ve ona uyanların hepsi dağılıp yok oldu."],[37,"Ondan sonra, nüfus sayımı günlerinde Celileli Yahuda ortaya çıktı ve birçok kişiyi peşinden sürükledi. O da yok oldu ve ona uyanların hepsi darmadağın oldu."],[38,"Şimdi size şunu söylüyorum: Bu adamlardan uzak durun, onları bırakın. Eğer bu tasarı ya da bu iş insandan geliyorsa kendiliğinden çöker."],[39,"Ama Tanrı’dan geliyorsa onları yıkamazsınız. Kendinizi Tanrı’ya karşı savaşırken bulmayın!”"]],"en":[[34,"But one in the council rising up, a Pharisee, named Gamaliel, a doctor of the law, respected by all the people, commanded the men to be put forth a little while."],[35,"And he said to them: Ye men of Israel, take heed to yourselves what you intend to do, as touching these men."],[36,"For before these days rose up Theodas, affirming himself to be somebody, to whom a number of men, about four hundred, joined themselves: who was slain; and all that believed him were scattered, and brought to nothing."],[37,"After this man, rose up Judas of Galilee, in the days of the enrolling, and drew away the people after him: he also perished; and all, even as many as consented to him, were dispersed."],[38,"And now, therefore, I say to you, refrain from these men, and let them alone; for if this council or this work be of men, it will come to nought;"],[39,"But if it be of God, you cannot overthrow it, lest perhaps you be found even to fight against God. And they consented to him."]]},"Daniel 7:13":{"tr":[[13,"Gece gördüğüm görümlerde baktım, göğün bulutlarıyla insanoğluna benzeyen biri geliyordu. Ezeli Olan’a doğru ilerledi ve onun önüne getirildi."]],"en":[[13,"I beheld therefore in the vision of the night, and lo, one like the son of man came with the clouds of heaven, and he came even to the Ancient of days: and they presented him before him."]]},"Daniel 9:24-26":{"tr":[[24,"Halkın ve kutsal kentin için yetmiş hafta belirlendi: isyanı bitirmek, günaha son vermek, suçu bağışlamak, sonsuz doğruluğu getirmek, görümü ve peygamberliği mühürlemek ve en kutsal olanı meshetmek için."],[25,"Şunu bil ve anla: Kudüs’ün yeniden kurulması için buyruk çıktığı andan meshedilmiş önderin gelişine kadar yedi hafta ve altmış iki hafta geçecek. Kent, meydanları ve hendekleriyle yeniden kurulacak, ama sıkıntılı zamanlarda."],[26,"Altmış iki haftadan sonra meshedilmiş olan ortadan kaldırılacak ve hiçbir şeyi kalmayacak. Gelecek önderin halkı kenti ve kutsal yeri yıkacak. Sonu bir sel gibi gelecek. Sona dek savaş sürecek, yıkımlar kararlaştırılmıştır."]],"en":[[24,"Seventy weeks are shortened upon thy people, and upon thy holy city, that transgression may be finished, and sin may have an end, and iniquity may be abolished; and everlasting justice may be brought; and vision and prophecy may be fulfilled; and the saint of saints may be anointed."],[25,"Know thou therefore, and take notice: that from the going forth of the word, to build up Jerusalem again, unto Christ the prince, there shall be seven weeks, and sixty-two weeks: and the street shall be built again, and the walls in straitness of times."],[26,"And after sixty-two weeks Christ shall be slain: and the people that shall deny him shall not be his. And a people with their leader that shall come, shall destroy the city and the sanctuary: and the end thereof shall be waste, and after the end of the war the appointed desolation."]]},"Daniel 9:24-27":{"tr":[[24,"Halkın ve kutsal kentin için yetmiş hafta belirlendi: isyanı bitirmek, günaha son vermek, suçu bağışlamak, sonsuz doğruluğu getirmek, görümü ve peygamberliği mühürlemek ve en kutsal olanı meshetmek için."],[25,"Şunu bil ve anla: Kudüs’ün yeniden kurulması için buyruk çıktığı andan meshedilmiş önderin gelişine kadar yedi hafta ve altmış iki hafta geçecek. Kent, meydanları ve hendekleriyle yeniden kurulacak, ama sıkıntılı zamanlarda."],[26,"Altmış iki haftadan sonra meshedilmiş olan ortadan kaldırılacak ve hiçbir şeyi kalmayacak. Gelecek önderin halkı kenti ve kutsal yeri yıkacak. Sonu bir sel gibi gelecek. Sona dek savaş sürecek, yıkımlar kararlaştırılmıştır."],[27,"Önder bir hafta boyunca birçoklarıyla sağlam bir antlaşma yapacak. Haftanın ortasında kurbana ve sunuya son verecek. Tiksinç şeylerin kanadı üzerinde yıkım getiren biri gelecek. Sonunda, kararlaştırılan yıkım yıkıcının üzerine dökülecek."]],"en":[[24,"Seventy weeks are shortened upon thy people, and upon thy holy city, that transgression may be finished, and sin may have an end, and iniquity may be abolished; and everlasting justice may be brought; and vision and prophecy may be fulfilled; and the saint of saints may be anointed."],[25,"Know thou therefore, and take notice: that from the going forth of the word, to build up Jerusalem again, unto Christ the prince, there shall be seven weeks, and sixty-two weeks: and the street shall be built again, and the walls in straitness of times."],[26,"And after sixty-two weeks Christ shall be slain: and the people that shall deny him shall not be his. And a people with their leader that shall come, shall destroy the city and the sanctuary: and the end thereof shall be waste, and after the end of the war the appointed desolation."],[27,"And he shall confirm the covenant with many, in one week: and in the half of the week the victim and the sacrifice shall fall: and there shall be in the temple the abomination of desolation: and the desolation shall continue even to the consummation, and to the end."]]},"Deuteronomy 21:23":{"tr":[[23,"Ölüsü gece boyunca ağaçta kalmamalı. Onu aynı gün gömmelisiniz. Çünkü ağaca asılan, Tanrı’nın lanetine uğramıştır. Tanrınız Rab’bin size mülk olarak verdiği toprağı kirletmeyeceksiniz."]],"en":[[23,"His body shall not remain upon the tree, but shall be buried the same day: for he is accursed of God that hangeth on a tree: and thou shalt not defile thy land, which the Lord thy God shall give thee in possession."]]},"Deuteronomy 25:13":{"tr":[[13,"Torbanda biri ağır biri hafif, iki farklı ağırlık taşımayacaksın."]],"en":[[13,"Thou shalt not have divers weights in thy bag, a greater and a less:"]]},"Deuteronomy 6:5":{"tr":[[5,"Tanrınız Rab’bi bütün yüreğinizle, bütün canınızla ve bütün gücünüzle seveceksiniz."]],"en":[[5,"Thou shalt love the Lord thy God with thy whole heart, and with thy whole soul, and with thy whole strength."]]},"Exodus 12:13":{"tr":[[13,"Bulunduğunuz evlerin üzerindeki kan sizin için bir işaret olacak. Kanı görünce üzerinizden geçeceğim. Mısır’ı cezalandırdığımda sizi yok edecek bir bela gelmeyecek."]],"en":[[13,"And the blood shall be unto you for a sign in the houses where you shall be: and I shall see the blood, and shall pass over you: and the plague shall not be upon you to destroy you, when I shall strike the land of Egypt."]]},"Exodus 32:28":{"tr":[[28,"Levililer Musa’nın dediği gibi yaptı. O gün halktan yaklaşık üç bin kişi öldü."]],"en":[[28,"And the sons of Levi did according to the words of Moses, and there were slain that day about three and twenty thousand men."]]},"Exodus 33:20":{"tr":[[20,"Rab, “Yüzümü göremezsin” dedi, “çünkü beni gören yaşayamaz.”"]],"en":[[20,"And again he said: Thou canst not see my face: for man shall not see me and live."]]},"Exodus 3:2-6":{"tr":[[2,"Rab’bin meleği ona bir çalının ortasında alev içinde göründü. Musa baktı, çalı yanıyor ama tükenmiyordu."],[3,"Musa, “Gidip bu olağanüstü görüntüye bakayım” dedi, “çalı neden yanıp tükenmiyor?”"],[4,"Rab onun bakmak için yaklaştığını görünce çalının ortasından ona seslendi: “Musa! Musa!” Musa, “Buradayım” dedi."],[5,"Tanrı, “Daha fazla yaklaşma” dedi, “çarıklarını çıkar, çünkü durduğun yer kutsal topraktır.”"],[6,"Sonra şöyle dedi: “Ben babanın Tanrısı’yım, İbrahim’in Tanrısı, İshak’ın Tanrısı ve Yakup’un Tanrısı’yım.” Musa yüzünü örttü, çünkü Tanrı’ya bakmaktan korkuyordu."]],"en":[[2,"And the Lord appeared to him in a flame of fire out of the midst of a bush: and he saw that the bush was on fire and was not burnt."],[3,"And Moses said: I will go and see this great sight, why the bush is not burnt."],[4,"And when the Lord saw that he went forward to see, he called to him out of the midst of the bush, and said: Moses, Moses. And he answered: Here I am."],[5,"And he said: Come not nigh hither, put off the shoes from thy feet: for the place whereon thou standest is holy ground."],[6,"And he said: I am the God of thy father, the God of Abraham, the God of Isaac, and the God of Jacob. Moses hid his face: for he durst not look at God."]]},"Genesis 18:1-2,22":{"tr":[[1,"Rab, Mamre meşeliğinde İbrahim’e göründü. İbrahim günün sıcağında çadırının girişinde oturuyordu."],[2,"Başını kaldırıp baktı ve yakınında üç adamın durduğunu gördü. Onları görünce çadırının girişinden karşılamaya koştu ve yere kadar eğildi."],[22,"Adamlar oradan ayrılıp Sodom’a doğru gittiler. İbrahim ise Rab’bin önünde durmaya devam etti."]],"en":[[1,"And the Lord appeared to him in the vale of Mambre as he was sitting at the door of his tent, in the very heat of the day."],[2,"And when he had lifted up his eyes, there appeared to him three men standing near him: and as soon as he saw them he ran to meet them from the door of his tent, and adored down to the ground."],[22,"And they turned themselves from thence, and went their way to Sodom: but Abraham as yet stood before the Lord."]]},"Genesis 19:1":{"tr":[[1,"İki melek akşamleyin Sodom’a vardı. Lut kentin kapısında oturuyordu. Onları görünce karşılamaya kalktı ve yüzüstü yere eğildi."]],"en":[[1,"And the two angels came to Sodom in the evening, and Lot was sitting in the gate of the city. And seeing them, he rose up and went to meet them: and worshipped prostrate to the ground,"]]},"Genesis 45:4":{"tr":[[4,"Yusuf kardeşlerine, “Lütfen bana yaklaşın” dedi. Yaklaştılar. Yusuf, “Ben Mısır’a sattığınız kardeşiniz Yusuf’um” dedi."]],"en":[[4,"And he said mildly to them: Come nearer to me. And when they were come near him, he said: I am Joseph, your brother, whom you sold into Egypt."]]},"Genesis 48:15-16":{"tr":[[15,"Yakup Yusuf’u kutsayarak şöyle dedi: “Atalarım İbrahim’in ve İshak’ın önünde yürüdüğü Tanrı, bugüne dek bütün yaşamım boyunca bana çobanlık eden Tanrı,"],[16,"beni her kötülükten kurtaran melek bu çocukları kutsasın. Adım, atalarım İbrahim’in ve İshak’ın adı onlarla yaşasın. Yeryüzünde çoğalsınlar.”"]],"en":[[15,"And Jacob blessed the sons of Joseph, and said: God, in whose sight my fathers Abraham and Isaac walked, God that feedeth me from my youth until this day;"],[16,"The angel that delivereth me from all evils, bless these boys: and let my name be called upon them, and the names of my fathers Abraham, and Isaac, and may they grow into a multitude upon the earth."]]},"Genesis 50:20":{"tr":[[20,"Siz bana kötülük düşündünüz, ama Tanrı bugün olduğu gibi birçok insanın hayatını kurtarmak için onu iyiliğe çevirdi."]],"en":[[20,"You thought evil against me: but God turned it into good, that he might exalt me, as at present you see, and might save many people."]]},"Haggai 2:23":{"tr":[[23,"Her Şeye Egemen Rab diyor ki: “O gün seni, kulum Şealtiel oğlu Zerubbabil, alacağım ve seni mühür yüzüğü gibi yapacağım. Çünkü seni ben seçtim.” Her Şeye Egemen Rab böyle diyor."]],"en":[[23,"In that day, saith the Lord of hosts, I will take thee, O Zorobabel the son of Salathiel, my servant, saith the Lord, and will make thee as a signet, for I have chosen thee, saith the Lord of hosts."]]},"Haggai 2:9":{"tr":[[9,"Her Şeye Egemen Rab diyor ki: “Bu tapınağın son görkemi ilkinden daha büyük olacak. Bu yere esenlik vereceğim.” Her Şeye Egemen Rab böyle diyor."]],"en":[[9,"Great shall be the glory of this last house more than of the first, saith the Lord of hosts: and in this place I will give peace, saith the Lord of hosts."]]},"Hosea 11:1":{"tr":[[1,"İsrail çocukken onu sevdim, oğlumu Mısır’dan çağırdım."]],"en":[[1,"As the morning passeth, so hath the king of Israel Israel was a child, and I loved him: and I called my son out of Egypt."]]},"Hosea 3:4-5":{"tr":[[4,"Çünkü İsrailliler uzun süre kralsız, öndersiz, kurbansız, dikili taşsız, efodsuz ve aile putları olmadan yaşayacak."],[5,"Sonra İsrailliler geri dönüp Tanrıları Rab’bi ve kralları Davut’u arayacaklar. Son günlerde titreyerek Rab’be ve O’nun iyiliğine yönelecekler."]],"en":[[4,"For the children of Israel shall sit many days without king, and without prince, and without sacrifice, and without altar, and without ephod, and without theraphim."],[5,"And after this the children of Israel shall return, and shall seek the Lord their God, and David their king: and they shall fear the Lord, and his goodness in the last days."]]},"Hosea 6:2":{"tr":[[2,"İki gün sonra bizi diriltecek, üçüncü gün bizi kaldıracak ve O’nun önünde yaşayacağız."]],"en":[[2,"He will revive us after two days: on the third day he will raise us up, and we shall live in his sight. We shall know, and we shall follow on, that we may know the Lord. His going forth is prepared as the morning light, and he will come to us as the early and the latter rain to the earth."]]},"Isaiah 10:21":{"tr":[[21,"Bir kalıntı, Yakup’tan arta kalanlar, güçlü Tanrı’ya dönecek."]],"en":[[21,"The remnant shall be converted, the remnant, I say, of Jacob, to the mighty God."]]},"Isaiah 11:1":{"tr":[[1,"İşay’ın kütüğünden bir filiz çıkacak, kökünden bir dal yetişip meyve verecek."]],"en":[[1,"And there shall come forth a rod out of the root of Jesse, and a flower shall rise up out of his root."]]},"Isaiah 11:6":{"tr":[[6,"Kurt kuzuyla birlikte yaşayacak, pars oğlakla birlikte yatacak. Buzağı, genç aslan ve besili hayvan bir arada olacak, küçük bir çocuk onları güdecek."]],"en":[[6,"The wolf shall dwell with the lamb: and the leopard shall lie down with the kid: the calf and the lion, and the sheep shall abide together, and a little child shall lead them."]]},"Isaiah 1:11-15":{"tr":[[11,"Rab diyor ki: “Bunca kurbanınız bana ne? Yakmalık koçlarınızdan, besili hayvanlarınızın yağından bıktım. Boğaların, kuzuların, tekelerin kanından hoşlanmıyorum."],[12,"Huzuruma çıkmaya geldiğinizde avlularımı çiğnemenizi sizden kim istedi?"],[13,"Artık boş sunular getirmeyin. Buhurunuz bana iğrenç geliyor. Yeni ay, Şabat, toplantılar... Kötülükle karışmış kutsal toplantılara dayanamıyorum."],[14,"Yeni ay törenlerinizden, bayramlarınızdan nefret ediyorum. Bana yük oldular, onları taşımaktan yoruldum."],[15,"Ellerinizi açtığınızda gözlerimi sizden kaçıracağım. Ne kadar dua ederseniz edin dinlemeyeceğim. Elleriniz kan dolu."]],"en":[[11,"To what purpose do you offer me the multitude of your victims, saith the Lord? I am full, I desire not holocausts of rams, and fat of fatlings, and blood of calves, and lambs, and buck goats."],[12,"When you came to appear before me, who required these things at your hands, that you should walk in my courts?"],[13,"Offer sacrifice no more in vain: incense is an abomination to me. The new moons, and the sabbaths, and other festivals I will not abide, your assemblies are wicked."],[14,"My soul hateth your new moons, and your solemnities: they are become troublesome to me, I am weary of bearing them."],[15,"And when you stretch forth your hands, I will turn away my eyes from you: and when you multiply prayer, I will not hear: for your hands are full of blood."]]},"Isaiah 2:4":{"tr":[[4,"Uluslar arasında yargıçlık edecek, birçok halkın davasına bakacak. Kılıçlarını dövüp saban demiri, mızraklarını bağ bıçağı yapacaklar. Ulus ulusa kılıç kaldırmayacak, artık savaşı öğrenmeyecekler."]],"en":[[4,"And he shall judge the Gentiles, and rebuke many people: and they shall turn their swords into ploughshares, and their spears into sickles: nation shall not lift up sword against nation, neither shall they be exercised any more to war."]]},"Isaiah 41:8":{"tr":[[8,"“Ama sen, ey kulum İsrail, seçtiğim Yakup, dostum İbrahim’in soyu,"]],"en":[[8,"But thou Israel, art my servant, Jacob whom I have chosen, the seed of Abraham my friend:"]]},"Isaiah 45:23":{"tr":[[23,"Kendi adıma ant içtim, ağzımdan doğrulukla çıkan söz geri dönmeyecek: Her diz önümde çökecek, her dil benim adımla ant içecek."]],"en":[[23,"I have sworn by myself, the word of justice shall go out of my mouth, and shall not return:"]]},"Isaiah 49:5-6":{"tr":[[5,"Yakup’u kendisine geri getirmek, İsrail’i kendi yanında toplamak için beni ana rahminde kulu olarak biçimlendiren Rab şimdi konuşuyor. Rab’bin gözünde değerliyim, Tanrım benim gücüm oldu."],[6,"Rab diyor ki: “Yakup’un oymaklarını yeniden ayağa kaldırman, İsrail’den sağ kalanları geri getirmen için kulum olman az bir şey. Seni ulusların ışığı yapacağım ki, kurtarışım dünyanın uçlarına ulaşsın.”"]],"en":[[5,"And now saith the Lord, that formed me from the womb to be his servant, that I may bring back Jacob unto him, and Israel will not be gathered together: and I am glorified in the eyes of the Lord, and my God is made my strength."],[6,"And he said: It is a small thing that thou shouldst be my servant to raise up the tribes of Jacob, and to convert the dregs of Israel. Behold, I have given thee to be the light of the Gentiles, that thou mayst be my salvation even to the farthest part of the earth."]]},"Isaiah 49:6":{"tr":[[6,"Rab diyor ki: “Yakup’un oymaklarını yeniden ayağa kaldırman, İsrail’den sağ kalanları geri getirmen için kulum olman az bir şey. Seni ulusların ışığı yapacağım ki, kurtarışım dünyanın uçlarına ulaşsın.”"]],"en":[[6,"And he said: It is a small thing that thou shouldst be my servant to raise up the tribes of Jacob, and to convert the dregs of Israel. Behold, I have given thee to be the light of the Gentiles, that thou mayst be my salvation even to the farthest part of the earth."]]},"Isaiah 50:1":{"tr":[[1,"Rab diyor ki: “Annenizi gönderdiğim boşanma belgesi nerede? Ya da sizi hangi alacaklıma sattım? İşte suçlarınız yüzünden satıldınız, isyanlarınız yüzünden anneniz gönderildi."]],"en":[[1,"Thus saith the Lord: What is this bill of the divorce of your mother, with which I have put her away? or who is my creditor, to whom I sold you: behold you are sold for your iniquities, and for your wicked deeds have I put your mother away."]]},"Isaiah 52:13":{"tr":[[13,"İşte kulum bilgece davranıp başarılı olacak. Yükseltilecek, yüceltilecek, çok yüce olacak."]],"en":[[13,"Behold my servant shall understand, he shall be exalted, and extolled, and shall be exceeding high."]]},"Isaiah 53:10":{"tr":[[10,"Ama onu ezmek, acı çektirmek Rab’bin isteğiydi. Canını suç sunusu olarak verdiğinde soyunu görecek, ömrü uzayacak. Rab’bin isteği onun eliyle gerçekleşecek."]],"en":[[10,"And the Lord was pleased to bruise him in infirmity: if he shall lay down his life for sin, he shall see a long-lived seed, and the will of the Lord shall be prosperous in his hand."]]},"Isaiah 53:10-11":{"tr":[[10,"Ama onu ezmek, acı çektirmek Rab’bin isteğiydi. Canını suç sunusu olarak verdiğinde soyunu görecek, ömrü uzayacak. Rab’bin isteği onun eliyle gerçekleşecek."],[11,"Canının çektiği acıdan sonra ışığı görüp hoşnut olacak. Doğru kulum, bilgisiyle birçoklarını aklayacak ve onların suçlarını yüklenecek."]],"en":[[10,"And the Lord was pleased to bruise him in infirmity: if he shall lay down his life for sin, he shall see a long-lived seed, and the will of the Lord shall be prosperous in his hand."],[11,"Because his soul hath laboured, he shall see and be filled: by his knowledge shall this my just servant justify many, and he shall bear their iniquities."]]},"Isaiah 53:12":{"tr":[[12,"Bu yüzden ona büyüklerle birlikte pay vereceğim, güçlülerle birlikte ganimeti paylaşacak. Çünkü canını ölüme döktü ve suçlularla bir sayıldı. Birçoklarının günahını yüklendi ve suçlular için aracılık etti."]],"en":[[12,"Therefore will I distribute to him very many, and he shall divide the spoils of the strong, because he hath delivered his soul unto death, and was reputed with the wicked: and he hath borne the sins of many, and hath prayed for the transgressors."]]},"Isaiah 53:5":{"tr":[[5,"O bizim isyanlarımız yüzünden yaralandı, suçlarımız yüzünden ezildi. Esenliğimiz için gelen ceza ona verildi, onun yaralarıyla şifa bulduk."]],"en":[[5,"But he was wounded for our iniquities, he was bruised for our sins: the chastisement of our peace was upon him, and by his bruises we are healed."]]},"Isaiah 53:8":{"tr":[[8,"Baskıyla ve yargıyla alınıp götürüldü. Kuşağından kim düşündü ki, halkımın isyanı yüzünden vuruldu ve yaşayanlar diyarından koparıldı?"]],"en":[[8,"He was taken away from distress, and from judgment: who shall declare his generation? because he is cut off out of the land of the living: for the wickedness of my people have I struck him."]]},"Isaiah 53:8-9":{"tr":[[8,"Baskıyla ve yargıyla alınıp götürüldü. Kuşağından kim düşündü ki, halkımın isyanı yüzünden vuruldu ve yaşayanlar diyarından koparıldı?"],[9,"Hiç zorbalık etmemiş, ağzından hile çıkmamış olsa da mezarı kötülerle birlikte yapıldı, öldüğünde bir zenginin yanına konuldu."]],"en":[[8,"He was taken away from distress, and from judgment: who shall declare his generation? because he is cut off out of the land of the living: for the wickedness of my people have I struck him."],[9,"And he shall give the ungodly for his burial, and the rich for his death: because he hath done no iniquity, neither was there deceit in his mouth."]]},"Isaiah 53:9":{"tr":[[9,"Hiç zorbalık etmemiş, ağzından hile çıkmamış olsa da mezarı kötülerle birlikte yapıldı, öldüğünde bir zenginin yanına konuldu."]],"en":[[9,"And he shall give the ungodly for his burial, and the rich for his death: because he hath done no iniquity, neither was there deceit in his mouth."]]},"Isaiah 59:2":{"tr":[[2,"Ama sizi Tanrınız’dan ayıran suçlarınızdır. O’nun yüzünü sizden gizleyen, sizi duymamasına neden olan günahlarınızdır."]],"en":[[2,"But your iniquities have divided between you and your God, and your sins have hid his face from you that he should not hear."]]},"Isaiah 7:14":{"tr":[[14,"Bu yüzden Rab size kendisi bir işaret verecek: İşte kız gebe kalıp bir oğul doğuracak ve adını İmmanuel koyacak."]],"en":[[14,"Therefore the Lord himself shall give you a sign. Behold a virgin shall conceive, and bear a son, and his name shall be called Emmanuel."]]},"Isaiah 9:6":{"tr":[[6,"Çünkü bize bir çocuk doğdu, bize bir oğul verildi. Egemenlik onun omuzlarında olacak. Adı Harika Öğütçü, Güçlü Tanrı, Ebedi Baba, Esenlik Önderi olacak."]],"en":[[6,"For a CHILD IS BORN to us, and a son is given to us, and the government is upon his shoulder: and his name shall be called, Wonderful, Counsellor, God the Mighty, the Father of the world to come, the Prince of Peace."]]},"Jeremiah 22:24":{"tr":[[24,"Rab diyor ki: “Varlığım hakkı için, Yahuda Kralı Yehoyakim oğlu Konya sağ elimde mühür yüzüğü olsa bile, seni oradan çıkarıp atardım."]],"en":[[24,"As I live, saith the Lord, if Jechonias the son of Joakim the king of Juda were a ring on my right hand, I would pluck him thence."]]},"Jeremiah 22:30":{"tr":[[30,"Rab diyor ki: “Bu adamı çocuksuz biri olarak, ömrü boyunca başarılı olamayacak biri olarak yazın. Çünkü soyundan hiç kimse başarılı olup Davut’un tahtına oturmayacak, Yahuda’yı yönetmeyecek.”"]],"en":[[30,"Thus saith the Lord: Write this man barren, a man that shall not prosper in his days: for there shall not be a man of his seed that shall sit upon the throne of David, and have power any more in Juda."]]},"Jeremiah 23:5":{"tr":[[5,"Rab diyor ki: “İşte, Davut için doğru bir Filiz çıkaracağım günler geliyor. O kral olarak bilgece egemenlik sürecek, ülkede adaleti ve doğruluğu sağlayacak."]],"en":[[5,"Behold the days come, saith the Lord, and I will raise up to David a just branch: and a king shall reign, and shall be wise, and shall execute judgement and justice in the earth."]]},"Jeremiah 23:5-6":{"tr":[[5,"Rab diyor ki: “İşte, Davut için doğru bir Filiz çıkaracağım günler geliyor. O kral olarak bilgece egemenlik sürecek, ülkede adaleti ve doğruluğu sağlayacak."],[6,"Onun günlerinde Yahuda kurtulacak, İsrail güvenlik içinde yaşayacak. Onun adı şu olacak: Rab Doğruluğumuzdur."]],"en":[[5,"Behold the days come, saith the Lord, and I will raise up to David a just branch: and a king shall reign, and shall be wise, and shall execute judgement and justice in the earth."],[6,"In those days shall Juda be saved, and Israel shall dwell confidently: and this is the name that they shall call him: the Lord our just one."]]},"Jeremiah 31:31-33":{"tr":[[31,"Rab diyor ki: “İşte, İsrail halkıyla ve Yahuda halkıyla yeni bir antlaşma yapacağım günler geliyor."],[32,"Bu antlaşma, atalarını elinden tutup Mısır’dan çıkardığım gün onlarla yaptığım antlaşmaya benzemeyecek. Ben onların kocası olduğum halde, onlar antlaşmamı bozdular.” Rab böyle diyor."],[33,"Rab diyor ki: “O günlerden sonra İsrail halkıyla yapacağım antlaşma şu olacak: Yasamı içlerine koyacak, yüreklerine yazacağım. Ben onların Tanrısı olacağım, onlar da benim halkım olacak."]],"en":[[31,"Behold the days shall come, saith the Lord, and I will make a new covenant with the house of Israel, and with the house of Juda:"],[32,"Not according to the covenant which I made with their fathers, in the day that I took them by the hand to bring them out of the land of Egypt: the covenant which they made void, and I had dominion over them, saith the Lord."],[33,"But this shall be the covenant that I will make with the house of Israel, after those days, saith the Lord: I will give my law in their bowels, and I will write it in their heart: and I will be their God, and they shall be my people."]]},"John 10:18":{"tr":[[18,"Canımı kimse benden alamaz, ben onu kendiliğimden veriyorum. Onu vermeye de geri almaya da yetkim var. Bu buyruğu Babam’dan aldım.”"]],"en":[[18,"No man taketh it away from me: but I lay it down of myself, and I have power to lay it down: and I have power to take it up again. This commandment have I received of my Father."]]},"John 1:1,14":{"tr":[[1,"Başlangıçta Söz vardı. Söz Tanrı’yla birlikteydi ve Söz Tanrı’ydı."],[14,"Söz insan oldu, lütuf ve gerçekle dolu olarak aramızda yaşadı. Biz O’nun yüceliğini, Baba’dan gelen biricik Oğul’un yüceliğini gördük."]],"en":[[1,"In the beginning was the Word, and the Word was with God, and the Word was God."],[14,"And the Word was made flesh, and dwelt among us, (and we saw his glory, the glory as it were of the only begotten of the Father,) full of grace and truth."]]},"John 4:22":{"tr":[[22,"Siz bilmediğinize tapıyorsunuz, biz bildiğimize tapıyoruz. Çünkü kurtuluş Yahudilerdendir."]],"en":[[22,"You adore that which you know not: we adore that which we know; for salvation is of the Jews."]]},"Leviticus 17:11":{"tr":[[11,"Çünkü bedenin canı kandadır. Canlarınızın kefareti için onu size sunakta verdim. Kefareti sağlayan, candır, yani kandır."]],"en":[[11,"Because the life of the flesh is in the blood: and I have given it to you, that you may make atonement with it upon the altar for your souls, and the blood may be for an expiation of the soul."]]},"Leviticus 19:18":{"tr":[[18,"Öç almayacaksın, halkının çocuklarına kin beslemeyeceksin. Komşunu kendin gibi seveceksin. Ben Rab’bim."]],"en":[[18,"Seek not revenge, nor be mindful of the injury of thy citizens. Thou shalt love thy friend as thyself. I am the Lord."]]},"Luke 22:20":{"tr":[[20,"Yemekten sonra kâseyi de aynı şekilde aldı ve şöyle dedi: “Bu kâse, sizin için akıtılan kanımla yapılan yeni antlaşmadır.”"]],"en":[[20,"In like manner the chalice also, after he had supped, saying: This is the chalice, the new testament in my blood, which shall be shed for you."]]},"Luke 23:34":{"tr":[[34,"İsa, “Baba, onları bağışla, çünkü ne yaptıklarını bilmiyorlar” dedi. Askerler kura çekerek O’nun giysilerini aralarında paylaştılar."]],"en":[[34,"And Jesus said: Father, forgive them, for they know not what they do. But they, dividing his garments, cast lots."]]},"Luke 2:21":{"tr":[[21,"Çocuğun sünnet edileceği sekizinci gün gelince, ona İsa adı verildi. Bu, daha ana rahmine düşmeden önce meleğin verdiği addı."]],"en":[[21,"And after eight days were accomplished, that the child should be circumcised, his name was called JESUS, which was called by the angel, before he was conceived in the womb."]]},"Luke 2:22-24":{"tr":[[22,"Musa’nın Yasası’na göre arınma günleri dolunca Yusuf ile Meryem, çocuğu Rab’be sunmak için Kudüs’e götürdüler."],[23,"Rab’bin Yasası’nda, “İlk doğan her erkek çocuk Rab’be adanmış sayılacak” diye yazılmıştır."],[24,"Ayrıca Rab’bin Yasası’nda söylendiği gibi, “bir çift kumru ya da iki güvercin yavrusu” kurban etmeye gittiler."]],"en":[[22,"And after the days of her purification, according to the law of Moses, were accomplished, they carried him to Jerusalem, to present him to the Lord:"],[23,"As it is written in the law of the Lord: Every male opening the womb shall be called holy to the Lord:"],[24,"And to offer a sacrifice, according as it is written in the law of the Lord, a pair of turtledoves, or two young pigeons:"]]},"Luke 2:25":{"tr":[[25,"Kudüs’te Simeon adında bir adam vardı. Doğru ve dindar biriydi, İsrail’in avuntusunu bekliyordu. Kutsal Ruh onun üzerindeydi."]],"en":[[25,"And behold there was a man in Jerusalem named Simeon, and this man was just and devout, waiting for the consolation of Israel; and the Holy Ghost was in him."]]},"Luke 2:30-32":{"tr":[[30,"Çünkü gözlerim senin kurtarışını gördü."],[31,"Sen onu bütün halkların önünde hazırladın."],[32,"O, ulusları aydınlatacak bir ışık ve halkın İsrail’in yüceliğidir.”"]],"en":[[30,"Because my eyes have seen thy salvation,"],[31,"Which thou hast prepared before the face of all peoples:"],[32,"A light to the revelation of the Gentiles, and the glory of thy people Israel."]]},"Luke 3:31":{"tr":[[31,"Melea’nın oğlu, Menna’nın oğlu, Mattata’nın oğlu, Natan’ın oğlu, Davut’un oğlu,"]],"en":[[31,"Who was of Melea, who was of Menna, who was of Mathatha, who was of Nathan, who was of David,"]]},"Malachi 3:1":{"tr":[[1,"“İşte, önümden yolu hazırlasın diye ulağımı gönderiyorum. Aradığınız Rab ansızın tapınağına gelecek. Özlediğiniz antlaşma ulağı geliyor.” Her Şeye Egemen Rab böyle diyor."]],"en":[[1,"Behold I send my angel, and he shall prepare the way before my face. And presently the Lord, whom you seek, and the angel of the testament, whom you desire, shall come to his temple. Behold he cometh, saith the Lord of hosts."]]},"Mark 14:24":{"tr":[[24,"İsa onlara, “Bu, birçokları için akıtılan, antlaşmanın kanıdır” dedi."]],"en":[[24,"And he said to them: This is my blood of the new testament, which shall be shed for many."]]},"Mark 3:4":{"tr":[[4,"Sonra onlara, “Şabat günü iyilik yapmak mı uygun, kötülük yapmak mı? Can kurtarmak mı, öldürmek mi?” diye sordu. Ama onlar sustular."]],"en":[[4,"And he saith to them: Is it lawful to do good on the sabbath days, or to do evil? to save life, or to destroy? But they held their peace."]]},"Matthew 23:39":{"tr":[[39,"Size şunu söyleyeyim: ‘Rab’bin adıyla gelene övgüler olsun!’ diyeceğiniz zamana dek beni bir daha görmeyeceksiniz.”"]],"en":[[39,"For I say to you, you shall not see me henceforth till you say: Blessed is he that cometh in the name of the Lord."]]},"Matthew 27:46":{"tr":[[46,"Saat üçe doğru İsa yüksek sesle, “Eli, Eli, lema şevaktani?” yani “Tanrım, Tanrım, beni neden bıraktın?” diye haykırdı."]],"en":[[46,"And about the ninth hour Jesus cried with a loud voice, saying: Eli, Eli, lamma sabacthani? that is, My God, my God, why hast thou forsaken me?"]]},"Matthew 2:15":{"tr":[[15,"Hirodes ölünceye dek orada kaldı. Böylece Rab’bin peygamber aracılığıyla söylediği şu söz gerçekleşti: “Oğlumu Mısır’dan çağırdım.”"]],"en":[[15,"That it might be fulfilled which the Lord spoke by the prophet, saying: Out of Egypt have I called my son."]]},"Matthew 2:23":{"tr":[[23,"Nasıra denen bir kente gelip oraya yerleşti. Böylece peygamberler aracılığıyla, “O Nasıralı diye anılacak” diye söylenen söz gerçekleşti."]],"en":[[23,"And coming he dwelt in a city called Nazareth: that it might be fulfilled which was said by prophets: That he shall be called a Nazarene."]]},"Matthew 4:1-11":{"tr":[[1,"Sonra Ruh İsa’yı, iblis tarafından sınanmak üzere çöle götürdü."],[2,"İsa kırk gün kırk gece oruç tuttu, sonunda acıktı."],[3,"Sınayan ona yaklaşıp, “Tanrı’nın Oğlu’ysan, söyle şu taşlar ekmek olsun” dedi."],[4,"İsa şöyle karşılık verdi: “‘İnsan yalnız ekmekle yaşamaz, Tanrı’nın ağzından çıkan her sözle yaşar’ diye yazılmıştır.”"],[5,"Sonra iblis İsa’yı kutsal kente götürdü ve Tapınağın en yüksek yerine çıkardı."],[6,"Ona, “Tanrı’nın Oğlu’ysan kendini aşağı at” dedi. “Çünkü şöyle yazılmıştır: ‘Senin için meleklerine buyruk verecek. Ayağın bir taşa çarpmasın diye seni elleri üzerinde taşıyacaklar.’”"],[7,"İsa ona, “‘Tanrın Rab’bi sınamayacaksın’ diye de yazılmıştır” dedi."],[8,"İblis yine İsa’yı çok yüksek bir dağa çıkardı ve ona dünyanın bütün krallıklarını ve görkemini gösterdi."],[9,"“Yere kapanıp bana taparsan bütün bunları sana vereceğim” dedi."],[10,"İsa ona şöyle dedi: “Çekil git, Şeytan! Çünkü ‘Tanrın Rab’be tapacak, yalnız O’na kulluk edeceksin’ diye yazılmıştır.”"],[11,"Bunun üzerine iblis onu bıraktı. Melekler gelip İsa’ya hizmet etti."]],"en":[[1,"Then Jesus was led by the spirit into the desert, to be tempted by the devil."],[2,"And when he had fasted forty days and forty nights, afterwards he was hungry."],[3,"And the tempter coming said to him: If thou be the Son of God, command that these stones be made bread."],[4,"Who answered and said: It is written, Not in bread alone doth man live, but in every word that proceedeth from the mouth of God."],[5,"Then the devil took him up into the holy city, and set him upon the pinnacle of the temple,"],[6,"And said to him: If thou be the Son of God, cast thyself down, for it is written: That he hath given his angels charge over thee, and in their hands shall they bear thee up, lest perhaps thou dash thy foot against a stone."],[7,"Jesus said to him: It is written again: Thou shalt not tempt the Lord thy God."],[8,"Again the devil took him up into a very high mountain, and shewed him all the kingdoms of the world, and the glory of them,"],[9,"And said to him: All these will I give thee, if falling down thou wilt adore me."],[10,"Then Jesus saith to him: Begone, Satan: for it is written, The Lord thy God shalt thou adore, and him only shalt thou serve."],[11,"Then the devil left him; and behold angels came and ministered to him."]]},"Matthew 5:17":{"tr":[[17,"Kutsal Yasa’yı ya da peygamberlerin sözlerini geçersiz kılmak için geldiğimi sanmayın. Ben bunları geçersiz kılmaya değil, tamamlamaya geldim."]],"en":[[17,"Do not think that I am come to destroy the law, or the prophets. I am not come to destroy, but to fulfill."]]},"Matthew 5:21-28":{"tr":[[21,"Atalarımıza, ‘Adam öldürmeyeceksin, öldüren yargılanacak’ dendiğini duydunuz."],[22,"Ama ben size diyorum ki, kardeşine öfkelenen herkes yargılanacak. Kardeşine ‘Aptal!’ diyen Yüksek Kurul’a hesap verecek. ‘Ahmak!’ diyen ise cehennem ateşini hak edecek."],[23,"Bu nedenle, sunağa adağını getirirken kardeşinin sana karşı bir şikâyeti olduğunu hatırlarsan,"],[24,"adağını orada, sunağın önünde bırak. Önce gidip kardeşinle barış, sonra gelip adağını sun."],[25,"Seninle davalı olan hasımla daha yoldayken çabuk anlaş. Yoksa o seni yargıca, yargıç da görevliye teslim eder ve hapse atılırsın."],[26,"Sana doğrusunu söyleyeyim, son kuruşuna kadar ödemedikçe oradan çıkamazsın."],[27,"‘Zina etmeyeceksin’ dendiğini duydunuz."],[28,"Ama ben size diyorum ki, bir kadına şehvetle bakan herkes, yüreğinde onunla zina etmiş olur."]],"en":[[21,"You have heard that it was said to them of old: Thou shalt not kill. And whosoever shall kill shall be in danger of the judgment."],[22,"But I say to you, that whosoever is angry with his brother, shall be in danger of the judgment. And whosoever shall say to his brother, Raca, shall be in danger of the council. And whosoever shall say, Thou Fool, shall be in danger of hell fire."],[23,"If therefore thou offer thy gift at the altar, and there thou remember that thy brother hath any thing against thee;"],[24,"Leave there thy offering before the altar, and go first to be reconciled to thy brother: and then coming thou shalt offer thy gift."],[25,"Be at agreement with thy adversary betimes, whilst thou art in the way with him: lest perhaps the adversary deliver thee to the judge, and the judge deliver thee to the officer, and thou be cast into prison."],[26,"Amen I say to thee, thou shalt not go out from thence till thou repay the last farthing."],[27,"You have heard that it was said to them of old: Thou shalt not commit adultery."],[28,"But I say to you, that whosoever shall look on a woman to lust after her, hath already committed adultery with her in his heart."]]},"Philippians 2:10-11":{"tr":[[10,"öyle ki, İsa’nın adı anıldığında gökte, yeryüzünde ve yer altında her diz çöksün,"],[11,"ve her dil, Baba Tanrı’nın yüceliği için İsa Mesih’in Rab olduğunu açıkça söylesin."]],"en":[[10,"That in the name of Jesus every knee should bow, of those that are in heaven, on earth, and under the earth:"],[11,"And that every tongue should confess that the Lord Jesus Christ is in the glory of God the Father."]]},"Psalm 16:10":{"tr":[[10,"Çünkü canımı ölüler diyarına bırakmayacaksın, sadık kulunun çürümesine izin vermeyeceksin."]],"en":[[10,"Because thou wilt not leave my soul in hell; nor wilt then give thy holy one to see corruption."]]},"Psalm 22:27":{"tr":[[27,"Dünyanın bütün uçları hatırlayıp Rab’be dönecek, ulusların bütün aileleri O’nun önünde eğilecek."]],"en":[[27,"All the ends of the earth shall remember, and shall be converted to the Lord: And all the kindreds of the Gentiles shall adore in his sight."]]},"Psalm 22:7-8,15-18":{"tr":[[7,"Beni gören herkes benimle alay ediyor, dudak bükerek başlarını sallıyorlar:"],[8,"“Rab’be güvendi, kurtarsın onu! Madem onu seviyor, o kurtarsın!”"],[15,"Gücüm bir çömlek parçası gibi kurudu, dilim damağıma yapıştı. Beni ölümün toprağına bıraktın."],[16,"Köpekler çevremi sardı, kötüler topluluğu beni kuşattı. Ellerimi ve ayaklarımı deldiler."],[17,"Bütün kemiklerimi sayabiliyorum. Onlar bakıyor, gözlerini bana dikiyorlar."],[18,"Giysilerimi aralarında paylaşıyor, elbisem için kura çekiyorlar."]],"en":[[7,"All they that saw me have laughed me to scorn: they have spoken with the lips, and wagged the head."],[8,"He hoped in the Lord, let him deliver him: let him save him, seeing he delighteth in him."],[15,"My strength is dried up like a potsherd, and my tongue hath cleaved to my jaws: and thou hast brought me down into the dust of death."],[16,"For many dogs have encompassed me: the council of the malignant hath besieged me. They have dug my hands and feet."],[17,"They have numbered all my bones. And they have looked and stared upon me."],[18,"They parted my garments amongst them; and upon my vesture they cast lots."]]},"Psalm 51:17-19":{"tr":[[17,"Tanrı’nın istediği kurban kırık bir ruhtur. Ey Tanrı, kırık ve pişman bir yüreği küçümsemezsin."],[18,"Lütfunla Siyon’a iyilik et, Kudüs’ün surlarını yeniden yap."],[19,"O zaman doğru kurbanlardan, yakmalık sunulardan, tümüyle yakılan sunulardan hoşnut olacaksın. O zaman sunağına boğalar sunulacak."]],"en":[[17,"A sacrifice to God is an afflicted spirit: a contrite and humbled heart, O God, thou wilt not despise."],[18,"Deal favourably, O Lord, in thy good will with Sion; that the walls of Jerusalem may be built up."],[19,"Then shalt thou accept the sacrifice of justice, oblations and whole burnt offerings: then shall they lay calves upon thy altar."]]},"Romans 11:29":{"tr":[[29,"Çünkü Tanrı’nın armağanları ve çağrısı geri alınmaz."]],"en":[[29,"For the gifts and the calling of God are without repentance."]]},"Romans 7:12":{"tr":[[12,"Demek ki Kutsal Yasa kutsaldır. Buyruk da kutsal, doğru ve iyidir."]],"en":[[12,"Wherefore the law indeed is holy, and the commandment holy, and just, and good."]]},"Tobit 12:9":{"tr":[[9,"Çünkü sadaka ölümden kurtarır ve her günahtan arındırır. Sadaka veren ve doğruluk yapanlar yaşamla doyacaklar."]],"en":[[9,"For alms delivereth from death, and the same is that which purgeth away sins, and maketh to find mercy and life everlasting."]]},"Zechariah 12:10":{"tr":[[10,"Davut soyunun ve Kudüs’te yaşayanların üzerine lütuf ve yakarış ruhu dökeceğim. Deldikleri bana bakacaklar. Biricik oğlu için yas tutan biri gibi onun için yas tutacaklar, ilk oğlu için acı acı ağlayan biri gibi onun için acı acı ağlayacaklar."]],"en":[[10,"And I will pour out upon the house of David, and upon the inhabitants of Jerusalem, the spirit of grace, and of prayers: and they shall look upon me, whom they have pierced: and they shall mourn for him as one mourneth for an only son, and they shall grieve over him, as the manner is to grieve for the death of the firstborn."]]},"Zechariah 13:1":{"tr":[[1,"O gün Davut soyu ve Kudüs’te yaşayanlar için günahtan ve kirlilikten arındıracak bir pınar açılacak."]],"en":[[1,"In that day there shall be a fountain open to the house of David, and to the inhabitants of Jerusalem: for the washing of the sinner, and of the unclean woman."]]},"Zechariah 6:12":{"tr":[[12,"Ona şöyle de: Her Şeye Egemen Rab diyor ki: ‘İşte, adı Filiz olan adam! Bulunduğu yerde filizlenecek ve Rab’bin Tapınağı’nı yapacak."]],"en":[[12,"And thou shalt speak to him, saying: Thus saith the Lord of hosts, saying: BEHOLD A MAN, THE ORIENT IS HIS NAME: and under him shall he spring up, and shall build a temple to the Lord."]]},"Zechariah 9:9":{"tr":[[9,"Ey Siyon kızı, çok sevin! Ey Kudüs kızı, sevinçle bağır! İşte kralın sana geliyor. O doğru ve zafer sahibidir. Alçakgönüllüdür, bir eşeğe, eşek sıpasına binmiş olarak geliyor."]],"en":[[9,"Rejoice greatly, O daughter of Sion, shout for joy, O daughter of Jerusalem: BEHOLD THY KING will come to thee, the just and saviour: he is poor, and riding upon an ass, and upon a colt the foal of an ass."]]}};
